    pub fn insert_message(
        &self,
        message: &MessageRecord,
        client_request_id: Option<&str>,
        preview: Option<&str>,
        increment_unread: bool,
    ) -> Result<bool, StoreError> {
        self.insert_message_inner(message, client_request_id, preview, increment_unread, None)
    }

    /// B: message insert and its event_log row commit together. Only the
    /// receive main path passes an event; every other writer keeps
    /// insert_message.
    pub fn insert_message_with_event(
        &self,
        message: &MessageRecord,
        client_request_id: Option<&str>,
        preview: Option<&str>,
        increment_unread: bool,
        event: &EventLogWrite,
    ) -> Result<bool, StoreError> {
        self.insert_message_inner(
            message,
            client_request_id,
            preview,
            increment_unread,
            Some(event),
        )
    }

    fn insert_message_inner(
        &self,
        message: &MessageRecord,
        client_request_id: Option<&str>,
        preview: Option<&str>,
        increment_unread: bool,
        event: Option<&EventLogWrite>,
    ) -> Result<bool, StoreError> {
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        // Retention counts how long this machine has kept a row, so the
        // stored-at stamp reads our clock here and never a peer's claimed
        // time; the sweep deadline derives from the same clock when the
        // envelope's own start stamp is absent (§4.41).
        let stored_at = crate::link::now_ms();
        let inserted = transaction
            .execute(
                "INSERT OR IGNORE INTO messages(
                    id, account_id, conversation_id, direction, sender_id, sent_at, received_at,
                    stored_at, body, body_bytes, body_truncated, status, client_request_id,
                    quote_message_id, quote_snapshot, attachments_json, live_attachment_locators,
                    rich_json, edited_at, sender_name,
                    mentions_self, sticker_json, expire_seconds, expire_start_at, expire_at, server_guid, server_timestamp, author_aci
                 ) VALUES(?1, ?2, ?3, ?4, ?5, ?6, ?7, ?14, ?8, ?9, ?10, ?11, ?12, ?13, ?15, ?16, ?17, ?19, ?18, ?20, ?21, ?22, ?23, ?24, ?25, ?26, ?27, ?28)",
                params![
                    message.id,
                    message.account_id,
                    message.conversation_id,
                    message.direction,
                    message.sender_id,
                    message.sent_at as i64,
                    message.received_at.map(|v| v as i64),
                    message.text,
                    message.text_bytes.map(i64::from),
                    i64::from(message.text_truncated && !message.text_retrievable),
                    message.status,
                    client_request_id,
                    message.quote_message_id,
                    stored_at as i64,
                    message
                        .quote_snapshot
                        .as_ref()
                        .map(|quote| serde_json::to_string(quote).expect("quote snapshot json")),
                    (!message.attachments.is_empty()).then(|| {
                        serde_json::to_string(&message.attachments).expect("attachments json")
                    }),
                    // The receive envelope's transit pointer faces (contract
                    // 1.61), index-aligned with `attachments_json`; the
                    // host-facing descriptor stays byte-identical (v1 shape).
                    // An engine without the projection stores all-None faces
                    // (indistinguishable from NULL on the read face).
                    (!message.attachments.is_empty()).then(|| {
                        serde_json::to_string(
                            &message
                                .attachments
                                .iter()
                                .map(|descriptor| descriptor.locator.clone().unwrap_or_default())
                                .collect::<Vec<_>>(),
                        )
                        .expect("live attachment locators json")
                    }),
                    message.edited_at.map(|v| v as i64),
                    message
                        .rich
                        .as_ref()
                        .map(|rich| serde_json::to_string(rich).expect("rich json")),
                    message.sender_name,
                    i64::from(message.mentions_self),
                    message
                        .sticker
                        .as_ref()
                        .map(|sticker| serde_json::to_string(sticker).expect("sticker json")),
                    message.expire_seconds.map(|value| value as i64),
                    message.expire_start_at.map(|value| value as i64),
                    expire_deadline(message, stored_at).map(|value| value as i64),
                    message.server_guid,
                    message.server_timestamp.map(|value| value as i64),
                    message.author_aci,
                ],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        if inserted == 0 {
            // The row identity already landed (a live echo, a re-receive, or
            // a history-import row). The insert is `INSERT OR IGNORE`, so
            // the incoming descriptors were silently dropped; merge them into
            // the existing row's empty positions instead (post-relink repair:
            // the restored row may carry no descriptors while the live echo
            // does).
            Self::merge_attachment_faces_in(
                &transaction,
                &message.account_id,
                &message.id,
                &message.attachments,
            )?;
            transaction
                .commit()
                .map_err(|error| StoreError::Unavailable(Some(error)))?;
            return Ok(false);
        }
        // The @ badge rides the same transaction as the unread badge (contract
        // 1.29): an incoming row that mentions self bumps both counters or
        // neither, so a crash between them can never split the pair.
        // Contract 1.112 (§4.93): the ending never regresses — Signal
        // timestamps are per-sender clocks, so a delayed delivery (a peer
        // back from offline, a late mirror) can land a row OLDER than what
        // the conversation already shows; the preview and the timestamp move
        // together only when the new row is newer (the history backfill's
        // guard), while the unread counters stay unconditional (an old
        // message still deserves its badge).
        let conversation_updated = transaction
            .execute(
                "UPDATE conversations
                 SET last_message_preview=CASE
                       WHEN last_message_at IS NULL OR last_message_at < ?3 THEN ?2
                       ELSE last_message_preview END,
                     last_message_at=CASE
                       WHEN last_message_at IS NULL OR last_message_at < ?3 THEN ?3
                       ELSE last_message_at END,
                     unread_count = unread_count + ?4,
                     unread_mentions = unread_mentions + ?5
                 WHERE id=?1",
                params![
                    message.conversation_id,
                    preview,
                    message.sent_at as i64,
                    if increment_unread { 1 } else { 0 },
                    i64::from(increment_unread && message.mentions_self)
                ],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        if conversation_updated != 1 {
            return Err(StoreError::ConversationNotFound);
        }
        let account_updated = transaction
            .execute(
                "UPDATE accounts
                 SET last_message_at=CASE
                       WHEN last_message_at IS NULL OR last_message_at < ?2 THEN ?2
                       ELSE last_message_at END,
                     unread_count = unread_count + ?3
                 WHERE id=?1",
                params![
                    message.account_id,
                    message.sent_at as i64,
                    if increment_unread { 1 } else { 0 }
                ],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        if account_updated != 1 {
            return Err(StoreError::AccountNotFound);
        }
        if let Some(event) = event {
            append_event_log_on(
                &transaction,
                event.epoch,
                event.account_id.as_deref(),
                &event.event_type,
            )?;
        }
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(true)
    }

    /// Opening a chat: zero conversation unread and subtract from account total.
    pub fn clear_conversation_unread(
        &self,
        account_id: &str,
        conversation_id: &str,
    ) -> Result<u32, StoreError> {
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let prev: i64 = transaction
            .query_row(
                "SELECT unread_count FROM conversations WHERE id=?1 AND account_id=?2",
                params![conversation_id, account_id],
                |row| row.get(0),
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?
            .unwrap_or(0);
        if prev <= 0 {
            transaction
                .commit()
                .map_err(|error| StoreError::Unavailable(Some(error)))?;
            return Ok(0);
        }
        let conversation_updated = transaction
            .execute(
                // Contract 1.29: the @ badge clears with the unread badge —
                // opening the chat is reading it, exactly like the official
                // conversation open.
                "UPDATE conversations SET unread_count=0, unread_mentions=0
                 WHERE id=?1 AND account_id=?2",
                params![conversation_id, account_id],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        if conversation_updated != 1 {
            return Err(StoreError::ConversationNotFound);
        }
        let account_updated = transaction
            .execute(
                "UPDATE accounts
                 SET unread_count = CASE
                     WHEN unread_count > ?2 THEN unread_count - ?2
                     ELSE 0
                 END
                 WHERE id=?1",
                params![account_id, prev],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        if account_updated != 1 {
            return Err(StoreError::AccountNotFound);
        }
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(prev as u32)
    }

    /// The read-position watermark's local-first advance (B-27, 水位制): the
    /// read legs (`messages.markRead` / `messages.syncRead` prepare) stamp the
    /// watermark to the conversation's NEWEST incoming row's `sent_at` — the
    /// official `markConversationRead` flips local read state before any
    /// receipt rides, so the stamp never waits for upstream confirmation. A
    /// whole-conversation read with zero incoming rows leaves the watermark
    /// untouched (no newest row = no position to claim). Monotonic by
    /// construction: the max-fold never lowers a past watermark (a race with
    /// retention deleting the newest row must not rewind the read position).
    pub fn advance_read_watermark_latest(
        &self,
        account_id: &str,
        conversation_id: &str,
    ) -> Result<(), StoreError> {
        let conn = self.lock_conn()?;
        // MAX over an empty incoming set answers one NULL row — no newest
        // row means no position to claim, and the watermark (including its
        // absent NULL) stays untouched; a 0 would masquerade as "read
        // everything before the epoch".
        let newest: Option<i64> = conn
            .query_row(
                "SELECT MAX(sent_at) , delete_failed
                 FROM messages
                 WHERE account_id=?1 AND conversation_id=?2 AND direction='incoming'",
                params![account_id, conversation_id],
                |row| row.get(0),
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        if let Some(newest) = newest.filter(|value| *value > 0) {
            conn.execute(
                "UPDATE conversations
                 SET read_watermark_ms = MAX(COALESCE(read_watermark_ms, 0), ?3)
                 WHERE id=?2 AND account_id=?1",
                params![account_id, conversation_id, newest],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        }
        Ok(())
    }

    /// The read-position watermark's remote-read advance: the §4.81 read-sync
    /// receive folds the synced rows' newest `sent_at` into the watermark —
    /// reading on another linked device is a true read, the official sync
    /// converges the same state. Same monotonic max-fold as the local leg.
    pub fn advance_read_watermark_to(
        &self,
        account_id: &str,
        conversation_id: &str,
        sent_at: u64,
    ) -> Result<(), StoreError> {
        let conn = self.lock_conn()?;
        conn.execute(
            "UPDATE conversations
             SET read_watermark_ms = MAX(COALESCE(read_watermark_ms, 0), ?3)
             WHERE id=?2 AND account_id=?1",
            params![account_id, conversation_id, sent_at],
        )
        .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(())
    }

    /// The read-position watermark's message-granular advance (contract
    /// revision 1.216, §4.216 — the official `markConversationRead` with a
    /// message target): the read legs accept an optional `messageId` naming
    /// ONE row of the addressed account+conversation, and the watermark
    /// moves to that row's `sent_at` — not to the conversation's newest
    /// row. Same monotonic max-fold as the other write seams: an older
    /// target never rewinds the position.
    ///
    /// The lookup IS the target validation: a missing row, a row owned by
    /// another account/conversation, and a row with no honest clock
    /// (`sent_at <= 0`) all answer
    /// [`StoreError::ReadWatermarkTargetInvalid`] and leave the watermark
    /// untouched — the caller maps that to a deterministic INVALID_REQUEST,
    /// never a silent advance. The position itself is never echoed or
    /// logged (content-free diagnostics only).
    pub fn advance_read_watermark_to_message(
        &self,
        account_id: &str,
        conversation_id: &str,
        message_id: &str,
    ) -> Result<(), StoreError> {
        let conn = self.lock_conn()?;
        let sent_at: Option<i64> = conn
            .query_row(
                "SELECT sent_at FROM messages
                 WHERE id=?1 AND account_id=?2 AND conversation_id=?3",
                params![message_id, account_id, conversation_id],
                |row| row.get(0),
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let Some(sent_at) = sent_at.filter(|value| *value > 0) else {
            return Err(StoreError::ReadWatermarkTargetInvalid);
        };
        let updated = conn
            .execute(
                "UPDATE conversations
                 SET read_watermark_ms = MAX(COALESCE(read_watermark_ms, 0), ?3)
                 WHERE id=?2 AND account_id=?1",
                params![account_id, conversation_id, sent_at],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        // The message row's own FK names a conversation; a missing row here
        // can only mean the conversation was erased between the two
        // statements (account deletion races the read legs).
        if updated != 1 {
            return Err(StoreError::ConversationNotFound);
        }
        Ok(())
    }

    /// The spam-report token's latest-wins landing (reportSpam data plane):
    /// every envelope carrying `reportingToken` overwrites the conversation's
    /// stored copy — the official `conversation.reportingToken` shape. Absent
    /// never clears (only message cleanup owns the clear upstream; the
    /// connector never clears it — a stale token is at worst ignored by the
    /// server, a missing one cannot be invented).
    pub fn store_conversation_report_token(
        &self,
        account_id: &str,
        conversation_id: &str,
        token: &str,
    ) -> Result<(), StoreError> {
        let conn = self.lock_conn()?;
        conn.execute(
            "UPDATE conversations SET report_spam_token=?3 WHERE id=?2 AND account_id=?1",
            params![account_id, conversation_id, token],
        )
        .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(())
    }

    /// The conversation's stored spam-report token (reportSpam data plane):
    /// the report face attaches it to the upstream POST body — the official
    /// `addReportSpamJob` reads `conversation.reportingToken` the same way.
    /// Absent when no envelope ever carried one (or the row predates the
    /// column) — the report then rides without the key, matching the
    /// official `jsonData={token}` with undefined.
    pub fn conversation_report_token(
        &self,
        account_id: &str,
        conversation_id: &str,
    ) -> Result<Option<String>, StoreError> {
        let conn = self.lock_conn()?;
        // The row mapping itself must be Option<String>: `.optional()` only
        // answers the no-rows case, and a plain String target would fail
        // with InvalidColumnType on the NULL column (a conversation no
        // token-bearing envelope has landed yet) — the exact honest-absent
        // case this face exists to answer.
        let token = conn
            .query_row(
                "SELECT report_spam_token FROM conversations WHERE id=?1 AND account_id=?2",
                params![conversation_id, account_id],
                |row| row.get::<_, Option<String>>(0),
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(token.flatten())
    }

    /// Update one message's status. Returns the row after the write together
    /// with whether the status actually transitioned: an idempotent replay of
    /// the same terminal write reports `false`, so the service layer does not
    /// re-emit a status event for a no-op.
    pub fn update_message_status(
        &self,
        message_id: &str,
        status: &str,
        sent_at: Option<u64>,
    ) -> Result<Option<(MessageRecord, bool)>, StoreError> {
        // One transaction for the write and the read-back: two separate
        // lock/execute rounds let another writer flip the status in between,
        // so the returned (record, changed) pair could describe two different
        // writes — and the status event built from it would carry a status
        // this call never set. The transaction keeps the pair atomic.
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let changed = transaction
            .execute(
                "UPDATE messages SET status=?2, sent_at=COALESCE(?3, sent_at)
                 WHERE id=?1 AND status<>?2",
                params![message_id, status, sent_at.map(|v| v as i64)],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let record = transaction
            .query_row(
                "SELECT id, account_id, conversation_id, direction, sender_id, sent_at, received_at,
                        body, body_bytes, body_truncated, status, quote_message_id, client_request_id,
                        quote_snapshot, attachments_json, rich_json, edited_at, sender_name, mentions_self, delivered_at, read_at, admin_deleted, sticker_json, expire_seconds, expire_start_at, expire_at, server_guid, server_timestamp, viewed_at, send_outcomes_json, author_aci,is_erased,delete_failed
                 FROM messages WHERE id=?1",
                params![message_id],
                message_record_from_row,
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(record.map(|record| (record, changed == 1)))
    }

    /// Rearm exactly one failed outgoing row for a send retry (contract 1.31):
    /// the transition `failed -> pending` is the single guarded write — a row
    /// in any other state (or already rearmed by a concurrent retry) is left
    /// untouched and reported as `changed=false`, so a double-click retry or a
    /// status push that settled the row between guard and rearm can never arm
    /// two dispatches of the same message. Same transaction shape as
    /// `update_message_status`: one lock round for write + read-back.
    ///
    /// §4.123: a manual rearm also retires the automatic retry face. The
    /// official semantics make a manual retry a NEW job with its own 24 h
    /// window — if this manual attempt then fails again with an eligible
    /// error, the fresh enqueue stamps a fresh window anchor instead of
    /// inheriting the retired one. The automatic claim path flips the status
    /// in `claim_due_retries` and deliberately does NOT go through this face,
    /// so queue-driven retries keep their window.
    pub fn rearm_failed_message(
        &self,
        message_id: &str,
    ) -> Result<Option<(MessageRecord, bool)>, StoreError> {
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let changed = transaction
            .execute(
                "UPDATE messages SET status='pending', first_send_attempted_at=NULL,
                        retry_attempt_count=0, next_attempt_at=NULL
                 WHERE id=?1 AND status='failed'",
                params![message_id],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let record = transaction
            .query_row(
                "SELECT id, account_id, conversation_id, direction, sender_id, sent_at, received_at,
                        body, body_bytes, body_truncated, status, quote_message_id, client_request_id,
                        quote_snapshot, attachments_json, rich_json, edited_at, sender_name, mentions_self, delivered_at, read_at, admin_deleted, sticker_json, expire_seconds, expire_start_at, expire_at, server_guid, server_timestamp, viewed_at, send_outcomes_json, author_aci,is_erased,delete_failed
                 FROM messages WHERE id=?1",
                params![message_id],
                message_record_from_row,
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(record.map(|record| (record, changed == 1)))
    }

    /// 契约 1.279（§4.263）+ 1.280（§4.264）：首发时记住这一条出站附件的原始
    /// data URI。`attachment_index` 是这条附件在消息 `attachments` 数组里的
    /// 位置（单附件恒为 0，多附件 0..n-1），与 accountId、clientRequestId 一起
    /// 构成主键（同一个 clientRequestId 在两个账号下是两行，互不覆盖）。
    ///
    /// 这是「官方消息附件持久化」的 connector 半：payload 不再是桌面的内存
    /// 责任，失败行在任何一次刷新/重启之后都还能重试。写入用
    /// `ON CONFLICT DO NOTHING`——同一个 (accountId, clientRequestId, index)
    /// 已经有 payload 时保留原来那一份（幂等重放/并发首发绝不能把首发的数据
    /// 覆盖成后来的请求）。首次发送在 pending 行写入前调用；写失败即失败（不发送），
    /// 否则修复会在无人察觉的情况下退化回「刷新即丢」。
    pub fn remember_outgoing_attachment_payload(
        &self,
        account_id: &str,
        conversation_id: &str,
        client_request_id: &str,
        attachment_index: u32,
        data_uri: &str,
        now_ms: u64,
    ) -> Result<(), StoreError> {
        self.remember_outgoing_attachment_payloads(
            account_id,
            conversation_id,
            client_request_id,
            &[(attachment_index, data_uri)],
            now_ms,
        )
    }

    /// 多附件版本（契约 1.280，§4.264）：一个事务写入整组条目（0..n-1），要么
    /// 全落、要么全不落——ids-only 重试按 index 重建整组字节，要求这组行是
    /// 完整的一代；宁可首发失败，也不要留下半组 payload 让重试无解。
    pub fn remember_outgoing_attachment_payloads(
        &self,
        account_id: &str,
        conversation_id: &str,
        client_request_id: &str,
        payloads: &[(u32, &str)],
        now_ms: u64,
    ) -> Result<(), StoreError> {
        if payloads.is_empty() {
            return Ok(());
        }
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        {
            let mut statement = transaction
                .prepare(
                    "INSERT INTO outgoing_attachment_payloads(
                       account_id, client_request_id, attachment_index,
                       conversation_id, data_uri, created_at, updated_at
                     ) VALUES(?1, ?2, ?3, ?4, ?5, ?6, ?6)
                     ON CONFLICT(account_id, client_request_id, attachment_index) DO NOTHING",
                )
                .map_err(|error| StoreError::Unavailable(Some(error)))?;
            for (attachment_index, data_uri) in payloads {
                statement
                    .execute(params![
                        account_id,
                        client_request_id,
                        i64::from(*attachment_index),
                        conversation_id,
                        data_uri,
                        now_ms as i64,
                    ])
                    .map_err(|error| StoreError::Unavailable(Some(error)))?;
            }
        }
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(())
    }

    /// 契约 1.279（§4.263）+ 1.280（§4.264）：重试时用这一次的 data URI 覆盖
    /// 对应 index 的 payload 行（`created_at` 保留首次落地时间），下一次刷新
    /// 重试继续可用。
    pub fn update_outgoing_attachment_payload(
        &self,
        account_id: &str,
        conversation_id: &str,
        client_request_id: &str,
        attachment_index: u32,
        data_uri: &str,
        now_ms: u64,
    ) -> Result<(), StoreError> {
        self.update_outgoing_attachment_payloads(
            account_id,
            conversation_id,
            client_request_id,
            &[(attachment_index, data_uri)],
            now_ms,
        )
    }

    /// 批量覆盖（见 `update_outgoing_attachment_payload`）：一个事务里的整组
    /// upsert。调用方带 bytes 时只覆盖它声明的 index；ids-only 重试把按 index
    /// 重建出来的整组 URI 写回（顺带刷新 updated_at，长失败的存量行不会在
    /// 保留窗口里失去重发源）。
    pub fn update_outgoing_attachment_payloads(
        &self,
        account_id: &str,
        conversation_id: &str,
        client_request_id: &str,
        payloads: &[(u32, &str)],
        now_ms: u64,
    ) -> Result<(), StoreError> {
        if payloads.is_empty() {
            return Ok(());
        }
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        {
            let mut statement = transaction
                .prepare(
                    "INSERT INTO outgoing_attachment_payloads(
                       account_id, client_request_id, attachment_index,
                       conversation_id, data_uri, created_at, updated_at
                     ) VALUES(?1, ?2, ?3, ?4, ?5, ?6, ?6)
                     ON CONFLICT(account_id, client_request_id, attachment_index) DO UPDATE SET
                       conversation_id=excluded.conversation_id,
                       data_uri=excluded.data_uri,
                       updated_at=excluded.updated_at",
                )
                .map_err(|error| StoreError::Unavailable(Some(error)))?;
            for (attachment_index, data_uri) in payloads {
                statement
                    .execute(params![
                        account_id,
                        client_request_id,
                        i64::from(*attachment_index),
                        conversation_id,
                        data_uri,
                        now_ms as i64,
                    ])
                    .map_err(|error| StoreError::Unavailable(Some(error)))?;
            }
        }
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(())
    }

    /// 契约 1.279（§4.263）+ 1.280（§4.264）：读取一条出站附件某个 index 的
    /// 原始 data URI。account 是主键的第一段（payload 与消息行同属一个账号），
    /// 跨账号的 clientRequestId 不会命中，也不会覆盖对方那一行。
    pub fn outgoing_attachment_payload(
        &self,
        account_id: &str,
        client_request_id: &str,
        attachment_index: u32,
    ) -> Result<Option<String>, StoreError> {
        self.lock_conn()?
            .query_row(
                "SELECT data_uri FROM outgoing_attachment_payloads
                  WHERE account_id=?1 AND client_request_id=?2 AND attachment_index=?3",
                params![account_id, client_request_id, i64::from(attachment_index)],
                |row| row.get::<_, String>(0),
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))
    }

    /// 契约 1.280（§4.264）：按 index 升序列出一组出站附件的原始 data URI——
    /// ids-only 重试就是靠它把多附件消息的整组字节按原顺序重建出来。
    pub fn outgoing_attachment_payloads(
        &self,
        account_id: &str,
        client_request_id: &str,
    ) -> Result<Vec<(u32, String)>, StoreError> {
        let conn = self.lock_conn()?;
        let mut statement = conn
            .prepare(
                "SELECT attachment_index, data_uri FROM outgoing_attachment_payloads
                  WHERE account_id=?1 AND client_request_id=?2
                  ORDER BY attachment_index",
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let rows = statement
            .query_map(params![account_id, client_request_id], |row| {
                Ok((row.get::<_, i64>(0)?, row.get::<_, String>(1)?))
            })
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let mut payloads = Vec::new();
        for row in rows {
            let (attachment_index, data_uri) =
                row.map_err(|error| StoreError::Unavailable(Some(error)))?;
            payloads.push((
                u32::try_from(attachment_index).unwrap_or(u32::MAX),
                data_uri,
            ));
        }
        Ok(payloads)
    }

    /// 契约 1.279/1.280：删除一条出站附件某个 index 的 payload（显式路径用）。
    /// 返回是否真的删了一行；幂等重放/已清理的请求返回 false。
    pub fn delete_outgoing_attachment_payload(
        &self,
        account_id: &str,
        client_request_id: &str,
        attachment_index: u32,
    ) -> Result<bool, StoreError> {
        let changed = self
            .lock_conn()?
            .execute(
                "DELETE FROM outgoing_attachment_payloads
                  WHERE account_id=?1 AND client_request_id=?2 AND attachment_index=?3",
                params![account_id, client_request_id, i64::from(attachment_index)],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(changed > 0)
    }

    /// 契约 1.279/1.280：删除这一个 clientRequestId 的全部 payload 行——成功
    /// 结算（整条消息已送达，整组原始字节都完成使命）走这里；显式删除路径则由
    /// store 内部的孤儿清理按同一个 clientRequestId 整组删除。失败/unknown
    /// 保留。返回删掉的行数。
    pub fn delete_outgoing_attachment_payloads(
        &self,
        account_id: &str,
        client_request_id: &str,
    ) -> Result<usize, StoreError> {
        self.lock_conn()?
            .execute(
                "DELETE FROM outgoing_attachment_payloads
                  WHERE account_id=?1 AND client_request_id=?2",
                params![account_id, client_request_id],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))
    }

    /// Rearm one failed outgoing attachment row for an IN-PLACE retry
    /// (contract revision 1.278, §4.262 — the §4.134 successor): the SAME
    /// row id takes the `failed -> pending` transition together with this
    /// request's content faces, in one guarded write. Nothing is deleted and
    /// nothing is inserted — the row the desktop bubble renders is the row
    /// the retry re-sends, so the history keeps exactly one row per
    /// clientRequestId (the official retry-send shape: reuse the message,
    /// never mint a second one beside it).
    ///
    /// Discipline, mirroring `rearm_failed_message`:
    /// - the `WHERE status='failed'` guard is the authority: a row that
    ///   settled meanwhile (or that a concurrent retry already rearmed) is
    ///   left untouched and reported `changed=false`, so two dispatch arms
    ///   can never race one row into two sends;
    /// - a manual retry is a NEW job with its own §4.123 window, so the
    ///   automatic face is retired with the rearm (`first_send_attempted_at`
    ///   / `retry_attempt_count` / `next_attempt_at` cleared) exactly as the
    ///   text retry does;
    /// - the previous attempt's settlement faces are cleared with it: the
    ///   §4.173 group-outcome ledger (`send_outcomes_json`) describes the
    ///   attempt that failed, and the delivery stamps belong to a send that
    ///   never landed;
    /// - identity and position stay the original message's (`id`,
    ///   `client_request_id`, `sent_at`): only the content faces follow this
    ///   request. The bytes come either from the caller or — contract 1.279,
    ///   §4.263 — from the persisted payload row; §4.183's local copy is still
    ///   a rendering cache, evictable at any governor pass.
    pub fn rearm_failed_attachment_retry(
        &self,
        message_id: &str,
        text: &str,
        quote_message_id: Option<&str>,
        attachments: &[MessageAttachmentInfo],
        rich: Option<&crate::engine::NormalizedRich>,
    ) -> Result<Option<(MessageRecord, bool)>, StoreError> {
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let changed = transaction
            .execute(
                "UPDATE messages SET status='pending', first_send_attempted_at=NULL,
                        retry_attempt_count=0, next_attempt_at=NULL,
                        body=?2, body_bytes=?3, body_truncated=0,
                        quote_message_id=?4, attachments_json=?5,
                        live_attachment_locators=?6, rich_json=?7,
                        send_outcomes_json=NULL, delivered_at=NULL, read_at=NULL,
                        viewed_at=NULL
                 WHERE id=?1 AND status='failed'",
                params![
                    message_id,
                    text,
                    text.len() as i64,
                    quote_message_id,
                    (!attachments.is_empty())
                        .then(|| { serde_json::to_string(attachments).expect("attachments json") }),
                    (!attachments.is_empty()).then(|| {
                        serde_json::to_string(
                            &attachments
                                .iter()
                                .map(|descriptor| descriptor.locator.clone().unwrap_or_default())
                                .collect::<Vec<_>>(),
                        )
                        .expect("live attachment locators json")
                    }),
                    rich.map(|rich| serde_json::to_string(rich).expect("rich json")),
                ],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let record = transaction
            .query_row(
                "SELECT id, account_id, conversation_id, direction, sender_id, sent_at, received_at,
                        body, body_bytes, body_truncated, status, quote_message_id, client_request_id,
                        quote_snapshot, attachments_json, rich_json, edited_at, sender_name, mentions_self, delivered_at, read_at, admin_deleted, sticker_json, expire_seconds, expire_start_at, expire_at, server_guid, server_timestamp, viewed_at, send_outcomes_json, author_aci,is_erased,delete_failed
                 FROM messages WHERE id=?1",
                params![message_id],
                message_record_from_row,
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(record.map(|record| (record, changed == 1)))
    }

    /// The official retry backoff beat for the nth automatic attempt (1-based):
    /// `min(190 ms · 1.9^(n-1), 15 min)`, computed in exact integer rational
    /// arithmetic so the schedule is reproducible without float drift. The
    /// cap is reached at n=15 and every later beat is 15 minutes, which is
    /// what makes the 24 h window fit ≈110 attempts (see `MAX_RETRY_ATTEMPTS`).
    pub fn retry_backoff_delay_ms(retry_number: u32) -> u64 {
        let mut delay = RETRY_BACKOFF_BASE_MS;
        for _ in 1..retry_number {
            delay = delay
                .saturating_mul(RETRY_BACKOFF_FACTOR_NUM)
                .saturating_div(RETRY_BACKOFF_FACTOR_DEN);
            if delay >= RETRY_BACKOFF_MAX_MS {
                return RETRY_BACKOFF_MAX_MS;
            }
        }
        delay.min(RETRY_BACKOFF_MAX_MS)
    }

    /// Retire the §4.123 scheduling face of one row, whatever its status.
    /// The unknown-outcome settlement calls this: a row whose wire outcome
    /// was never settled must never carry a live schedule, so the red line
    /// (unknown outcomes are never retried automatically) holds at the store
    /// layer even if a schedule somehow survived onto a later-unknown row.
    /// Idempotent; the per-account queue ceiling counts only rows it can
    /// still see, so retiring keeps the bound honest.
    pub fn retire_retry_schedule(&self, message_id: &str) -> Result<(), StoreError> {
        let conn = self.lock_conn()?;
        conn.execute(
            "UPDATE messages SET first_send_attempted_at=NULL, retry_attempt_count=0,
                    next_attempt_at=NULL
             WHERE id=?1",
            params![message_id],
        )
        .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(())
    }

    /// Settle one dispatched send as definitively failed (§4.123): the
    /// atomic `pending -> failed` transition, and — when the caller
    /// classified the engine error into an automatic-retry arm — the queue
    /// schedule in the same guarded write, so a row can never be observed
    /// failed-and-unscheduled between settlement and enqueue. The schedule
    /// arm refuses anything that is not a retryable outbound text row
    /// (direction, non-empty text, a `client_request_id`, no attachment
    /// descriptors — §4.134, the rebuild's caption-only channel; the
    /// receive-mirrored multi-device echo rows are another device's delivery
    /// and are never ours to resend), that already spent its attempt budget,
    /// or that would push the account past the in-queue ceiling; such rows
    /// settle plain `failed` with the queue face retired. Returns the row
    /// after the write with whether the settlement actually transitioned (a
    /// status push that already settled the row wins; the late engine answer
    /// loses).
    ///
    /// Unknown outcomes never reach this face: the caller settles them
    /// through `update_message_status(_, "unknown", _)`, and the scheduling
    /// guard would refuse them anyway (their status is not `pending` after
    /// that write — the red line is enforced twice, by the funnel and by the
    /// store).
    pub fn settle_send_failed(
        &self,
        message_id: &str,
        now: u64,
        schedule: SendRetrySchedule,
        outcomes: Option<&MessageSendOutcomes>,
    ) -> Result<Option<(MessageRecord, bool)>, StoreError> {
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let changed = if matches!(
            schedule,
            SendRetrySchedule::Backoff | SendRetrySchedule::RateLimit
        ) {
            // Scheduling settlement: the status flips alone; the schedule arm
            // below writes the retry face, so the window anchor
            // (`first_send_attempted_at`) survives consecutive automatic
            // attempts — a retry never resets the window.
            transaction
                .execute(
                    "UPDATE messages SET status='failed' WHERE id=?1 AND status='pending'",
                    params![message_id],
                )
                .map_err(|error| StoreError::Unavailable(Some(error)))?
        } else {
            // Plain settlement (ineligible error class, non-text row, or the
            // caller's explicit no-schedule): the row leaves the queue face
            // entirely, so nothing scheduled survives on a row the queue no
            // longer owns. §4.173: an all-recipient-failure group send
            // settles through this arm and its counted outcomes ride the row
            // (the desktop's error face reads them); `None` keeps the column
            // untouched — a plain engine-error settlement never had a
            // `results` face to count.
            transaction
                .execute(
                    "UPDATE messages SET status='failed',
                            first_send_attempted_at=NULL, retry_attempt_count=0,
                            next_attempt_at=NULL, send_outcomes_json=COALESCE(?2, send_outcomes_json)
                     WHERE id=?1 AND status='pending'",
                    params![
                        message_id,
                        outcomes
                            .map(|counted| serde_json::to_string(counted).expect("send outcomes json")),
                    ],
                )
                .map_err(|error| StoreError::Unavailable(Some(error)))?
        };
        let record = if changed == 0 {
            None
        } else {
            Self::settle_send_failed_schedule(&transaction, message_id, now, schedule)?;
            transaction
                .query_row(
                    "SELECT id, account_id, conversation_id, direction, sender_id, sent_at, received_at,
                            body, body_bytes, body_truncated, status, quote_message_id, client_request_id,
                            quote_snapshot, attachments_json, rich_json, edited_at, sender_name, mentions_self, delivered_at, read_at, admin_deleted, sticker_json, expire_seconds, expire_start_at, expire_at, server_guid, server_timestamp, viewed_at, send_outcomes_json, author_aci,is_erased,delete_failed
                     FROM messages WHERE id=?1",
                    params![message_id],
                    message_record_from_row,
                )
                .optional()
                .map_err(|error| StoreError::Unavailable(Some(error)))?
        };
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(record.map(|record| (record, true)))
    }

    /// The §4.123 schedule arm of `settle_send_failed`, on the caller's
    /// transaction: re-reads the just-settled row, decides eligibility, and
    /// either writes the scheduling face or retires it. Every refusal
    /// (non-text row, no clientRequestId, attempt budget spent, account
    /// queue ceiling) clears `next_attempt_at`, so a refused row can never
    /// be re-claimed — the budget and the ceiling are terminal for the
    /// automatic face, not a pause.
    fn settle_send_failed_schedule(
        transaction: &Connection,
        message_id: &str,
        now: u64,
        schedule: SendRetrySchedule,
    ) -> Result<(), StoreError> {
        if matches!(schedule, SendRetrySchedule::None) {
            return Ok(());
        }
        let row = transaction
            .query_row(
                "SELECT direction, body, client_request_id, retry_attempt_count,
                        first_send_attempted_at, account_id, attachments_json
                 , delete_failed
                 FROM messages WHERE id=?1 AND status='failed'",
                params![message_id],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, Option<String>>(1)?,
                        row.get::<_, Option<String>>(2)?,
                        row.get::<_, i64>(3)?,
                        row.get::<_, Option<i64>>(4)?,
                        row.get::<_, String>(5)?,
                        row.get::<_, Option<String>>(6)?,
                    ))
                },
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let Some((
            direction,
            body,
            client_request_id,
            attempt_count,
            _first,
            account_id,
            attachments,
        )) = row
        else {
            return Ok(());
        };
        // Eligibility (§4.123, narrowed by §4.134): outbound text row with a
        // clientRequestId, attempt budget left, no attachment descriptors,
        // and the account under its in-queue ceiling. The rebuild face has
        // no attachment channel, so an attachment row — caption included —
        // would re-dispatch its caption as plain text without the bytes; the
        // descriptor-carrying family stays manual (the §4.92 answer), the
        // refusal the standard retire shape.
        let eligible = direction == "outgoing"
            && body.as_deref().is_some_and(|body| !body.is_empty())
            && client_request_id.is_some()
            && !has_attachment_descriptors(attachments.as_deref())
            && (attempt_count as u64) < u64::from(MAX_RETRY_ATTEMPTS);
        if !eligible {
            return Self::retire_retry_schedule_in(transaction, message_id);
        }
        let queued: i64 = transaction
            .query_row(
                "SELECT COUNT(*) FROM messages
                 WHERE account_id=?1 AND direction='outgoing' AND status='failed'
                   AND next_attempt_at IS NOT NULL AND id<>?2",
                params![account_id, message_id],
                |row| row.get(0),
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        if queued as u64 >= u64::from(MAX_RETRY_QUEUED_PER_ACCOUNT) {
            return Self::retire_retry_schedule_in(transaction, message_id);
        }
        let delay = match schedule {
            // The 429/413 family waits the server's pause, not the curve:
            // this wire carries no Retry-After value, so the official
            // default (one minute) is the beat.
            SendRetrySchedule::RateLimit => RATE_LIMIT_RETRY_AFTER_MS,
            SendRetrySchedule::Backoff => Self::retry_backoff_delay_ms(attempt_count as u32 + 1),
            // Unreachable — the None arm returned before the row read — but
            // a no-op keeps the match total without inventing behavior.
            SendRetrySchedule::None => return Ok(()),
        };
        transaction
            .execute(
                "UPDATE messages SET next_attempt_at=?2,
                        retry_attempt_count=retry_attempt_count+1,
                        first_send_attempted_at=COALESCE(first_send_attempted_at, ?3)
                 WHERE id=?1 AND status='failed'",
                params![message_id, (now.saturating_add(delay)) as i64, now as i64],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(())
    }

    /// The transaction-bound retire used by the schedule refusals above (the
    /// standalone `retire_retry_schedule` opens its own connection lock and
    /// must never be called inside one of these transactions).
    fn retire_retry_schedule_in(
        transaction: &Connection,
        message_id: &str,
    ) -> Result<(), StoreError> {
        transaction
            .execute(
                "UPDATE messages SET next_attempt_at=NULL
                 WHERE id=?1 AND status='failed'",
                params![message_id],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(())
    }

    /// One bounded §4.123 drain pass: scan the due queue (oldest schedule
    /// first, partial index, hard batch limit), kill the entries whose 24 h
    /// window has run out, and claim the rest by the atomic
    /// `failed -> pending` flip — the same guard family as
    /// `rearm_failed_message`, so a concurrent manual retry or a second
    /// claimer can never double-take a row (the flip is the claim; a lost
    /// race simply selects nothing). Bounded at every layer: the scan reads
    /// at most `limit` rows, each surviving at most `MAX_RETRY_ATTEMPTS`
    /// claims (the schedule face refuses a 129th), and the queue itself at
    /// most `MAX_RETRY_QUEUED_PER_ACCOUNT` per account. The drain loop reads
    /// the wake instant separately, after the pass settles, through
    /// `next_retry_due_at`.
    pub fn claim_due_retries(&self, now: u64, limit: u32) -> Result<Vec<RetryClaim>, StoreError> {
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let mut due = transaction
            .prepare(
                "SELECT id, account_id, conversation_id, client_request_id, sent_at,
                        first_send_attempted_at, attachments_json
                 FROM messages
                 WHERE direction='outgoing' AND status='failed'
                   AND next_attempt_at IS NOT NULL AND next_attempt_at<=?1
                 ORDER BY next_attempt_at ASC, id ASC
                 LIMIT ?2",
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let scanned = due
            .query_map(params![now as i64, limit], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, String>(2)?,
                    row.get::<_, Option<String>>(3)?,
                    row.get::<_, i64>(4)?,
                    row.get::<_, Option<i64>>(5)?,
                    row.get::<_, Option<String>>(6)?,
                ))
            })
            .map_err(|error| StoreError::Unavailable(Some(error)))?
            .collect::<Result<Vec<_>, _>>()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        drop(due);
        let mut claims = Vec::new();
        for (
            message_id,
            account_id,
            conversation_id,
            client_request_id,
            sent_at,
            first,
            attachments,
        ) in scanned
        {
            // §4.134: an attachment row that still carries a live schedule
            // (enrolled before the §4.134 enrollment gate) is refused at
            // claim time — the schedule retires and the row stays `failed`
            // (the over-ceiling refusal shape), so the rebuild face's
            // caption-only channel never re-dispatches it and the scan
            // shrinks instead of circling.
            if has_attachment_descriptors(attachments.as_deref()) {
                transaction
                    .execute(
                        "UPDATE messages SET next_attempt_at=NULL
                         WHERE id=?1 AND status='failed'",
                        params![message_id],
                    )
                    .map_err(|error| StoreError::Unavailable(Some(error)))?;
                continue;
            }
            // Window judgment (§4.123): past `first_send_attempted_at + 24 h`
            // the row dies in the queue — it stays `failed` (terminal) and
            // the scheduling face is retired, so the scan shrinks instead of
            // circling. The fallback treats a NULL first stamp as "window
            // started now", which can only happen on a hand-edited store.
            let window_start = first
                .map(|value| value as u64)
                .unwrap_or(sent_at as u64)
                .min(now);
            if now.saturating_sub(window_start) >= RETRY_WINDOW_MS {
                transaction
                    .execute(
                        "UPDATE messages SET next_attempt_at=NULL
                         WHERE id=?1 AND status='failed'",
                        params![message_id],
                    )
                    .map_err(|error| StoreError::Unavailable(Some(error)))?;
                continue;
            }
            // The flip is the claim: only one writer can move a row out of
            // 'failed', so a double-take (second worker, a racing manual
            // retry) loses here and the row is skipped this pass.
            let claimed = transaction
                .execute(
                    "UPDATE messages SET status='pending' WHERE id=?1 AND status='failed'",
                    params![message_id],
                )
                .map_err(|error| StoreError::Unavailable(Some(error)))?;
            if claimed == 1
                && let Some(client_request_id) = client_request_id
            {
                claims.push(RetryClaim {
                    message_id,
                    account_id,
                    conversation_id,
                    client_request_id,
                    sent_at: sent_at as u64,
                });
            }
        }
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(claims)
    }

    /// The earliest schedule still standing in the §4.123 queue — the drain
    /// loop's wake instant (None = queue empty). One partial-index read, run
    /// after a pass settles so a just-scheduled retry beat is honored at its
    /// own pace (the official 190 ms… 15 min curve), never at the tick's.
    pub fn next_retry_due_at(&self) -> Result<Option<u64>, StoreError> {
        let conn = self.lock_conn()?;
        let next_due: Option<i64> = conn
            .query_row(
                "SELECT MIN(next_attempt_at) FROM messages
                 WHERE direction='outgoing' AND status='failed'
                   AND next_attempt_at IS NOT NULL",
                [],
                |row| row.get(0),
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?
            .flatten();
        Ok(next_due.map(|value| value.max(0) as u64))
    }

    /// Apply an inbound edit (contract 1.15): replace the body of the row the
    /// target upstream timestamp addresses, only when the editor matches the
    /// row's sender identity, and stamp `edited_at`. Returns the updated row,
    /// or None when no matching row exists (missing target / editor mismatch /
    /// already remote-deleted) — the caller drops the edit in that case.
    #[allow(clippy::too_many_arguments)]
    pub fn apply_inbound_edit(
        &self,
        account_id: &str,
        conversation_id: &str,
        target_sent_at: u64,
        sender_id: &str,
        legacy_sender_id: &str,
        new_text: &str,
        new_text_bytes: u32,
    ) -> Result<Option<MessageRecord>, StoreError> {
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        // The sender match uses the same identity pair as receive dedupe: the
        // sender hash for incoming rows differs between store generations.
        // The prior body is read before the overwrite so the contract-1.32
        // snapshot can record what this edit replaced.
        let prior: Option<(String, String, i64)> = transaction
            .query_row(
                "SELECT id, body, body_bytes FROM messages
                 WHERE account_id=?1 AND conversation_id=?2 AND sent_at=?3
                   AND sender_id IN (?4, ?5) AND direction='incoming'
                   AND status NOT IN ('remote-deleted', 'system')
                 ORDER BY id ASC LIMIT 1",
                params![
                    account_id,
                    conversation_id,
                    target_sent_at as i64,
                    sender_id,
                    legacy_sender_id,
                ],
                |row| {
                    Ok((
                        row.get(0)?,
                        row.get::<_, Option<String>>(1)?.unwrap_or_default(),
                        row.get::<_, Option<i64>>(2)?.unwrap_or(0),
                    ))
                },
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let changed = transaction
            .execute(
                "UPDATE messages
                 SET body=?4, body_bytes=?5, body_truncated=0, edited_at=?6
                 WHERE account_id=?1 AND conversation_id=?2 AND sent_at=?3
                   AND sender_id IN (?7, ?8) AND direction='incoming'
                   AND status NOT IN ('remote-deleted', 'system')",
                params![
                    account_id,
                    conversation_id,
                    target_sent_at as i64,
                    new_text,
                    new_text_bytes,
                    crate::link::now_ms() as i64,
                    sender_id,
                    legacy_sender_id,
                ],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        if changed == 0 {
            transaction
                .commit()
                .map_err(|error| StoreError::Unavailable(Some(error)))?;
            return Ok(None);
        }
        if let Some((message_id, prior_body, _)) = prior {
            Self::snapshot_prior_body(&transaction, account_id, &message_id, &prior_body)?;
        }
        let record = transaction
            .query_row(
                "SELECT id, account_id, conversation_id, direction, sender_id, sent_at, received_at,
                        body, body_bytes, body_truncated, status, quote_message_id, client_request_id,
                        quote_snapshot, attachments_json, rich_json, edited_at, sender_name, mentions_self, delivered_at, read_at, admin_deleted, sticker_json, expire_seconds, expire_start_at, expire_at, server_guid, server_timestamp, viewed_at, send_outcomes_json, author_aci,is_erased,delete_failed
                 FROM messages
                 WHERE account_id=?1 AND conversation_id=?2 AND sent_at=?3
                   AND sender_id IN (?4, ?5)
                 ORDER BY id ASC LIMIT 1",
                params![
                    account_id,
                    conversation_id,
                    target_sent_at as i64,
                    sender_id,
                    legacy_sender_id,
                ],
                message_record_from_row,
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(record)
    }

    /// Replace an outgoing row's body after a confirmed upstream
    /// `editMessage` (contract 1.15; the engine's native edit method since
    /// 1.105). The status is untouched — an edited message stays `sent` — and
    /// `edited_at` marks the row.
    pub fn apply_outgoing_edit(
        &self,
        message_id: &str,
        account_id: &str,
        _conversation_id: &str,
        new_text: &str,
        new_text_bytes: u32,
    ) -> Result<Option<MessageRecord>, StoreError> {
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        // Contract-1.32 snapshot: the body this host-initiated edit replaces.
        let prior: Option<(String, String)> = transaction
            .query_row(
                "SELECT body, body_bytes , delete_failed
                 FROM messages
                 WHERE id=?1 AND account_id=?2 AND direction='outgoing'",
                params![message_id, account_id],
                |row| {
                    Ok((
                        row.get::<_, Option<String>>(0)?.unwrap_or_default(),
                        row.get::<_, Option<i64>>(1)?.unwrap_or(0),
                    ))
                },
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?
            .map(|(body, _)| (message_id.to_string(), body));
        transaction
            .execute(
                "UPDATE messages
                 SET body=?3, body_bytes=?4, body_truncated=0, edited_at=?5
                 WHERE id=?1 AND account_id=?2
                   AND direction='outgoing'",
                params![
                    message_id,
                    account_id,
                    new_text,
                    new_text_bytes,
                    crate::link::now_ms() as i64,
                ],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        if let Some((snapshot_id, prior_body)) = prior {
            Self::snapshot_prior_body(&transaction, account_id, &snapshot_id, &prior_body)?;
        }
        let record = transaction
            .query_row(
                "SELECT id, account_id, conversation_id, direction, sender_id, sent_at, received_at,
                        body, body_bytes, body_truncated, status, quote_message_id, client_request_id,
                        quote_snapshot, attachments_json, rich_json, edited_at, sender_name, mentions_self, delivered_at, read_at, admin_deleted, sticker_json, expire_seconds, expire_start_at, expire_at, server_guid, server_timestamp, viewed_at, send_outcomes_json, author_aci,is_erased,delete_failed
                 FROM messages WHERE id=?1",
                params![message_id],
                message_record_from_row,
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(record)
    }

    /// Our own multi-device edit mirror (contract 1.15): locate the outgoing
    /// row by its upstream timestamp — the phone's edit echoes
    /// `targetSentTimestamp`, which equals the row's `sent_at` after
    /// `complete_outgoing_send` overwrote it — and apply the same body
    /// replacement as a host-initiated edit.
    pub fn apply_outgoing_edit_by_signal(
        &self,
        account_id: &str,
        conversation_id: &str,
        target_sent_at: u64,
        new_text: &str,
        new_text_bytes: u32,
    ) -> Result<Option<MessageRecord>, StoreError> {
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        // Contract-1.32 snapshot: the body this multi-device mirror edit
        // replaces, read under the same predicate the UPDATE below guards.
        let prior: Option<(String, String)> = transaction
            .query_row(
                "SELECT id, body , delete_failed
                 FROM messages
                 WHERE account_id=?1 AND conversation_id=?2 AND sent_at=?3
                   AND direction='outgoing'
                   AND status NOT IN ('remote-deleted', 'system')
                 ORDER BY id ASC LIMIT 1",
                params![account_id, conversation_id, target_sent_at as i64],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, Option<String>>(1)?.unwrap_or_default(),
                    ))
                },
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        transaction
            .execute(
                "UPDATE messages
                 SET body=?4, body_bytes=?5, body_truncated=0, edited_at=?6
                 WHERE account_id=?1 AND conversation_id=?2 AND sent_at=?3
                   AND direction='outgoing'
                   AND status NOT IN ('remote-deleted', 'system')",
                params![
                    account_id,
                    conversation_id,
                    target_sent_at as i64,
                    new_text,
                    new_text_bytes,
                    crate::link::now_ms() as i64,
                ],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        if let Some((snapshot_id, prior_body)) = prior {
            Self::snapshot_prior_body(&transaction, account_id, &snapshot_id, &prior_body)?;
        }
        let record = transaction
            .query_row(
                "SELECT id, account_id, conversation_id, direction, sender_id, sent_at, received_at,
                        body, body_bytes, body_truncated, status, quote_message_id, client_request_id,
                        quote_snapshot, attachments_json, rich_json, edited_at, sender_name, mentions_self, delivered_at, read_at, admin_deleted, sticker_json, expire_seconds, expire_start_at, expire_at, server_guid, server_timestamp, viewed_at, send_outcomes_json, author_aci,is_erased,delete_failed
                 FROM messages
                 WHERE account_id=?1 AND conversation_id=?2 AND sent_at=?3
                   AND direction='outgoing'
                 ORDER BY id ASC LIMIT 1",
                params![account_id, conversation_id, target_sent_at as i64],
                message_record_from_row,
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(record)
    }

    /// Fold one live poll vote onto the poll row it addresses (§4.118):
    /// the official vote semantics — the voter's full selection replaces
    /// their prior vote, an empty selection clears it. The row is keyed by
    /// the §4.6 addressing pair (upstream timestamp + the poll author's
    /// sender-hash pair, the same identity family receive dedupe and the
    /// edit arms use; the pair itself disambiguates the incoming/outgoing
    /// legs, so no direction clause is needed). Fail-closed everywhere: a
    /// missing or ambiguous row, and a row that carries no poll face, all
    /// answer `None` and mutate nothing — a vote can never invent a poll
    /// face on a foreign row. Indexes past the poll's own option bound
    /// cannot render and no-op the fold (a hostile selection never erases
    /// a legitimate vote under the clear-vote shape). Returns the updated
    /// record for the caller's `message.upserted`.
    #[allow(clippy::too_many_arguments)]
    pub fn fold_poll_vote(
        &self,
        account_id: &str,
        conversation_id: &str,
        target_sent_at: u64,
        sender_id: &str,
        legacy_sender_id: &str,
        voter_id: &str,
        option_indexes: &[u32],
    ) -> Result<Option<MessageRecord>, StoreError> {
        self.fold_poll_row(
            account_id,
            conversation_id,
            target_sent_at,
            sender_id,
            legacy_sender_id,
            |poll| {
                // The §4.38 cap family: a poll past the vote cap keeps its
                // first 64 voters, exactly like the import fold.
                const MAX_POLL_VOTES: usize = 64;
                let cap = poll.options.len() as u32;
                let indexes: Vec<u32> = option_indexes
                    .iter()
                    .copied()
                    .filter(|index| *index < cap)
                    .collect();
                if let Some(entry) = poll.votes.iter_mut().find(|vote| vote.voter_id == voter_id) {
                    if indexes.is_empty() {
                        let voter = voter_id.to_string();
                        poll.votes.retain(|vote| vote.voter_id != voter);
                    } else {
                        entry.option_indexes = indexes;
                    }
                    return true;
                }
                if indexes.is_empty() || poll.votes.len() >= MAX_POLL_VOTES {
                    return false;
                }
                poll.votes.push(crate::engine::NormalizedPollVote {
                    voter_id: voter_id.to_string(),
                    option_indexes: indexes,
                });
                true
            },
        )
    }

    /// Fold one live poll termination onto the poll row it addresses
    /// (§4.118): the `terminated` bit flips true, idempotent. The same
    /// fail-closed keying and `None` answers as [`Self::fold_poll_vote`].
    pub fn fold_poll_terminate(
        &self,
        account_id: &str,
        conversation_id: &str,
        target_sent_at: u64,
        sender_id: &str,
        legacy_sender_id: &str,
    ) -> Result<Option<MessageRecord>, StoreError> {
        self.fold_poll_row(
            account_id,
            conversation_id,
            target_sent_at,
            sender_id,
            legacy_sender_id,
            |poll| {
                if poll.terminated {
                    return false;
                }
                poll.terminated = true;
                true
            },
        )
    }

    /// The shared fold half: resolve the addressed poll row, require a
    /// poll face, apply the mutation, persist the rich column, return the
    /// fresh record. `None` answers an absent target, an ambiguous
    /// (per-sender timestamp collision) target, and a target with no poll
    /// face alike — the caller cannot distinguish them and never invents
    /// state from the difference.
    fn fold_poll_row<F>(
        &self,
        account_id: &str,
        conversation_id: &str,
        target_sent_at: u64,
        sender_id: &str,
        legacy_sender_id: &str,
        mutate: F,
    ) -> Result<Option<MessageRecord>, StoreError>
    where
        F: FnOnce(&mut crate::engine::NormalizedPoll) -> bool,
    {
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let candidates: Vec<(String, Option<String>)> = transaction
            .prepare(
                "SELECT id, rich_json , delete_failed
                 FROM messages
                 WHERE account_id=?1 AND conversation_id=?2 AND sent_at=?3
                   AND sender_id IN (?4, ?5)
                   AND status NOT IN ('remote-deleted', 'system')
                 ORDER BY id ASC",
            )
            .and_then(|mut stmt| {
                stmt.query_map(
                    params![
                        account_id,
                        conversation_id,
                        target_sent_at as i64,
                        sender_id,
                        legacy_sender_id,
                    ],
                    |row| Ok((row.get(0)?, row.get(1)?)),
                )
                .and_then(|rows| rows.collect())
            })
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        // One row answers; two rows at one (sender-pair, timestamp) identity
        // are the same ambiguity `message_by_signal_identity` refuses — a
        // fold into "whichever row wins the ORDER BY" could poison a
        // foreign row.
        let mut rows = candidates.into_iter();
        let Some((message_id, rich_json)) = rows.next() else {
            return Ok(None);
        };
        if rows.next().is_some() {
            return Ok(None);
        }
        let Some(json) = rich_json else {
            return Ok(None);
        };
        // A rich column this store did not write (or cannot parse) is not a
        // poll row this fold can honestly touch — refuse, never guess.
        let Ok(mut rich) = serde_json::from_str::<crate::engine::NormalizedRich>(&json) else {
            return Ok(None);
        };
        let Some(poll) = rich.poll.as_mut() else {
            return Ok(None);
        };
        if !mutate(poll) {
            return Ok(None);
        }
        let updated = serde_json::to_string(&rich).expect("rich json");
        transaction
            .execute(
                "UPDATE messages SET rich_json=?2 WHERE id=?1",
                params![message_id, updated],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let record = transaction
            .query_row(
                "SELECT id, account_id, conversation_id, direction, sender_id, sent_at, received_at,
                        body, body_bytes, body_truncated, status, quote_message_id, client_request_id,
                        quote_snapshot, attachments_json, rich_json, edited_at, sender_name, mentions_self, delivered_at, read_at, admin_deleted, sticker_json, expire_seconds, expire_start_at, expire_at, server_guid, server_timestamp, viewed_at, send_outcomes_json, author_aci,is_erased,delete_failed
                 FROM messages
                 WHERE id=?1",
                params![message_id],
                message_record_from_row,
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(record)
    }

    /// Mark a message remote-deleted (contract 1.15): a peer's or our own
    /// multi-device remoteDelete pointing at this row's upstream timestamp.
    /// Contract 1.109 (§4.90): the delete is author-scoped — only rows whose
    /// `sender_id` is the delete envelope's own author projection (the same
    /// derivation the landing row stored, the account id itself for the
    /// outgoing multi-device mirrors) ever transition. Per-sender clocks make
    /// (conversation, sent_at) shared across authors in a group, so the
    /// author-blind update could wipe a foreign member's row that happens to
    /// carry the same timestamp. Idempotent; returns the updated row when the
    /// status actually transitioned so a replayed delete does not re-emit
    /// events. `None` answers either an absent target or a target owned by
    /// another author — the caller cannot distinguish the two and must not
    /// (the absent case is the early-arrival question, §4.91).
    pub fn mark_remote_deleted(
        &self,
        account_id: &str,
        conversation_id: &str,
        target_sent_at: u64,
        author_sender_id: &str,
    ) -> Result<Option<(MessageRecord, bool)>, StoreError> {
        let conn = self.lock_conn()?;
        let transaction = conn
            .unchecked_transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let changed = transaction
            .execute(
                "UPDATE messages
                 SET status='remote-deleted',
                     body=NULL,
                     body_bytes=NULL,
                     body_truncated=0,
                     attachments_json=NULL,
                     attachment_locators=NULL,
                     live_attachment_locators=NULL,
                     rich_json=NULL,
                     quote_message_id=NULL,
                     quote_snapshot=NULL
                 WHERE account_id=?1 AND conversation_id=?2 AND sent_at=?3
                   AND sender_id=?4
                   AND status NOT IN ('remote-deleted', 'system')",
                params![
                    account_id,
                    conversation_id,
                    target_sent_at as i64,
                    author_sender_id
                ],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let record = transaction
            .query_row(
                "SELECT id, account_id, conversation_id, direction, sender_id, sent_at, received_at,
                        body, body_bytes, body_truncated, status, quote_message_id, client_request_id,
                        quote_snapshot, attachments_json, rich_json, edited_at, sender_name, mentions_self, delivered_at, read_at, admin_deleted, sticker_json, expire_seconds, expire_start_at, expire_at, server_guid, server_timestamp, viewed_at, send_outcomes_json, author_aci,is_erased,delete_failed
                 FROM messages
                 WHERE account_id=?1 AND conversation_id=?2 AND sent_at=?3 AND sender_id=?4
                 ORDER BY id ASC LIMIT 1",
                params![
                    account_id,
                    conversation_id,
                    target_sent_at as i64,
                    author_sender_id
                ],
                message_record_from_row,
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        // 官方 eraseMessageContents：同时终结该消息上的回应（保留墓碑行，
        // 但正文/附件/引用/富文本与 reaction 不再可见）。
        if changed > 0 {
            transaction
                .execute(
                    "UPDATE message_events
                     SET removed=1
                     WHERE account_id=?1 AND conversation_id=?2 AND target_timestamp=?3",
                    params![account_id, conversation_id, target_sent_at as i64],
                )
                .map_err(|error| StoreError::Unavailable(Some(error)))?;
            // 契约 1.279（§4.263）：对所有人删除后这条消息不可能再重试，
            // 原始 payload 一并删除（墓碑行保留）。
            if let Some(client_request_id) = record
                .as_ref()
                .and_then(|record| record.client_request_id.as_deref())
            {
                transaction
                    .execute(
                        "DELETE FROM outgoing_attachment_payloads
                          WHERE client_request_id=?1 AND account_id=?2",
                        params![client_request_id, account_id],
                    )
                    .map_err(|error| StoreError::Unavailable(Some(error)))?;
            }
        }
        // 若被删行正占摘要槽，清掉旧正文预览；conversation_summary 随后
        // 仍会从该行 status=remote-deleted 计算 last_message_status，桌面据此
        // 显示官方删除墓碑，而不是摘要继续残留旧正文。
        if changed > 0
            && let Some(latest) = record.as_ref()
        {
            transaction
                .execute(
                    "UPDATE conversations
                     SET last_message_preview=NULL
                     WHERE id=?1
                       AND (SELECT id FROM messages
                            WHERE conversation_id=?1
                            ORDER BY sent_at DESC, id DESC LIMIT 1)=?2",
                    params![conversation_id, latest.id],
                )
                .map_err(|error| StoreError::Unavailable(Some(error)))?;
        }
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(record.map(|record| (record, changed > 0)))
    }

    /// Append one pin to the conversation queue (contract 1.33; multi-pin
    /// queue, diff-C #54; backup `PinDetails` semantics, contract 1.197).
    /// The official model keeps up to `CONVERSATION_PIN_LIMIT` pinned
    /// messages per conversation (`getPinnedMessagesLimit` = 3) and the
    /// desktop's `appendPinnedMessage` decides by target message id:
    /// a target with no existing row inserts, the same target replaces
    /// only when the new `pinned_at` is strictly newer, and after the write
    /// the queue keeps the newest three by `pinned_at`
    /// (pinDetails@`import.preload.ts:1922-1945`,
    /// `appendPinnedMessage`@`pinnedMessages.std.ts:157-201`,
    /// `_truncatePinnedMessagesByConversationId`@:126-144). The local key is
    /// the target's upstream stamp, never the author spelling: import and
    /// live faces may name the same message as E.164 or ACI and still
    /// converge on one row. `pinned_at` is the backup's
    /// `pinnedAtTimestamp` on import and the receive clock live;
    /// `expires_at` is the precomputed expiry (`None` = forever). A missing
    /// target row is not an error: the state is still derived (the summary
    /// projection only surfaces pins whose row is locally renderable).
    pub fn append_conversation_pin(
        &self,
        account_id: &str,
        conversation_id: &str,
        target_author: &str,
        target_sent_at: u64,
        pinned_at: u64,
        expires_at: Option<u64>,
    ) -> Result<(), StoreError> {
        let mut conn = self.lock_conn()?;
        let transaction = conn
            .transaction()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        let existing: Option<i64> = transaction
            .query_row(
                "SELECT pinned_at FROM conversation_pins
                 WHERE account_id=?1 AND conversation_id=?2 AND target_sent_at=?3",
                params![account_id, conversation_id, target_sent_at as i64],
                |row| row.get(0),
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        // Official appendPinnedMessage: insert when absent, replace only when
        // the incoming pin is strictly newer. An older replay (a backup pin
        // landing after the live pin it duplicates) leaves the row alone.
        if existing.is_none_or(|existing| pinned_at > existing as u64) {
            transaction
                .execute(
                    "DELETE FROM conversation_pins
                     WHERE account_id=?1 AND conversation_id=?2 AND target_sent_at=?3",
                    params![account_id, conversation_id, target_sent_at as i64],
                )
                .map_err(|error| StoreError::Unavailable(Some(error)))?;
            transaction
                .execute(
                    "INSERT INTO conversation_pins(
                        account_id, conversation_id, target_author, target_sent_at,
                        pinned_at, expires_at
                     ) VALUES(?1, ?2, ?3, ?4, ?5, ?6)",
                    params![
                        account_id,
                        conversation_id,
                        target_author,
                        target_sent_at as i64,
                        pinned_at as i64,
                        expires_at.map(|value| value as i64),
                    ],
                )
                .map_err(|error| StoreError::Unavailable(Some(error)))?;
        }
        // Receiver-side cap: keep the newest three by pinned_at (official
        // truncate keeps `ORDER BY pinnedAt DESC LIMIT 3`; ties break by the
        // older rowid so the survivor is deterministic).
        transaction
            .execute(
                "DELETE FROM conversation_pins
                 WHERE rowid IN (
                   SELECT rowid FROM conversation_pins
                    WHERE account_id=?1 AND conversation_id=?2
                    ORDER BY pinned_at DESC, rowid DESC
                    LIMIT -1 OFFSET ?3
                 )",
                params![account_id, conversation_id, CONVERSATION_PIN_LIMIT as i64],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        transaction
            .commit()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(())
    }

    /// Clear the conversation's pinned state by target stamp. The official
    /// unpin/adminDelete resolves the target message and deletes that message
    /// id, so the local key is the upstream stamp — not the author spelling a
    /// replayed envelope happened to carry. A stale or mismatched clear
    /// addresses no row and leaves a newer pin alone. Returns whether a row
    /// was removed so replays stay silent.
    pub fn clear_conversation_pin(
        &self,
        account_id: &str,
        conversation_id: &str,
        target_sent_at: u64,
    ) -> Result<bool, StoreError> {
        let changed = self
            .lock_conn()?
            .execute(
                "DELETE FROM conversation_pins
             WHERE account_id=?1 AND conversation_id=?2
               AND target_sent_at=?3",
                params![account_id, conversation_id, target_sent_at as i64],
            )
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(changed > 0)
    }

    /// Contract 1.138 (§4.130): stamp the conversation's draft timestamp —
    /// the body never passes through here (the desktop keeps draft text in
    /// its own safeStorage; the connector sees only the official draft
    /// record's clock). One row per conversation, the `conversation_pins`
    /// table shape minus the pin identity columns. Returns whether a
    /// conversation row was addressed (the caller answers
    /// CONVERSATION_NOT_FOUND otherwise); re-saving the same conversation
    /// replaces its stamp.
    pub fn save_conversation_draft(
        &self,
        account_id: &str,
        conversation_id: &str,
        draft_timestamp: u64,
    ) -> Result<bool, StoreError> {
        let conn = self.lock_conn()?;
        let addressed: Option<i64> = conn
            .query_row(
                "SELECT 1 FROM conversations WHERE id=?1 AND account_id=?2",
                params![conversation_id, account_id],
                |row| row.get(0),
            )
            .optional()
            .map_err(|error| StoreError::Unavailable(Some(error)))?;
        if addressed.is_none() {
            return Ok(false);
        }
        conn.execute(
            "INSERT INTO conversation_drafts(
                account_id, conversation_id, draft_timestamp
             ) VALUES(?1, ?2, ?3)
             ON CONFLICT(account_id, conversation_id) DO UPDATE SET
               draft_timestamp=excluded.draft_timestamp",
            params![account_id, conversation_id, draft_timestamp as i64],
        )
        .map_err(|error| StoreError::Unavailable(Some(error)))?;
        Ok(true)
    }

    /// 契约 1.207（M5）：写入会话外观——官方八个字段对位。
    ///
    /// 全量覆盖语义（官方整体写这四个 appearance 属性）；None = 清除该面。
    /// 返回是否命中会话（未命中 → 调用方答 CONVERSATION_NOT_FOUND）。
