    #[test]
    fn single_account_lifecycle_acceptance() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let message = MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: "atomic-1".into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "incoming",
            sender_id: "sender".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: 1_700_000_000_000,
            received_at: None,
            text: Some("atomic".into()),
            text_bytes: Some(6),
            text_truncated: false,
            text_retrievable: true,
            status: "received",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            admin_deleted: false,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        let event = EventLogWrite {
            epoch: store
                .account_engine_epoch(&account.id)
                .unwrap()
                .unwrap_or(0),
            account_id: Some(account.id.clone()),
            event_type: "message.upserted".into(),
        };
        assert!(
            store
                .insert_message_with_event(&message, None, Some("atomic"), true, &event)
                .unwrap()
        );
        let page = store.events_page(Some(0), None, 10).unwrap();
        assert_eq!(page.events.len(), 1);
        assert_eq!(page.events[0].event_type, "message.upserted");
        assert_eq!(
            page.events[0].account_id.as_deref(),
            Some(account.id.as_str())
        );
        let seq = page.events[0].seq;

        // 1. restart: message and event survive.
        drop(store);
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let count: i64 = store
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT COUNT(*) FROM messages WHERE id='atomic-1'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(count, 1);
        let records = store.events_page(Some(0), None, 10).unwrap();
        assert_eq!(records.events.len(), 1);
        assert_eq!(records.events[0].event_type, "message.upserted");

        // 2. unlink keeps history and bumps epoch.
        store.set_event_cursor("desktop", seq, 1).unwrap();
        store.mark_account_device_unlinked("+15555550100").unwrap();
        assert_eq!(store.account_engine_epoch(&account.id).unwrap(), Some(1));
        let count: i64 = store
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT COUNT(*) FROM messages WHERE id='atomic-1'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(count, 1);

        // 3. relink bumps again; cursor replay is durable.
        store
            .mark_account_ready_by_id(&account.id, "upstream")
            .unwrap();
        assert_eq!(store.account_engine_epoch(&account.id).unwrap(), Some(2));
        let attempt = store
            .record_send_attempt("atomic-1", &account.id, "req-1", "dispatch-1", 2)
            .unwrap();
        store.settle_send_attempt(attempt, "ok", None).unwrap();
        let settled: (Option<i64>, Option<String>) = store
            .conn
            .lock()
            .unwrap()
            .query_row(
                "SELECT returned_at, result FROM send_attempt WHERE attempt_id=?1",
                [attempt],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert!(settled.0.is_some());
        assert_eq!(settled.1.as_deref(), Some("ok"));
        drop(store);
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        assert_eq!(store.event_cursor("desktop").unwrap(), Some((seq, 1)));
    }

