    #[test]
    fn event_log_rolls_back_with_product_transaction() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let result: Result<(), StoreError> = store.write_transaction(|tx| {
            append_event_log_on(tx, 1, Some("a"), "must.rollback")?;
            Err(StoreError::Unavailable(None))
        });
        assert!(result.is_err());
        let count: i64 = store
            .conn
            .lock()
            .unwrap()
            .query_row("SELECT COUNT(*) FROM event_log", [], |row| row.get(0))
            .unwrap();
        assert_eq!(count, 0);

        store
            .write_transaction(|tx| {
                append_event_log_on(tx, 1, Some("a"), "must.commit")?;
                Ok(())
            })
            .unwrap();
        let count: i64 = store
            .conn
            .lock()
            .unwrap()
            .query_row("SELECT COUNT(*) FROM event_log", [], |row| row.get(0))
            .unwrap();
        assert_eq!(count, 1);
    }

    // ---- 契约 1.283（§4.267）：thin ledger + 头部保留窗 + 游标代际 --------

    /// One ledger page through the public face, with the token this ledger
    /// currently hands out (the cold-start reset is the bootstrap path a real
    /// subscriber uses).
    fn ledger_page(
        store: &Store,
        after: Option<i64>,
        token: Option<&str>,
        limit: u32,
    ) -> EventLedgerPage {
        store.events_page(after, token, limit).unwrap()
    }

    fn ledger_token(store: &Store) -> String {
        ledger_page(store, None, None, 10).token
    }

    fn append_events(store: &Store, count: usize) -> Vec<i64> {
        (0..count)
            .map(|index| {
                store
                    .append_event_log(
                        1,
                        Some("a"),
                        if index % 2 == 0 {
                            "message.upserted"
                        } else {
                            "conversation.changed"
                        },
                    )
                    .unwrap()
            })
            .collect()
    }

    /// The cursor face: a cold start resets, a stamped page resumes, the
    /// truncation flag is honest, and a page never carries a payload.
    #[test]
    fn event_ledger_pages_forward_under_one_token() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        append_events(&store, 3);

        let cold = ledger_page(&store, None, None, 10);
        assert!(cold.reset);
        assert_eq!(cold.reset_reason, Some("coldStart"));
        assert!(cold.events.is_empty(), "a reset never clamps events");
        assert_eq!(cold.trimmed_through_seq, 0);
        assert_eq!(cold.next_after_seq, 0);
        assert!(!cold.truncated);
        let token = cold.token.clone();
        assert_eq!(token.len(), 32, "the token is one random generation stamp");

        let page = ledger_page(&store, Some(0), Some(&token), 10);
        assert!(!page.reset);
        assert_eq!(page.reset_reason, None);
        assert_eq!(page.events.len(), 3);
        assert_eq!(page.events[0].seq, 1);
        assert_eq!(page.events[0].event_type, "message.upserted");
        assert_eq!(page.events[0].account_id.as_deref(), Some("a"));
        assert_eq!(page.next_after_seq, 3);
        assert!(!page.truncated);
        // Thin: the wire row carries the pointer and its stamp, never a body.
        let wire = serde_json::to_value(&page.events[0]).unwrap();
        assert_eq!(wire["type"], json!("message.upserted"));
        assert!(wire.get("payload").is_none());
        assert!(wire.get("createdAt").is_some());

        let first = ledger_page(&store, Some(0), Some(&token), 2);
        assert_eq!(first.events.len(), 2);
        assert_eq!(first.next_after_seq, 2);
        assert!(first.truncated, "a third row exists beyond this page");

        let rest = ledger_page(&store, Some(first.next_after_seq), Some(&token), 2);
        assert_eq!(rest.events.len(), 1);
        assert_eq!(rest.events[0].seq, 3);
        assert!(!rest.truncated);

        let idle = ledger_page(&store, Some(3), Some(&token), 2);
        assert!(idle.events.is_empty());
        assert_eq!(idle.next_after_seq, 3, "an idle poll keeps the cursor put");
    }

    /// The four reset criteria, each on its own: a rotated token, no cursor at
    /// all, a cursor below the floor, and a cursor ahead of the ledger.
    #[test]
    fn event_ledger_resets_on_token_floor_and_head() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        append_events(&store, 4);
        let token = ledger_token(&store);

        let mismatched = ledger_page(&store, Some(1), Some("not-this-generation"), 10);
        assert!(mismatched.reset);
        assert_eq!(mismatched.reset_reason, Some("tokenMismatch"));
        assert!(mismatched.events.is_empty());

        let cold = ledger_page(&store, None, None, 10);
        assert_eq!(cold.reset_reason, Some("coldStart"));

        // Trim the first two rows: a cursor that points at them is dead.
        let retention = EventLogRetention {
            max_age_ms: u64::MAX,
            max_rows: 2,
            max_bytes: u64::MAX,
        };
        let trimmed = store
            .trim_event_log_with(crate::link::now_ms(), retention)
            .unwrap();
        assert_eq!(trimmed.removed, 2);
        assert_eq!(trimmed.trimmed_through_seq, 2);

        let below = ledger_page(&store, Some(1), Some(&token), 10);
        assert!(below.reset);
        assert_eq!(below.reset_reason, Some("belowFloor"));
        assert_eq!(below.trimmed_through_seq, 2);
        assert_eq!(below.next_after_seq, 2);
        assert!(below.events.is_empty());

        let ahead = ledger_page(&store, Some(99), Some(&token), 10);
        assert!(ahead.reset);
        assert_eq!(ahead.reset_reason, Some("aheadOfLog"));

        // The floor itself is a valid cursor: it neither resets nor skips.
        let at_floor = ledger_page(&store, Some(2), Some(&token), 10);
        assert!(!at_floor.reset);
        assert_eq!(at_floor.events.first().map(|event| event.seq), Some(3));
        assert_eq!(at_floor.events.len(), 2);
    }

    /// The head window: age, row count and bytes each cut on their own, the
    /// floor follows the rows, and a second pass over the same ledger is a
    /// quiet no-op (the floor never moves backwards).
    #[test]
    fn event_ledger_trim_honours_age_rows_and_bytes() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let now = crate::link::now_ms();
        append_events(&store, 10);
        // Five rows age out; the newest five stay inside the window.
        store
            .conn
            .lock()
            .unwrap()
            .execute(
                "UPDATE event_log SET created_at=?1 WHERE seq <= 5",
                params![now.saturating_sub(120_000) as i64],
            )
            .unwrap();

        let age = store
            .trim_event_log_with(
                now,
                EventLogRetention {
                    max_age_ms: 60_000,
                    max_rows: i64::MAX,
                    max_bytes: u64::MAX,
                },
            )
            .unwrap();
        assert_eq!(age.removed, 5);
        assert_eq!(age.trimmed_through_seq, 5);
        assert_eq!(age.rows, 5);

        // The row cap binds next: five rows in, keep two.
        let rows = store
            .trim_event_log_with(
                now,
                EventLogRetention {
                    max_age_ms: u64::MAX,
                    max_rows: 2,
                    max_bytes: u64::MAX,
                },
            )
            .unwrap();
        assert_eq!(rows.removed, 3);
        assert_eq!(rows.trimmed_through_seq, 8);
        assert_eq!(rows.rows, 2);

        // Then the byte ceiling: the row cost is 27 + type + account + 12, so
        // the newest row (60 bytes) fits a 100-byte ceiling and the one behind
        // it (56 more) does not.
        let bytes = store
            .trim_event_log_with(
                now,
                EventLogRetention {
                    max_age_ms: u64::MAX,
                    max_rows: i64::MAX,
                    max_bytes: 100,
                },
            )
            .unwrap();
        assert_eq!(bytes.removed, 1, "one row's cost fits, two do not");
        assert_eq!(bytes.trimmed_through_seq, 9);
        assert_eq!(bytes.rows, 1);

        // Idempotent, and the floor never regresses on a wider window.
        let again = store
            .trim_event_log_with(
                now,
                EventLogRetention {
                    max_age_ms: u64::MAX,
                    max_rows: 100,
                    max_bytes: u64::MAX,
                },
            )
            .unwrap();
        assert_eq!(again.removed, 0);
        assert_eq!(again.trimmed_through_seq, 9);
        assert_eq!(store.event_log_health().trimmed_through_seq, 9);
        assert!(ledger_page(&store, None, None, 10).reset);
    }

    /// The floor and the deletion are one transaction: a delete that cannot
    /// land leaves the floor exactly where it was (a floor that promises rows
    /// it still has, or rows a floor refuses, is the failure this rules out).
    #[test]
    fn event_ledger_trim_is_atomic_with_the_floor() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        append_events(&store, 4);
        store
            .conn
            .lock()
            .unwrap()
            .execute_batch(
                "CREATE TRIGGER event_ledger_guard BEFORE DELETE ON event_log
                 BEGIN SELECT RAISE(ABORT, 'ledger delete blocked'); END;",
            )
            .unwrap();

        let outcome = store.trim_event_log_with(
            crate::link::now_ms(),
            EventLogRetention {
                max_age_ms: u64::MAX,
                max_rows: 1,
                max_bytes: u64::MAX,
            },
        );
        assert!(
            outcome.is_err(),
            "the aborted delete must not be reported as a trim"
        );
        // Nothing moved: floor 0, all four rows, and the cursor face still
        // serves them.
        let health = store.event_log_health();
        assert_eq!(health.trimmed_through_seq, 0);
        assert_eq!(health.rows, 4);
        let token = ledger_token(&store);
        assert_eq!(
            ledger_page(&store, Some(0), Some(&token), 10).events.len(),
            4
        );

        store
            .conn
            .lock()
            .unwrap()
            .execute_batch("DROP TRIGGER event_ledger_guard;")
            .unwrap();
        let trimmed = store
            .trim_event_log_with(
                crate::link::now_ms(),
                EventLogRetention {
                    max_age_ms: u64::MAX,
                    max_rows: 1,
                    max_bytes: u64::MAX,
                },
            )
            .unwrap();
        assert_eq!(trimmed.removed, 3);
        assert_eq!(trimmed.trimmed_through_seq, 3);
    }

    /// The generation survives a restart: reopening the store keeps the token,
    /// so a subscriber that was closed politely resumes instead of resetting.
    #[test]
    fn event_ledger_generation_survives_reopen() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        append_events(&store, 2);
        let token = ledger_token(&store);
        store
            .trim_event_log_with(
                crate::link::now_ms(),
                EventLogRetention {
                    max_age_ms: u64::MAX,
                    max_rows: 1,
                    max_bytes: u64::MAX,
                },
            )
            .unwrap();
        drop(store);

        let reopened = Store::open(temp.path(), Some(test_store_key())).unwrap();
        assert_eq!(reopened.event_log_health().trimmed_through_seq, 1);
        let page = ledger_page(&reopened, Some(1), Some(&token), 10);
        assert!(!page.reset, "the same generation resumes across a restart");
        assert_eq!(page.events.len(), 1);
        assert_eq!(page.next_after_seq, 2);
    }

    /// The response byte budget stops a page before it crosses the ceiling and
    /// says so — while still delivering the first row, so a caller can always
    /// make progress.
    #[test]
    fn event_ledger_page_respects_the_byte_budget() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        append_events(&store, 6);
        let token = ledger_token(&store);

        let page = store
            .events_page_with(Some(0), Some(&token), 500, 100)
            .unwrap();
        assert_eq!(page.events.len(), 1, "one frame fits the 100-byte budget");
        assert!(page.truncated);
        assert_eq!(page.next_after_seq, 1);

        // The same page under an impossible budget still carries its first row.
        let tiny = store
            .events_page_with(Some(0), Some(&token), 500, 1)
            .unwrap();
        assert_eq!(tiny.events.len(), 1);
        assert!(tiny.truncated);
    }

    /// Account deletion is the token's other rotation point: the account's
    /// rows leave, every other account's rows stay, the receipt counts the
    /// ledger's rows, and the subscriber is told to reset.
    #[test]
    fn event_ledger_account_delete_cascades_and_rotates_the_token() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let doomed = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let kept = store
            .upsert_account_from_signal("+15555550101", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        store
            .append_event_log(1, Some(&doomed.id), "message.upserted")
            .unwrap();
        store
            .append_event_log(1, Some(&kept.id), "message.upserted")
            .unwrap();
        store
            .append_event_log(1, Some(&doomed.id), "conversation.changed")
            .unwrap();
        let before = ledger_token(&store);
        assert_eq!(store.event_log_health().token_generation, 1);

        let receipt = store
            .complete_account_delete_recorded(&doomed.id, None, crate::link::now_ms())
            .unwrap()
            .expect("a live account is deleted");
        assert_eq!(receipt.table_counts.get("event_log"), Some(&2));

        let after = store.event_log_health();
        assert_eq!(after.rows, 1, "only the surviving account's row is left");
        assert_eq!(after.token_generation, 2, "the generation rotated");
        let current = ledger_token(&store);
        assert_ne!(before, current);
        let reset = ledger_page(&store, Some(0), Some(&before), 10);
        assert!(reset.reset);
        assert_eq!(reset.reset_reason, Some("tokenMismatch"));
        assert!(reset.events.is_empty());
        assert_eq!(
            ledger_page(&store, Some(0), Some(&current), 10)
                .events
                .len(),
            1
        );
    }

    /// v50: the stored ledger loses its payload column, keeps its surviving
    /// rows and their seq/type, clears the deleted account's rows, and seeds a
    /// fresh generation at floor 0 — so the first subscriber reset is honest
    /// rather than a replay of a half-thin log.
    #[test]
    fn schema_v50_thin_ledger_migration_drops_payload_and_clears_orphans() {
        let temp = TempDir::new().unwrap();
        let state_dir = temp.path().join("state");
        let path = legacy_store(
            &state_dir,
            20,
            "INSERT INTO accounts(id, signal_account, masked_address, state)
               VALUES('acc-1', '+15555550100', '+15***00', 'ready');
             CREATE TABLE event_log (
               seq INTEGER PRIMARY KEY AUTOINCREMENT,
               epoch INTEGER NOT NULL,
               account_id TEXT,
               type TEXT NOT NULL,
               payload TEXT NOT NULL,
               created_at INTEGER NOT NULL
             );
             CREATE INDEX event_log_account ON event_log(account_id, seq);
             INSERT INTO event_log(epoch, account_id, type, payload, created_at) VALUES
               (1, 'acc-1', 'message.upserted', '{\"body\":\"secret\"}', 100),
               (1, 'gone', 'message.upserted', '{\"body\":\"orphan\"}', 200),
               (1, NULL, 'storage.changed', '{}', 300);",
        );
        // The old ledger really carries payloads and a deleted account's row.
        let legacy = keyed(&path);
        assert!(
            table_column_names(&legacy, "event_log")
                .unwrap()
                .iter()
                .any(|column| column == "payload")
        );
        drop(legacy);

        let store = Store::open(&state_dir, Some(test_store_key())).unwrap();
        let health = store.event_log_health();
        assert!(health.readable);
        assert_eq!(health.rows, 2, "the deleted account's row is an orphan");
        assert_eq!(health.trimmed_through_seq, 0);
        assert_eq!(health.token_generation, 1);
        assert_eq!(health.seq_max, 3, "seq keeps its high-water");

        let check = keyed(&path);
        assert!(
            !table_column_names(&check, "event_log")
                .unwrap()
                .iter()
                .any(|column| column == "payload"),
            "the payload column is gone"
        );
        drop(check);

        let token = ledger_token(&store);
        assert_eq!(token.len(), 32);
        let page = ledger_page(&store, Some(0), Some(&token), 10);
        let types: Vec<&str> = page
            .events
            .iter()
            .map(|event| event.event_type.as_str())
            .collect();
        assert_eq!(types, vec!["message.upserted", "storage.changed"]);
        assert_eq!(page.events[0].seq, 1);
        assert_eq!(page.events[1].seq, 3);
        assert_eq!(
            page.events[1].created_at, 300,
            "the timestamps survived verbatim"
        );
        assert!(
            page.events
                .iter()
                .all(|event| event.account_id.as_deref() != Some("gone"))
        );
    }

    /// The ledger's health face is read-only and reports the same numbers the
    /// trimmer and the retention window use.
    #[test]
    fn event_ledger_health_reports_floor_rows_and_window() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let empty = store.event_log_health();
        assert!(empty.readable);
        assert_eq!(empty.rows, 0);
        assert_eq!(empty.bytes, 0);
        assert_eq!(empty.seq_max, 0);
        assert_eq!(empty.oldest_created_at, None);
        assert_eq!(empty.retention.max_rows, EVENT_LOG_MAX_ROWS);
        assert_eq!(empty.retention.max_bytes, EVENT_LOG_MAX_BYTES);
        assert_eq!(empty.retention.max_age_ms, EVENT_LOG_RETENTION_MS);

        append_events(&store, 3);
        let health = store.event_log_health();
        assert_eq!(health.rows, 3);
        assert!(health.bytes > 3 * 40, "the row cost covers the columns");
        assert_eq!(health.seq_max, 3);
        assert!(health.oldest_created_at.is_some());
        assert!(health.newest_created_at >= health.oldest_created_at);

        let wire = serde_json::to_value(&health).unwrap();
        assert!(
            wire.get("token").is_none(),
            "the token never leaves the store"
        );
        assert_eq!(wire["retention"]["maxRows"], json!(EVENT_LOG_MAX_ROWS));
    }

    /// Every unit-test store is encrypted: the fixture key exercises the same
    /// keyed-open path production uses (optimization-plan Phase 3).
    const TEST_KEY_BYTES: [u8; 32] = [0x5A; 32];

    // ------------------------------------------------------------------
    // §4.123 automatic send-retry queue (store faces)
    // ------------------------------------------------------------------

    /// Seed one §4.123 fixture row: an outgoing text row inserted in the
    /// `sent` placeholder status, then moved to the requested status with
    /// the requested scheduling face straight through the store connection
    /// (the schedule face is queue-internal; only the queue faces write it
    /// in production).
    #[allow(clippy::too_many_arguments)]
    fn seed_retry_row(
        store: &Store,
        account_id: &str,
        conversation_id: &str,
        id: &str,
        client_request_id: &str,
        status: &str,
        first_send_attempted_at: Option<u64>,
        retry_attempt_count: u32,
        next_attempt_at: Option<u64>,
    ) {
        let record = MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: id.into(),
            account_id: account_id.into(),
            conversation_id: conversation_id.into(),
            direction: "outgoing",
            sender_id: "self".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: 1_000,
            received_at: None,
            text: Some("hello".into()),
            text_bytes: Some(5),
            text_truncated: false,
            text_retrievable: true,
            status: "sent",
            client_request_id: Some(client_request_id.into()),
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        assert!(
            store
                .insert_message(&record, Some(client_request_id), Some("hello"), false)
                .unwrap()
        );
        store
            .conn()
            .execute(
                "UPDATE messages SET status=?2, first_send_attempted_at=?3,
                        retry_attempt_count=?4, next_attempt_at=?5
                 WHERE id=?1",
                params![
                    id,
                    status,
                    first_send_attempted_at.map(|value| value as i64),
                    retry_attempt_count as i64,
                    next_attempt_at.map(|value| value as i64),
                ],
            )
            .unwrap();
    }

    /// Runtime state authority (contract 1.275): inventory reconciliation may
    /// not erase a terminal unlink; only an explicit link/whoami answer does.
    #[test]
    fn inventory_upsert_preserves_terminal_unlink_until_explicit_ready() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        store
            .mark_account_device_unlinked("+15555550100")
            .unwrap()
            .expect("account row");

        let after_inventory = store
            .upsert_account_from_signal("+15555550100", Some(2), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(after_inventory.state, "device_unlinked");
        assert_eq!(after_inventory.state_evidence.as_deref(), Some("upstream"));

        let after_ready = store
            .mark_account_ready_by_id(&account.id, "engine")
            .unwrap()
            .expect("account row");
        assert_eq!(after_ready.state, "ready");
        assert_eq!(after_ready.state_evidence.as_deref(), Some("engine"));
        assert!(after_ready.state_observed_at.is_some());
    }

    /// Contract 1.277: state revision moves only on a real transition, never
    /// on a plain inventory re-read.
    #[test]
    fn account_state_revision_bumps_only_on_real_transitions() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(account.state_revision, 1);

        let inventory = store
            .upsert_account_from_signal("+15555550100", Some(2), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(inventory.state_revision, 1);

        let unlinked = store
            .mark_account_device_unlinked("+15555550100")
            .unwrap()
            .expect("account row");
        assert_eq!(unlinked.state_revision, 2);

        let inventory_again = store
            .upsert_account_from_signal("+15555550100", Some(3), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(inventory_again.state_revision, 2);

        let ready = store
            .mark_account_ready_by_id(&account.id, "engine")
            .unwrap()
            .expect("account row");
        assert_eq!(ready.state_revision, 3);
    }

    /// The wire projection carries the new evidence only when present and
    /// keeps `stale:false` off the frame (additive shape).
    #[test]
    fn terminal_state_evidence_serializes_additively() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let terminal = store
            .mark_account_device_unlinked("+15555550100")
            .unwrap()
            .expect("account row");
        let value = serde_json::to_value(terminal).unwrap();
        assert_eq!(value["state"], "device_unlinked");
        assert_eq!(value["stateEvidence"], "upstream");
        assert!(value.get("stale").is_none());
        assert!(value["stateObservedAt"].as_u64().is_some());
    }

    /// 契约 1.207（M5）：会话外观八字段——官方 ConversationAttributesType 对位。
    #[test]
    fn conversation_appearance_round_trip() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();

        // 默认：外观全 None，但 autoBubbleColor 缺省 true（官方缺省）。
        assert_eq!(
            store
                .conversation_appearance(&account.id, &conversation.id)
                .unwrap(),
            Some((None, None, None, true, None, None, None))
        );

        // 写入自定义色（官方 CustomColorType 结构体）+ 壁纸预设 + 深色变暗。
        let custom = serde_json::json!({
            "start": { "hue": 210, "saturation": 60, "lightness": 40 },
            "end": { "hue": 220, "saturation": 55 },
            "deg": 135
        });
        assert!(
            store
                .set_conversation_appearance(
                    &account.id,
                    &conversation.id,
                    Some("custom"),
                    Some(&custom),
                    Some("custom-7"),
                    false,
                    Some(3),
                    Some("cG9pbnRlci1hYmM="),
                    Some(true),
                )
                .unwrap()
        );
        assert_eq!(
            store
                .conversation_appearance(&account.id, &conversation.id)
                .unwrap(),
            Some((
                Some("custom".to_owned()),
                // customColor 是结构体：往返必须保持对象形状（不是字符串）。
                Some(custom.clone()),
                Some("custom-7".to_owned()),
                false,
                Some(3),
                Some("cG9pbnRlci1hYmM=".to_owned()),
                Some(true),
            ))
        );

        // 全量覆盖清空：None 全部生效（不是部分更新）。
        assert!(
            store
                .set_conversation_appearance(
                    &account.id,
                    &conversation.id,
                    None,
                    None,
                    None,
                    true,
                    None,
                    None,
                    None,
                )
                .unwrap()
        );
        assert_eq!(
            store
                .conversation_appearance(&account.id, &conversation.id)
                .unwrap(),
            Some((None, None, None, true, None, None, None))
        );

        // 未命中会话：写答 false、读答 None。
        assert!(
            !store
                .set_conversation_appearance(
                    &account.id,
                    "missing",
                    Some("RED"),
                    None,
                    None,
                    true,
                    None,
                    None,
                    None,
                )
                .unwrap()
        );
        assert_eq!(
            store
                .conversation_appearance(&account.id, "missing")
                .unwrap(),
            None
        );
    }
    /// 契约 1.206（M5）：通知细分四开关——与 muted 正交（muted 是总闸，
    /// 这四个是「静音之后仍要提醒什么」）。官方 ConversationAttributesType 同形。
    #[test]
    fn conversation_notification_prefs_round_trip() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();

        // 默认全 false（DDL 缺省，不发明 true）。
        assert_eq!(
            store
                .conversation_notification_prefs(&account.id, &conversation.id)
                .unwrap(),
            Some((false, false, false, false))
        );

        // 打开「mentions + replies」（最常用组合：群静音但 @我/回复我要响）。
        assert!(
            store
                .set_conversation_notification_prefs(
                    &account.id,
                    &conversation.id,
                    false,
                    true,
                    true,
                    false,
                )
                .unwrap()
        );
        assert_eq!(
            store
                .conversation_notification_prefs(&account.id, &conversation.id)
                .unwrap(),
            Some((false, true, true, false))
        );

        // 整体覆盖（不做部分更新）：翻成 calls + reminders。
        assert!(
            store
                .set_conversation_notification_prefs(
                    &account.id,
                    &conversation.id,
                    true,
                    false,
                    false,
                    true,
                )
                .unwrap()
        );
        assert_eq!(
            store
                .conversation_notification_prefs(&account.id, &conversation.id)
                .unwrap(),
            Some((true, false, false, true))
        );

        // 未命中会话：写答 false、读答 None（缺席 = 未知）。
        assert!(!store
            .set_conversation_notification_prefs(
                &account.id, "missing", true, true, true, true,
            )
            .unwrap());
        assert_eq!(
            store
                .conversation_notification_prefs(&account.id, "missing")
                .unwrap(),
            None
        );
    }

    /// 契约 1.208（M4b-2）：按已读水位自动锚定最旧未读——官方
    /// `metrics.oldestUnseen` 路径。无水位的未读面必须回落 None（不发明锚点）。
    #[test]
    fn list_messages_around_oldest_unread_derives_from_watermark() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        // 20 条入站，sent_at 用毫秒刻度（t=1000,2000..20000）——与
        // read_watermark_ms 同单位，避免刻度错配。
        for tick in 1..=20i64 {
            store
                .seed_message_row_for_test_at(&account.id, &conversation.id, tick * 1000)
                .unwrap();
        }

        // 无水印（全部未读）→ 最旧未读 = t=1，窗口从它开始、只有 newer 侧。
        let page = store
            .list_messages_around_oldest_unread(&account.id, &conversation.id, 5)
            .unwrap()
            .expect("未读面存在");
        assert_eq!(
            page.items.first().map(|row| row.sent_at as i64),
            Some(1000),
            "锚在最旧（t=1s），older 侧为空"
        );
        // 锚在最旧 → older 侧取不到（0 条），窗口只有 actor + newer(limit-1)
        // 里实际存在的条数。limit=5 → newer 目标 2 条，共 3 行。
        // 这是官方同姿：任一侧不足时按实际返回，不补假行。
        assert_eq!(page.items.len(), 3, "older 侧空 → 窗口只有锚 + newer");

        // 水印推到 t=15 → 最旧未读 = t=16，窗口居中。
        store
            .conn()
            .execute(
                "UPDATE conversations SET read_watermark_ms=?2 WHERE id=?1",
                params![conversation.id, 15_000i64],
            )
            .unwrap();
        let page = store
            .list_messages_around_oldest_unread(&account.id, &conversation.id, 5)
            .unwrap()
            .expect("仍有未读");
        let anchor_at = page
            .items
            .iter()
            .position(|row| row.sent_at as i64 > 15_000)
            .expect("窗口含超水位行");
        assert!(anchor_at <= 2, "锚应在窗口中段（older 侧 2 条）");

        // 水印推到 20（全部已读）→ 无未读，答 None。
        store
            .conn()
            .execute(
                "UPDATE conversations SET read_watermark_ms=?2 WHERE id=?1",
                params![conversation.id, 20_000i64],
            )
            .unwrap();
        assert!(
            store
                .list_messages_around_oldest_unread(&account.id, &conversation.id, 5)
                .unwrap()
                .is_none(),
            "全部已读 → None（不发明锚点）"
        );
    }
    /// 契约 1.205（M5）：草稿完整面持久化——官方 ConversationAttributesType 的
    /// draft/draftAttachments/draftBodyRanges/draftIsViewOnce/draftEditMessage
    /// 五字段。此前只存时间戳（正文仅活在桌面本地，跨设备/重装即丢）。
    #[test]
    fn conversation_draft_persists_the_full_surface() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();

        // 无草稿时读面为 None（缺席不发明）。
        assert!(
            store
                .conversation_draft_full(&account.id, &conversation.id)
                .unwrap()
                .is_none()
        );

        // 全字段写入。
        let saved = store
            .save_conversation_draft_full(
                &account.id,
                &conversation.id,
                1_700_000_000_000,
                Some("写了一半的话"),
                Some(r#"[{"id":"a1"}]"#),
                Some(r#"[{"start":0,"length":2}]"#),
                true,
                Some(&serde_json::json!({
                    "editHistoryLength": 2,
                    "body": "改过的内容",
                    "targetMessageId": "msg-target-1"
                })),
            )
            .unwrap();
        assert!(saved, "会话存在 → 保存成功");

        let (ts, body, attachments, ranges, view_once, edit_target) = store
            .conversation_draft_full(&account.id, &conversation.id)
            .unwrap()
            .expect("draft present");
        assert_eq!(ts, 1_700_000_000_000, "时间戳原样往返");
        assert_eq!(body.as_deref(), Some("写了一半的话"), "正文持久化");
        assert_eq!(attachments.as_deref(), Some(r#"[{"id":"a1"}]"#));
        assert_eq!(ranges.as_deref(), Some(r#"[{"start":0,"length":2}]"#));
        assert!(view_once, "viewOnce 位持久化");
        // 官方 DraftEditMessageType 是六字段对象：往返必须保持完整形状，
        // 而不是只留一个 target id（审计项 #6）。
        let edit_target = edit_target.expect("edit message present");
        assert_eq!(edit_target["editHistoryLength"], serde_json::json!(2));
        assert_eq!(edit_target["body"], serde_json::json!("改过的内容"));
        assert_eq!(
            edit_target["targetMessageId"],
            serde_json::json!("msg-target-1")
        );

        // 覆盖写：正文清空但时间戳推进（官方 draftChanged 语义）。
        store
            .save_conversation_draft_full(
                &account.id,
                &conversation.id,
                1_700_000_100_000,
                None,
                None,
                None,
                false,
                None,
            )
            .unwrap();
        let (ts, body, _, _, view_once, _) = store
            .conversation_draft_full(&account.id, &conversation.id)
            .unwrap()
            .expect("draft still present");
        assert_eq!(ts, 1_700_000_100_000, "时间戳推进");
        assert!(body.is_none(), "正文清空");
        assert!(!view_once, "viewOnce 复位");

        // 不存在的会话 → false（调用方答 CONVERSATION_NOT_FOUND）。
        assert!(
            !store
                .save_conversation_draft_full(
                    &account.id,
                    "missing-conversation",
                    1,
                    None,
                    None,
                    None,
                    false,
                    None,
                )
                .unwrap()
        );
    }
    /// 契约 1.204（M4b）：以锚点为中心取窗——官方
    /// `getConversationRangeCenteredOnMessage` 对位。验证三段的边界语义：
    /// 升序、锚在位、两侧按 limit 均分、锚缺席诚实拒。
    #[test]
    fn list_messages_around_centers_on_the_anchor() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        // 造 20 条：t=1..=20（升序），锚定在 t=10。
        for tick in 1..=20i64 {
            store
                .seed_message_row_for_test_at(&account.id, &conversation.id, tick)
                .unwrap();
        }
        let anchor_id = format!("seed-{}-10", conversation.id);
        let page = store
            .list_messages_around(&account.id, &conversation.id, &anchor_id, 9)
            .unwrap();
        // limit=9 → older 4 / anchor 1 / newer 4 = 9 行，升序排列。
        assert_eq!(page.items.len(), 9, "三段合计不超过 limit");
        let sent: Vec<i64> = page.items.iter().map(|row| row.sent_at as i64).collect();
        assert_eq!(
            sent,
            vec![6, 7, 8, 9, 10, 11, 12, 13, 14],
            "锚在正中且整体升序"
        );
        assert!(
            page.items.iter().any(|row| row.id == anchor_id),
            "锚行本身在窗口内"
        );
        // older 取满额 → next_cursor 指向更早一侧。
        assert!(page.next_cursor.is_some(), "older 满额时游标存在");
        // 锚不在本地/已删 → 诚实拒（不重新锚定）。
        assert!(matches!(
            store.list_messages_around(&account.id, &conversation.id, "missing", 9),
            Err(StoreError::InvalidCursor)
        ));
    }

    /// 契约 1.209（§4.209）：群名册投影——官方 membersV2 对位。
    /// 核心纪律：**缺席 = 名册未知**，绝不回空数组冒充「已知且为空」。
    #[test]
    fn conversation_summary_projects_the_group_roster() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        // ① 有完整官方五字段名册的群（aci/role/joinedAtVersion/labelString/labelEmoji）。
        store
            .upsert_contact(
                &account.id,
                "group",
                "group-key-a",
                "Team A",
                Some(r#"{"members":[{"uuid":"aci-1","role":"administrator","joinedAtVersion":7,"labelString":"lead","labelEmoji":"⭐"},{"uuid":"aci-2","role":1}]}"#),
                10,
            )
            .unwrap();
        // ② 有成员字段但为空的群（捕获明确说「零成员」——照实返回空数组）。
        store
            .upsert_contact(
                &account.id,
                "group",
                "group-key-b",
                "Team B",
                Some(r#"{"members":[]}"#),
                10,
            )
            .unwrap();
        // ③ 无 extra 的群（名册未知）。
        store
            .upsert_contact(&account.id, "group", "group-key-c", "Team C", None, 10)
            .unwrap();

        store
            .ensure_conversation(&account.id, "group", "group-key-a", "Team A")
            .unwrap();
        store
            .ensure_conversation(&account.id, "group", "group-key-b", "Team B")
            .unwrap();
        store
            .ensure_conversation(&account.id, "group", "group-key-c", "Team C")
            .unwrap();
        // ④ 直聊行（永不带名册）。
        store
            .ensure_conversation(&account.id, "direct", "+15555550109", "Peer")
            .unwrap();

        let page = store.list_conversations(&account.id, 20, None).unwrap();
        let by_title = |title: &str| {
            page.items
                .iter()
                .find(|row| row.title == title)
                .map(|row| serde_json::to_value(row).unwrap())
                .expect("row present")
        };

        // ① 完整名册：按官方 GroupV2MemberType 五字段投影。
        let a = by_title("Team A");
        let members = a["members"].as_array().expect("members array");
        assert_eq!(members.len(), 2);
        // aci 是唯一必填身份键（uuid 优先映射）。
        assert_eq!(members[0]["aci"], serde_json::json!("aci-1"));
        assert_eq!(members[0]["role"], serde_json::json!("administrator"));
        assert_eq!(members[0]["joinedAtVersion"], serde_json::json!(7));
        assert_eq!(members[0]["labelString"], serde_json::json!("lead"));
        assert_eq!(members[0]["labelEmoji"], serde_json::json!("⭐"));
        // 第二成员：role 用 proto 数字 1 → 归一化成 "default"；
        // 其余三键捕获没有 → 缺席（不发明）。
        assert_eq!(members[1]["aci"], serde_json::json!("aci-2"));
        assert_eq!(members[1]["role"], serde_json::json!("default"));
        assert!(members[1].get("joinedAtVersion").is_none());
        assert!(members[1].get("labelString").is_none());
        assert!(members[1].get("labelEmoji").is_none());
        // 官方无 memberCount 字段——本项目不自造（审计项 #1）。
        assert!(
            a.get("memberCount").is_none(),
            "memberCount 是自造字段，已删"
        );

        // ② 空名册：照实给空数组（捕获说了零成员）。
        let b = by_title("Team B");
        assert_eq!(b["members"].as_array().map(|items| items.len()), Some(0));

        // ③ 无 extra：名册未知 → members 键缺席（不回空数组冒充已知为空）。
        let c = by_title("Team C");
        assert!(c.get("members").is_none(), "无名册必须缺席");

        // ④ 直聊行恒不带名册。
        let direct = by_title("Peer");
        assert!(direct.get("members").is_none());
    }
    /// 契约 1.203（§4.203）：会话命名梯材料——systemName 取通讯录 title、
    /// username 取 contacts.extra；掩码/占位不算材料；全 miss 三键皆缺席。
    /// 断言面走 serde（wire 形状即契约），不用结构体字段直读。
    #[test]
    fn conversation_summary_projects_the_naming_ladder_additively() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        // ① 有通讯录名 + username 的联系人。
        store
            .upsert_contact(
                &account.id,
                "contact",
                "+15555550101",
                "Alice",
                Some(r#"{"username":"alice.01"}"#),
                10,
            )
            .unwrap();
        // ② 只有掩码占位的联系人（不是材料）。
        store
            .upsert_contact(&account.id, "contact", "+15555550102", "8fc***e2", None, 10)
            .unwrap();
        // ③ 无 contacts 行的陌生人。
        store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Alice")
            .unwrap();
        store
            .ensure_conversation(&account.id, "direct", "+15555550102", "8fc***e2")
            .unwrap();
        store
            .ensure_conversation(&account.id, "direct", "+15555550103", "ghost")
            .unwrap();

        let page = store.list_conversations(&account.id, 10, None).unwrap();
        // 定位用**协议标识**而非 title：ConversationSummary 不投影存储层的
        // peer_key，而是把它归一化成 e164 / serviceId / groupId 三个语义字段
        //（契约 1.138 §4.129）。用 title 定位等于绕过协议投影——本轮自纠。
        let by_e164 = |e164: &str| {
            page.items
                .iter()
                .find(|row| row.e164.as_deref() == Some(e164))
                .map(|row| serde_json::to_value(row).unwrap())
                .unwrap_or_else(|| panic!("row for {e164} present"))
        };

        let alice = by_e164("+15555550101");
        assert_eq!(alice["systemName"], serde_json::json!("Alice"));
        assert_eq!(alice["username"], serde_json::json!("alice.01"));
        // profile 名由桌面三源链补，connector 侧恒缺席。
        assert!(alice.get("profileName").is_none());

        // 掩码占位不是材料：systemName 不出现。
        let masked = by_e164("+15555550102");
        assert!(
            masked.get("systemName").is_none(),
            "掩码 title 不是命名材料"
        );
        assert!(masked.get("username").is_none());
        // 掩码值仍原样留在 title 面（呈现层自行降级）。
        assert_eq!(masked["title"], serde_json::json!("8fc***e2"));

        // 无 contacts 行：两键都缺席（缺席 = 未知）。
        let ghost = by_e164("+15555550103");
        assert!(ghost.get("systemName").is_none());
        assert!(ghost.get("username").is_none());
        // title 面语义零变化（旧消费者逐字不变）。
        assert_eq!(ghost["title"], serde_json::json!("ghost"));
    }
    /// Read one row's §4.123 face: (status, first_send_attempted_at,
    /// retry_attempt_count, next_attempt_at).
    fn retry_face(store: &Store, id: &str) -> (String, Option<i64>, i64, Option<i64>) {
        store
            .conn()
            .query_row(
                "SELECT status, first_send_attempted_at, retry_attempt_count,
                        next_attempt_at
                 FROM messages WHERE id=?1",
                params![id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .unwrap()
    }

    /// The window judgment: a queue entry whose `first_send_attempted_at +
    /// 24 h` has run out dies in the queue — the claim pass retires its
    /// Contract 1.176 (§4.176): the raw `JsonContact.username` the sync
    /// captured into the contact row's `extra` JSON projects on the
    /// `contacts.list` wire and the read-time username map; absent,
    /// blank, and over-budget markers all answer absent (the informative-
    /// keys discipline — pre-1.176 rows read byte-identical).
    #[test]
    fn list_contacts_projects_captured_username() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        store
            .upsert_synced_contacts(
                &account.id,
                &[
                    SyncedContact {
                        kind: "contact",
                        peer_key: "+15555550101",
                        title: "Alice Contact",
                        extra: Some(r#"{"username":"alice.01"}"#),
                    },
                    SyncedContact {
                        kind: "contact",
                        peer_key: "+15555550102",
                        title: "Budget Peer",
                        extra: Some(&format!(r#"{{"username":"{}"}}"#, "x".repeat(65))),
                    },
                    SyncedContact {
                        kind: "contact",
                        peer_key: "+15555550103",
                        title: "No Username",
                        extra: None,
                    },
                ],
                1_725_300_000,
            )
            .unwrap();

        let page = store.list_contacts(&account.id, None, 50, None).unwrap();
        let wire = serde_json::to_value(&page.items).unwrap();
        assert_eq!(wire[0]["username"], serde_json::json!("alice.01"));
        assert!(wire[1].get("username").is_none(), "over-budget drops");
        assert!(wire[2].get("username").is_none(), "absent stays absent");
        // group rows never carry a username face
        store
            .upsert_synced_contacts(
                &account.id,
                &[SyncedContact {
                    kind: "group",
                    peer_key: "ZmFrZS1ncm91cC0x",
                    title: "Fixture Group",
                    extra: Some(r#"{"username":"group.01","memberCount":1}"#),
                }],
                1_725_300_000,
            )
            .unwrap();
        let with_group = store.list_contacts(&account.id, None, 50, None).unwrap();
        let group_wire = serde_json::to_value(&with_group.items).unwrap();
        let group_row = group_wire
            .as_array()
            .unwrap()
            .iter()
            .find(|row| row["kind"] == "group")
            .expect("the group row projects");
        assert!(
            group_row.get("username").is_none(),
            "JsonGroup has no username face — the key never rides a group row"
        );

        let usernames = store.contact_username_map(&account.id).unwrap();
        assert_eq!(
            usernames.get("+15555550101").map(String::as_str),
            Some("alice.01")
        );
        assert!(!usernames.contains_key("+15555550102"));
        assert!(!usernames.contains_key("+15555550103"));
    }

    /// schedule and claims nothing for it (the row stays `failed`,
    /// terminal), while a live-window control row in the same pass is
    /// claimed normally.
    #[test]
    fn retry_window_exhaustion_kills_the_queue_entry() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let now: u64 = 1_800_000_000_000;
        seed_retry_row(
            &store,
            &account.id,
            &conversation.id,
            "m-dead",
            "req-dead",
            "failed",
            Some(now - crate::store::RETRY_WINDOW_MS - 1_000),
            3,
            Some(now - 500),
        );
        seed_retry_row(
            &store,
            &account.id,
            &conversation.id,
            "m-live",
            "req-live",
            "failed",
            Some(now - 60_000),
            1,
            Some(now - 500),
        );
        let claims = store.claim_due_retries(now, 10).unwrap();
        assert_eq!(
            claims
                .iter()
                .map(|claim| claim.message_id.as_str())
                .collect::<Vec<_>>(),
            ["m-live"],
            "the window-dead entry is judged, the live one claimed"
        );
        // The dead row: still failed (terminal), schedule retired — the
        // anchor and the attempt count stay as the terminal record, but
        // nothing is scheduled, so no later pass can ever claim it again.
        let (status, first, count, next) = retry_face(&store, "m-dead");
        assert_eq!(status, "failed");
        assert_eq!(count, 3);
        assert!(first.is_some());
        assert_eq!(next, None);
        // The claimed row: pending, face intact for the next settlement.
        let (status, _, _, _) = retry_face(&store, "m-live");
        assert_eq!(status, "pending");
    }

    /// The official backoff curve (190 ms · 1.9^(n-1), capped at 15
    /// minutes) drives the schedule face: the first automatic retry beat
    /// lands at +190 ms, the second at +361 ms, and the window anchor never
    /// moves across retries (a retry does not reset the window).
    #[test]
    fn retry_backoff_schedule_follows_the_official_curve() {
        assert_eq!(Store::retry_backoff_delay_ms(1), 190);
        assert_eq!(Store::retry_backoff_delay_ms(2), 361);
        assert_eq!(Store::retry_backoff_delay_ms(15), 15 * 60 * 1_000);
        assert_eq!(Store::retry_backoff_delay_ms(40), 15 * 60 * 1_000);
        let mut previous = 0;
        for attempt in 1..=40u32 {
            let delay = Store::retry_backoff_delay_ms(attempt);
            assert!(delay >= previous, "the curve never shrinks");
            assert!(delay <= 15 * 60 * 1_000, "the cap holds");
            previous = delay;
        }

        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let first_failure: u64 = 1_800_000_000_000;
        seed_retry_row(
            &store,
            &account.id,
            &conversation.id,
            "m-curve",
            "req-curve",
            "pending",
            None,
            0,
            None,
        );
        store
            .settle_send_failed(
                "m-curve",
                first_failure,
                crate::store::SendRetrySchedule::Backoff,
                None,
            )
            .unwrap()
            .unwrap();
        let (_, first, count, next) = retry_face(&store, "m-curve");
        assert_eq!(
            (first, count, next),
            (
                Some(first_failure as i64),
                1,
                Some((first_failure + 190) as i64)
            )
        );
        // Attempt 2: claim flips it pending, the send fails again, the
        // schedule advances by the second beat and the anchor stays put.
        let claims = store.claim_due_retries(first_failure + 190, 10).unwrap();
        assert_eq!(claims.len(), 1);
        store
            .settle_send_failed(
                "m-curve",
                first_failure + 190,
                crate::store::SendRetrySchedule::Backoff,
                None,
            )
            .unwrap()
            .unwrap();
        let (_, first, count, next) = retry_face(&store, "m-curve");
        assert_eq!(
            first,
            Some(first_failure as i64),
            "a retry never resets the window"
        );
        assert_eq!(count, 2);
        assert_eq!(
            next,
            Some((first_failure + 190 + 361) as i64),
            "the second beat is 190 ms · 1.9"
        );
    }

    /// Contract 1.143 (§4.139): the rate-limit arm schedules the official
    /// Retry-After default, not the curve — the exact one-minute beat from
    /// the settlement instant, one attempt spent, the window anchor stamped
    /// like any queue row. The eligibility gate is the shared one: a row
    /// past its attempt budget settles plain failed with the face retired
    /// even under the rate-limit family.
    #[test]
    fn rate_limit_settlement_schedules_the_retry_after_beat_not_the_curve() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let first_failure: u64 = 1_800_000_000_000;
        seed_retry_row(
            &store,
            &account.id,
            &conversation.id,
            "m-ratelimit",
            "req-ratelimit",
            "pending",
            None,
            0,
            None,
        );
        store
            .settle_send_failed(
                "m-ratelimit",
                first_failure,
                crate::store::SendRetrySchedule::RateLimit,
                None,
            )
            .unwrap()
            .unwrap();
        let (_, first, count, next) = retry_face(&store, "m-ratelimit");
        assert_eq!(
            (first, count, next),
            (
                Some(first_failure as i64),
                1,
                Some((first_failure + crate::store::RATE_LIMIT_RETRY_AFTER_MS) as i64)
            ),
            "the beat is the Retry-After default, never the 190 ms curve head"
        );

        // The shared eligibility gate holds on this arm too: a row that
        // spent its attempt budget settles plain failed with the face
        // retired — the rate-limit family is not a budget bypass.
        seed_retry_row(
            &store,
            &account.id,
            &conversation.id,
            "m-ratelimit-spent",
            "req-ratelimit-spent",
            "pending",
            None,
            MAX_RETRY_ATTEMPTS,
            None,
        );
        store
            .settle_send_failed(
                "m-ratelimit-spent",
                first_failure,
                crate::store::SendRetrySchedule::RateLimit,
                None,
            )
            .unwrap()
            .unwrap();
        let (_, first, count, next) = retry_face(&store, "m-ratelimit-spent");
        assert_eq!(
            (first, count, next),
            (None, MAX_RETRY_ATTEMPTS as i64, None),
            "the spent row stays terminal under the rate-limit arm"
        );
    }

    /// The claim is the atomic failed→pending flip: a second claim pass
    /// takes nothing (the claimed rows are pending), and a manual rearm
    /// that raced ahead of the claim steals the row — the queue never
    /// double-takes against the manual path.
    #[test]
    fn retry_claim_is_atomic_against_double_take() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let now: u64 = 1_800_000_000_000;
        for id in ["m-a", "m-b", "m-c"] {
            seed_retry_row(
                &store,
                &account.id,
                &conversation.id,
                id,
                &format!("req-{id}"),
                "failed",
                Some(now - 1_000),
                1,
                Some(now - 500),
            );
        }
        // The manual path wins the race for m-c before the claim runs.
        let (_, manual_won) = store.rearm_failed_message("m-c").unwrap().unwrap();
        assert!(manual_won);
        let claims = store.claim_due_retries(now, 10).unwrap();
        assert_eq!(claims.len(), 2, "the manually rearmed row is not claimed");
        let claimed = claims
            .iter()
            .map(|claim| claim.message_id.as_str())
            .collect::<Vec<_>>();
        assert!(claimed.contains(&"m-a") && claimed.contains(&"m-b"));
        // A second pass double-takes nothing.
        let second = store.claim_due_retries(now, 10).unwrap();
        assert!(second.is_empty(), "the flip is the claim");
        // The manual loser's guarded rearm reports the loss.
        let manual_after = store.rearm_failed_message("m-a").unwrap().unwrap();
        assert!(!manual_after.1, "a claimed row answers changed=false");
    }

    /// Queue state persists across a store reopen (the official
    /// replay-after-restart for the definitively-failed half: the schedule
    /// and the window anchor survive), while the §4.92 startup sweep leaves
    /// fresh pending rows manual-only — their schedule face is retired by
    /// the sweep, never armed (a pending row that outlived its process is
    /// an unknown outcome, and unknown outcomes are never retried
    /// automatically).
    #[test]
    fn retry_queue_survives_restart_while_swept_pendings_stay_manual() {
        let temp = TempDir::new().unwrap();
        {
            let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
            let account = store
                .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
                .unwrap();
            let conversation = store
                .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
                .unwrap();
            let now: u64 = 1_800_000_000_000;
            seed_retry_row(
                &store,
                &account.id,
                &conversation.id,
                "m-queued",
                "req-queued",
                "failed",
                Some(now - 60_000),
                4,
                Some(now + 60_000),
            );
            seed_retry_row(
                &store,
                &account.id,
                &conversation.id,
                "m-stuck-pending",
                "req-stuck",
                "pending",
                None,
                0,
                None,
            );
        }
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        // The swept row: manual-only, no schedule.
        let (status, first, count, next) = retry_face(&store, "m-stuck-pending");
        assert_eq!(
            (status.as_str(), first, count, next),
            ("failed", None, 0, None)
        );
        // The queued row: schedule and anchor intact; still due in the
        // future, so the pass claims nothing yet — then claims it once due.
        let (status, first, count, next) = retry_face(&store, "m-queued");
        assert_eq!(status, "failed");
        assert_eq!(count, 4);
        assert!(first.is_some() && next.is_some());
        let now = next.unwrap() as u64 + 1;
        let claims = store.claim_due_retries(now, 10).unwrap();
        assert_eq!(
            claims
                .iter()
                .map(|claim| claim.message_id.as_str())
                .collect::<Vec<_>>(),
            ["m-queued"],
            "the queue replays across the restart"
        );
    }

    /// Every queue bound is terminal, not a pause: the per-account in-queue
    /// ceiling refuses a 257th enrollment, the scan batch limit caps a pass,
    /// and the total attempt cap retires the face instead of scheduling a
    /// 129th attempt.
    #[test]
    fn retry_queue_bounds_are_enforced() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let other = store
            .upsert_account_from_signal("+15555550102", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let other_conversation = store
            .ensure_conversation(&other.id, "direct", "+15555550103", "Peer")
            .unwrap();
        let now: u64 = 1_800_000_000_000;
        // Per-account ceiling: 256 queued rows fill the account's queue.
        for index in 0..MAX_RETRY_QUEUED_PER_ACCOUNT {
            seed_retry_row(
                &store,
                &account.id,
                &conversation.id,
                &format!("m-full-{index}"),
                &format!("req-full-{index}"),
                "failed",
                Some(now - 1_000),
                1,
                Some(now + 60_000),
            );
        }
        seed_retry_row(
            &store,
            &account.id,
            &conversation.id,
            "m-over-cap",
            "req-over-cap",
            "pending",
            None,
            0,
            None,
        );
        store
            .settle_send_failed(
                "m-over-cap",
                now,
                crate::store::SendRetrySchedule::Backoff,
                None,
            )
            .unwrap()
            .unwrap();
        let (status, first, count, next) = retry_face(&store, "m-over-cap");
        assert_eq!(
            (status.as_str(), first, count, next),
            ("failed", None, 0, None),
            "the 257th enrollment is refused and the face retired"
        );
        // Another account's queue is unaffected by the first account's fill.
        seed_retry_row(
            &store,
            &other.id,
            &other_conversation.id,
            "m-other-account",
            "req-other-account",
            "pending",
            None,
            0,
            None,
        );
        store
            .settle_send_failed(
                "m-other-account",
                now,
                crate::store::SendRetrySchedule::Backoff,
                None,
            )
            .unwrap()
            .unwrap();
        let (_, first, count, next) = retry_face(&store, "m-other-account");
        assert_eq!(
            (first, count, next),
            (Some(now as i64), 1, Some((now + 190) as i64))
        );
        // Scan batch limit: the drain pass takes at most its limit.
        for index in 0..5 {
            seed_retry_row(
                &store,
                &other.id,
                &other_conversation.id,
                &format!("m-due-{index}"),
                &format!("req-due-{index}"),
                "failed",
                Some(now - 1_000),
                1,
                Some(now - 500),
            );
        }
        let claims = store.claim_due_retries(now, 2).unwrap();
        assert_eq!(claims.len(), 2, "the pass never exceeds its batch");
        let remaining = store.claim_due_retries(now, 100).unwrap();
        assert_eq!(remaining.len(), 3);
        // Total attempt cap: a row that already spent its budget settles
        // terminal — the schedule face retires, nothing is scheduled.
        seed_retry_row(
            &store,
            &other.id,
            &other_conversation.id,
            "m-spent",
            "req-spent",
            "pending",
            Some(now - 1_000),
            MAX_RETRY_ATTEMPTS,
            None,
        );
        store
            .settle_send_failed(
                "m-spent",
                now,
                crate::store::SendRetrySchedule::Backoff,
                None,
            )
            .unwrap()
            .unwrap();
        let (status, first, count, next) = retry_face(&store, "m-spent");
        assert_eq!(status, "failed");
        assert_eq!(
            (first, count, next),
            (Some((now - 1_000) as i64), MAX_RETRY_ATTEMPTS as i64, None),
            "the 129th attempt is refused, not deferred"
        );
    }

    /// Schema 23 (§4.123): a v22 database migrates in place — the three
    /// scheduling columns appear and the version stamp moves to 23.
    #[test]
    fn schema_v23_upgrade_adds_retry_queue_columns() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("connector.sqlite3");
        let conn = Connection::open(&path).unwrap();
        conn.execute_batch(
            "CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
             INSERT INTO meta(key, value) VALUES('schema_version', '22');
             CREATE TABLE accounts (
               id TEXT PRIMARY KEY,
               signal_account TEXT NOT NULL UNIQUE,
               masked_address TEXT NOT NULL,
               display_name TEXT,
               state TEXT NOT NULL,
               linked_at INTEGER,
               last_message_at INTEGER,
               unread_count INTEGER NOT NULL DEFAULT 0
             );
             CREATE TABLE messages (
               id TEXT PRIMARY KEY,
               account_id TEXT NOT NULL,
               conversation_id TEXT NOT NULL,
               direction TEXT NOT NULL,
               sender_id TEXT NOT NULL,
               sent_at INTEGER NOT NULL,
               received_at INTEGER,
               stored_at INTEGER,
               body TEXT,
               body_bytes INTEGER,
               body_truncated INTEGER NOT NULL DEFAULT 0,
               status TEXT NOT NULL,
               client_request_id TEXT,
               quote_message_id TEXT,
               quote_snapshot TEXT,
               attachments_json TEXT,
               attachment_locators TEXT,
               live_attachment_locators TEXT,
               rich_json TEXT,
               sticker_json TEXT,
               expire_seconds INTEGER,
               expire_start_at INTEGER,
               expire_at INTEGER,
               server_guid TEXT,
               server_timestamp INTEGER,
               edited_at INTEGER,
               sender_name TEXT,
               mentions_self INTEGER NOT NULL DEFAULT 0
             );",
        )
        .unwrap();
        drop(conn);

        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        assert!(table_has_column(&store.conn(), "messages", "first_send_attempted_at").unwrap());
        assert!(table_has_column(&store.conn(), "messages", "retry_attempt_count").unwrap());
        assert!(table_has_column(&store.conn(), "messages", "next_attempt_at").unwrap());
        let version: i64 = store
            .conn()
            .query_row(
                "SELECT CAST(value AS INTEGER) FROM meta WHERE key='schema_version'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(version, SCHEMA_VERSION);
    }

    /// Contract 1.142 (§4.138): the v23→v24 migration adds the additive
    /// nullable `accounts.aci` column. Nothing is backfilled — pre-1.142 rows
    /// legitimately hold none (the engine face had no key to read) — and the
    /// version stamp moves to 24.
    #[test]
    fn schema_v24_upgrade_adds_the_account_aci_column() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("connector.sqlite3");
        let conn = Connection::open(&path).unwrap();
        conn.execute_batch(
            "CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
             INSERT INTO meta(key, value) VALUES('schema_version', '23');
             CREATE TABLE accounts (
               id TEXT PRIMARY KEY,
               signal_account TEXT NOT NULL UNIQUE,
               masked_address TEXT NOT NULL,
               display_name TEXT,
               state TEXT NOT NULL,
               linked_at INTEGER,
               last_message_at INTEGER,
               unread_count INTEGER NOT NULL DEFAULT 0,
               proxy_group TEXT NOT NULL DEFAULT 'default'
             );",
        )
        .unwrap();
        drop(conn);

        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        assert!(table_has_column(&store.conn(), "accounts", "aci").unwrap());
        let version: i64 = store
            .conn()
            .query_row(
                "SELECT CAST(value AS INTEGER) FROM meta WHERE key='schema_version'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(version, SCHEMA_VERSION);
        // The migrated face reads as absence until an engine answer lands.
        store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(store.list_accounts().unwrap()[0].aci, None);
    }

    /// Contract 1.142 (§4.138): the canonical ACI shape. The dashed and bare
    /// 32-hex shapes normalize to dashed lowercase in either case; anything
    /// else — wrong length, misplaced dashes, non-hex, empty — is not an ACI
    /// and reads as absence, never a repaired guess.
    #[test]
    fn canonical_aci_normalizes_the_answered_shapes_and_refuses_the_rest() {
        // Dashed lowercase is already canonical.
        assert_eq!(
            canonical_aci("5a1cc2cd-b364-53d4-8d71-1ec62b8eb72b"),
            Some("5a1cc2cd-b364-53d4-8d71-1ec62b8eb72b".into())
        );
        // Dashed uppercase normalizes to lowercase.
        assert_eq!(
            canonical_aci("5A1CC2CD-B364-53D4-8D71-1EC62B8EB72B"),
            Some("5a1cc2cd-b364-53d4-8d71-1ec62b8eb72b".into())
        );
        // Bare 32-hex (either case) takes the dashed shape.
        assert_eq!(
            canonical_aci("5A1CC2CDB36453D48D711EC62B8EB72B"),
            Some("5a1cc2cd-b364-53d4-8d71-1ec62b8eb72b".into())
        );
        // Not an ACI: short, misplaced dashes, non-hex, empty.
        assert_eq!(canonical_aci("5a1cc2cd-b364-53d4-8d71-1ec62b8eb72"), None);
        assert_eq!(canonical_aci("5a1cc2cd-b36-453d4-8d7-11ec62b8eb72b"), None);
        assert_eq!(canonical_aci("5a1cc2cd_b364_53d4_8d71_1ec62b8eb72b"), None);
        assert_eq!(canonical_aci("zzzzzzzz-zzzz-zzzz-zzzz-zzzzzzzzzzzz"), None);
        assert_eq!(canonical_aci(""), None);
    }

    /// Contract 1.142 (§4.138): the writer takes only a fresh engine answer —
    /// `None` writes nothing, so an absent face never unreports a stored
    /// identity — and every read face (the single summary and both listings)
    /// carries the row's aci once set.
    #[test]
    fn set_account_aci_persists_the_answer_and_none_never_unreports() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(
            store.account_summary(&account.id).unwrap().unwrap().aci,
            None
        );

        let aci = canonical_aci("5A1CC2CDB36453D48D711EC62B8EB72B").unwrap();
        store.set_account_aci(&account.id, Some(&aci)).unwrap();
        let summary = store.account_summary(&account.id).unwrap().unwrap();
        assert_eq!(
            summary.aci.as_deref(),
            Some("5a1cc2cd-b364-53d4-8d71-1ec62b8eb72b")
        );
        assert_eq!(store.list_accounts().unwrap()[0].aci, summary.aci);
        assert_eq!(
            store
                .list_accounts_in_group(DEFAULT_PROXY_GROUP_ID)
                .unwrap()[0]
                .aci,
            summary.aci
        );

        // The absent face leaves the stored identity in place.
        store.set_account_aci(&account.id, None).unwrap();
        assert_eq!(
            store.account_summary(&account.id).unwrap().unwrap().aci,
            Some(aci)
        );

        // A fresh answer overwrites.
        let other = canonical_aci("18E2E00B2AC755ECA25DD5646A80C042").unwrap();
        store.set_account_aci(&account.id, Some(&other)).unwrap();
        assert_eq!(
            store.account_summary(&account.id).unwrap().unwrap().aci,
            Some("18e2e00b-2ac7-55ec-a25d-d5646a80c042".into())
        );
    }

    /// Contract 1.43 (§4.42): `isSelf` marks exactly the linked account's own
    /// direct chat — the number match — and never a sibling contact, a
    /// UUID-keyed row (the §4.24 boundary: the own ACI is not queryable), a
    /// group, or another account's conversation. The list and the single-row
    /// read derive the same answer.
    #[test]
    fn conversation_summary_is_self_marks_only_the_own_direct_chat() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let own = store
            .ensure_conversation(&account.id, "direct", "+15555550100", "Test User")
            .unwrap();
        let contact = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Alice")
            .unwrap();
        let uuid_peer = store
            .ensure_conversation(
                &account.id,
                "direct",
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "Aci Peer",
            )
            .unwrap();
        let group = store
            .ensure_conversation(&account.id, "group", "Z3JvdXAtaWQ=", "Group")
            .unwrap();

        let summary = |conversation_id: &str| {
            store
                .conversation_summary(&account.id, conversation_id)
                .unwrap()
                .unwrap()
        };
        assert!(summary(&own.id).is_self);
        assert!(!summary(&contact.id).is_self);
        assert!(!summary(&uuid_peer.id).is_self);
        assert!(!summary(&group.id).is_self);

        let listed = store.list_conversations(&account.id, 10, None).unwrap();
        let marked: Vec<_> = listed.items.iter().filter(|row| row.is_self).collect();
        assert_eq!(marked.len(), 1);
        assert_eq!(marked[0].id, own.id);
        assert_eq!(marked[0].kind, "direct");
        for row in &listed.items {
            assert_eq!(row.is_self, summary(&row.id).is_self);
        }

        // The same peer key means different things per owning account: under
        // the second account, +15555550199 is its own Note to Self chat, while
        // under the first account it is just a contact.
        let other = store
            .upsert_account_from_signal("+15555550199", Some(2), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let other_own = store
            .ensure_conversation(&other.id, "direct", "+15555550199", "Other Self")
            .unwrap();
        assert!(
            store
                .conversation_summary(&other.id, &other_own.id)
                .unwrap()
                .unwrap()
                .is_self
        );
        let contact_view = store
            .ensure_conversation(&account.id, "direct", "+15555550199", "Bob")
            .unwrap();
        assert!(
            !store
                .conversation_summary(&account.id, &contact_view.id)
                .unwrap()
                .unwrap()
                .is_self
        );
        let other_listed = store.list_conversations(&other.id, 10, None).unwrap();
        let other_marked: Vec<_> = other_listed
            .items
            .iter()
            .filter(|row| row.is_self)
            .collect();
        assert_eq!(other_marked.len(), 1);
        assert_eq!(other_marked[0].id, other_own.id);

        // Contract 1.170 (§4.170): once the account carries an ACI, the ACI
        // key marks the same way the number always did — and the own-number
        // key redirects to the canonical ACI row, so the two faces agree.
        let other_aci = canonical_aci("18E2E00B2AC755ECA25DD5646A80C042").unwrap();
        store.set_account_aci(&other.id, Some(&other_aci)).unwrap();
        let canonical = store
            .ensure_conversation(&other.id, "direct", "+15555550199", "Other Self")
            .unwrap();
        assert_eq!(canonical.peer_key, other_aci, "the number key redirects");
        assert!(
            store
                .conversation_summary(&other.id, &canonical.id)
                .unwrap()
                .unwrap()
                .is_self
        );
        let canonical_listed = store.list_conversations(&other.id, 10, None).unwrap();
        assert_eq!(
            canonical_listed
                .items
                .iter()
                .filter(|row| row.is_self)
                .count(),
            2,
            "shell and canonical both mark until the fold retires the shell"
        );
        // The store-level fold (§4.170) is what retires the shell: after it
        // the list marks exactly the canonical row.
        let folded = store.normalize_memo_identity(&other.id).unwrap().unwrap();
        assert_eq!(folded.id, canonical.id);
        let folded_listed = store.list_conversations(&other.id, 10, None).unwrap();
        let folded_marked: Vec<_> = folded_listed
            .items
            .iter()
            .filter(|row| row.is_self)
            .collect();
        assert_eq!(
            folded_marked.len(),
            1,
            "one self conversation after the fold"
        );
        assert_eq!(folded_marked[0].id, canonical.id);
        // A foreign UUID-shaped peer key still never marks (the §4.24
        // boundary lives on for peers that are not the account itself).
        let stranger = store
            .ensure_conversation(
                &other.id,
                "direct",
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "Stranger",
            )
            .unwrap();
        assert!(
            !store
                .conversation_summary(&other.id, &stranger.id)
                .unwrap()
                .unwrap()
                .is_self
        );
    }

    /// Seed one message row with explicit signal-identity fields (the fold's
    /// dedupe tuple: direction, sent_at, sender_id).
    fn seed_memo_message(
        store: &Store,
        account_id: &str,
        conversation_id: &str,
        id: &str,
        direction: &'static str,
        sender_id: &str,
        sent_at: u64,
    ) {
        let record = MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: id.into(),
            account_id: account_id.into(),
            conversation_id: conversation_id.into(),
            direction,
            sender_id: sender_id.into(),
            sender_name: None,
            mentions_self: false,
            sent_at,
            received_at: None,
            text: Some("memo body".into()),
            text_bytes: Some(9),
            text_truncated: false,
            text_retrievable: true,
            status: "sent",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        assert!(
            store
                .insert_message(&record, None, Some("memo body"), false)
                .unwrap(),
            "seeded rows never collide"
        );
    }

    /// Contract 1.170 (§4.170), the fold: the number-keyed shell's messages
    /// (deduplicated by signal identity), reactions, pin, draft and merged
    /// state land on the canonical ACI-keyed row, the shell row is deleted,
    /// and the ledger row records the fold with the rollback snapshot.
    #[test]
    fn memo_migration_folds_the_number_shell_into_the_canonical_aci_row() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let aci = canonical_aci("18E2E00B2AC755ECA25DD5646A80C042").unwrap();
        let shell = store
            .ensure_conversation(&account.id, "direct", "+15555550100", "8fc***e2")
            .unwrap();
        let canonical = store
            .ensure_conversation(&account.id, "direct", &aci, "Canonical")
            .unwrap();
        assert_ne!(shell.id, canonical.id, "two keys, two rows before the fold");

        // Shell-side material: two unique messages, one duplicate of a
        // canonical message (same direction+sent_at+sender_id), a reaction,
        // a pin and a draft. The canonical side holds its own copy of the
        // duplicate identity plus one unique message, a masked-canonical
        // title and a higher unread count.
        seed_memo_message(
            &store,
            &account.id,
            &shell.id,
            "m-shell-1",
            "outgoing",
            "self",
            1_000,
        );
        seed_memo_message(
            &store,
            &account.id,
            &shell.id,
            "m-shell-2",
            "incoming",
            "+15555550101",
            2_000,
        );
        seed_memo_message(
            &store,
            &account.id,
            &shell.id,
            "m-dup-shell",
            "incoming",
            "+15555550101",
            3_000,
        );
        seed_memo_message(
            &store,
            &account.id,
            &canonical.id,
            "m-dup-canonical",
            "incoming",
            "+15555550101",
            3_000,
        );
        seed_memo_message(
            &store,
            &account.id,
            &canonical.id,
            "m-canonical-1",
            "outgoing",
            "self",
            4_000,
        );
        store
            .upsert_reaction_event(&account.id, &shell.id, "👍", 2_000, "actor-1", false, None)
            .unwrap();
        store
            .upsert_reaction_event(
                &account.id,
                &canonical.id,
                "🎉",
                4_000,
                "actor-2",
                false,
                None,
            )
            .unwrap();
        store
            .append_conversation_pin(
                &account.id,
                &shell.id,
                "+15555550101",
                2_000,
                1_700_000_000_000,
                None,
            )
            .unwrap();
        store
            .save_conversation_draft(&account.id, &shell.id, 5_000)
            .unwrap();
        store
            .conn()
            .execute(
                "UPDATE conversations SET unread_count=7, muted=1, last_message_at=5000,
                        last_message_preview='shell newest' WHERE id=?1",
                params![shell.id],
            )
            .unwrap();

        store.set_account_aci(&account.id, Some(&aci)).unwrap();
        let summary = store.normalize_memo_identity(&account.id).unwrap();
        let summary = summary.expect("a shell must fold");

        // The shell is gone; the canonical row carries the folded state.
        assert_eq!(summary.id, canonical.id);
        assert!(summary.is_self, "the canonical row marks as self");
        assert!(
            store
                .conversation_by_peer(&account.id, "direct", "+15555550100")
                .unwrap()
                .is_none(),
            "the number-keyed shell row is deleted"
        );
        let folded = store
            .conversation_summary(&account.id, &canonical.id)
            .unwrap()
            .unwrap();
        assert_eq!(folded.unread_count, 7, "unread takes the MAX");
        assert!(folded.muted, "muted ORs");
        assert!(
            !title_should_upgrade(&folded.title, "8fc***e2"),
            "a real title never upgrades to a mask"
        );

        // Messages: the union of both rows, duplicates collapsed onto the
        // canonical copy, every survivor keyed to the canonical conversation.
        let count: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM messages WHERE conversation_id=?1",
                params![canonical.id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(count, 4, "five seeded rows minus the one duplicate");
        let shell_leftovers: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM messages WHERE conversation_id=?1",
                params![shell.id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(shell_leftovers, 0);
        let kept: String = store
            .conn()
            .query_row(
                "SELECT id FROM messages WHERE direction='incoming' AND sent_at=3000",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            kept, "m-dup-canonical",
            "the canonical copy wins the dedupe"
        );
        // Reactions: both survive, none left on the shell.
        assert_eq!(store.count_reaction_events(&account.id).unwrap(), 2);
        // Pin and draft moved with the conversation.
        let moved: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM conversation_pins WHERE conversation_id=?1",
                params![canonical.id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(moved, 1);
        let draft: Option<i64> = store
            .conn()
            .query_row(
                "SELECT draft_timestamp FROM conversation_drafts WHERE conversation_id=?1",
                params![canonical.id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(draft, Some(5_000));
        // The ledger row records the fold with the rollback snapshot.
        let (ledger_aci, ledger_source, rollback): (String, String, String) = store
            .conn()
            .query_row(
                "SELECT canonical_aci, source_peer_key, rollback_json FROM memo_migrations
                 WHERE account_id=?1",
                params![account.id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(ledger_aci, aci);
        assert_eq!(ledger_source, "+15555550100");
        let snapshot: Value = serde_json::from_str(&rollback).unwrap();
        assert_eq!(snapshot["id"], shell.id.as_str());
        assert_eq!(
            snapshot["droppedMessageIds"],
            json!(["m-dup-shell"]),
            "the deduplicated copy rides the ledger"
        );
    }

    /// Contract 1.170 (§4.170): the fold is idempotent and honestly a no-op
    /// on the faces that have nothing to fold — no ACI, no shell, and a
    /// folded account (the second run must not reannounce).
    #[test]
    fn memo_migration_is_idempotent_and_skips_accounts_without_shell_or_aci() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let no_aci = store
            .upsert_account_from_signal("+15555550101", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        store
            .ensure_conversation(&no_aci.id, "direct", "+15555550101", "Shell")
            .unwrap();
        assert!(
            store.normalize_memo_identity(&no_aci.id).unwrap().is_none(),
            "no ACI: nothing keys the canonical row"
        );

        let aci = canonical_aci("18E2E00B2AC755ECA25DD5646A80C042").unwrap();
        let shellless = store
            .upsert_account_from_signal("+15555550102", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        store.set_account_aci(&shellless.id, Some(&aci)).unwrap();
        assert!(
            store
                .normalize_memo_identity(&shellless.id)
                .unwrap()
                .is_none(),
            "no shell: nothing folds, and no canonical placeholder is created"
        );
        let listed = store.list_conversations(&shellless.id, 10, None).unwrap();
        assert!(
            listed.items.is_empty(),
            "the fold never materializes an empty self chat"
        );

        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let shell = store
            .ensure_conversation(&account.id, "direct", "+15555550100", "Self")
            .unwrap();
        seed_memo_message(
            &store,
            &account.id,
            &shell.id,
            "m-1",
            "outgoing",
            "self",
            1_000,
        );
        store.set_account_aci(&account.id, Some(&aci)).unwrap();
        store
            .normalize_memo_identity(&account.id)
            .unwrap()
            .expect("the first run folds");
        let (first_stamp, first_rollback): (i64, String) = store
            .conn()
            .query_row(
                "SELECT migrated_at, rollback_json FROM memo_migrations WHERE account_id=?1",
                params![account.id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert!(
            store
                .normalize_memo_identity(&account.id)
                .unwrap()
                .is_none(),
            "the second run finds no shell"
        );
        let (second_stamp, second_rollback): (i64, String) = store
            .conn()
            .query_row(
                "SELECT migrated_at, rollback_json FROM memo_migrations WHERE account_id=?1",
                params![account.id],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(
            (first_stamp, first_rollback),
            (second_stamp, second_rollback),
            "the ledger is untouched by a no-op run"
        );
    }

    /// Contract 1.259 (§4.243, batch Z1 · S14): the peer-side fold — the
    /// number-keyed shell collapses into the ACI-keyed row with the row
    /// count 2 → 1, the message union deduplicated with ids stable, unread
    /// conserved (not maxed), pins/drafts moved, and the A5 notice minted
    /// into the canonical conversation when the official three-arm gate
    /// holds (both sides had messages, the shell title useful). The notice
    /// itself never raises the badge (the official readStatus: Read).
    #[test]
    fn peer_identity_merge_folds_the_number_shell_into_the_aci_row() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let aci = canonical_aci("18E2E00B2AC755ECA25DD5646A80C042").unwrap();
        let shell = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer Name")
            .unwrap();
        let canonical = store
            .ensure_conversation(&account.id, "direct", &aci, "8fc***e2")
            .unwrap();
        assert_ne!(shell.id, canonical.id, "two keys, two rows before the fold");

        seed_memo_message(
            &store,
            &account.id,
            &shell.id,
            "m-shell-1",
            "incoming",
            "shell-sender",
            1_000,
        );
        seed_memo_message(
            &store,
            &account.id,
            &shell.id,
            "m-shell-2",
            "incoming",
            "shell-sender",
            2_000,
        );
        seed_memo_message(
            &store,
            &account.id,
            &canonical.id,
            "m-canonical-1",
            "outgoing",
            "self",
            3_000,
        );
        store
            .append_conversation_pin(
                &account.id,
                &shell.id,
                "shell-sender",
                1_000,
                1_700_000_000_000,
                None,
            )
            .unwrap();
        store
            .save_conversation_draft(&account.id, &shell.id, 6_000)
            .unwrap();
        store
            .conn()
            .execute(
                "UPDATE conversations SET unread_count=2, unread_mentions=1,
                        last_message_at=2000, last_message_preview='shell newest'
                  WHERE id=?1",
                params![shell.id],
            )
            .unwrap();
        store
            .conn()
            .execute(
                "UPDATE conversations SET unread_count=1 WHERE id=?1",
                params![canonical.id],
            )
            .unwrap();
        store
            .upsert_peer_identity(&account.id, &aci, "+15555550101")
            .unwrap();

        let outcome = store
            .merge_peer_identity(&account.id, &aci, "+15555550101")
            .unwrap()
            .expect("both rows present: the fold answers");

        // The shell row is gone; one row remains under the ACI key.
        assert_eq!(outcome.canonical_summary.id, canonical.id);
        assert_eq!(outcome.obsolete_conversation_id, shell.id);
        assert!(
            store
                .conversation_by_peer(&account.id, "direct", "+15555550101")
                .unwrap()
                .is_none(),
        );
        let folded = store
            .conversation_summary(&account.id, &canonical.id)
            .unwrap()
            .unwrap();
        // Unread conservation: the union's incoming rows (the watermark is
        // NULL here = everything incoming counts) — the shell's two incoming
        // rows conserve; the canonical lone row is outgoing and never counts.
        assert_eq!(folded.unread_count, 2, "the badge conserves, never maxes");
        // The A5 notice: minted, unread-silent, carrying the two-key face.
        let notice = outcome
            .merge_notice
            .expect("the gate holds: both had messages and the shell title is useful");
        assert_eq!(notice.direction, "system");
        assert_eq!(notice.status, "system");
        assert_eq!(notice.conversation_id, canonical.id);
        let rich = notice.rich.expect("the A5 face rides rich");
        let merge = rich.conversation_merge.expect("the conversationMerge face");
        assert_eq!(
            merge.obsolete_conversation_title.as_deref(),
            Some("Peer Name")
        );
        assert_eq!(
            merge.obsolete_conversation_number.as_deref(),
            Some("+15555550101")
        );
        let stored: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM messages WHERE id=?1 AND conversation_id=?2",
                params![notice.id, canonical.id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(stored, 1, "the notice is persisted under the canonical row");
        assert_eq!(
            folded.unread_count, 2,
            "the notice never raises the badge (readStatus: Read)"
        );
        // Pins and drafts moved with the fold.
        let moved: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM conversation_pins WHERE conversation_id=?1",
                params![canonical.id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(moved, 1);
        let draft: Option<i64> = store
            .conn()
            .query_row(
                "SELECT draft_timestamp FROM conversation_drafts WHERE conversation_id=?1",
                params![canonical.id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(draft, Some(6_000));
        // Messages: all three, none left shell-side.
        let count: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM messages WHERE conversation_id=?1",
                params![canonical.id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(count, 4, "three seeded rows plus the minted notice");
        // The peer ledger records the fold.
        let rollback: String = store
            .conn()
            .query_row(
                "SELECT rollback_json FROM conversation_identity_merges
                 WHERE account_id=?1 AND obsolete_peer_key='+15555550101'",
                params![account.id],
                |row| row.get(0),
            )
            .unwrap();
        let snapshot: Value = serde_json::from_str(&rollback).unwrap();
        assert_eq!(snapshot["id"], shell.id.as_str());
        assert_eq!(snapshot["noticeMinted"], json!(true));
    }

    /// Contract 1.259 (§4.243): the unread counters recompute from the
    /// surviving row's read watermark over the moved union — the store's own
    /// invariant — so rows the shell already read (its watermark above them)
    /// never inflate the surviving badge, and the mention badge recomputes
    /// on the same clock.
    #[test]
    fn peer_identity_merge_recomputes_unread_from_the_surviving_watermark() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let aci = canonical_aci("18E2E00B2AC755ECA25DD5646A80C042").unwrap();
        let shell = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let canonical = store
            .ensure_conversation(&account.id, "direct", &aci, "Peer")
            .unwrap();
        // Shell rows: one read under its watermark (sent_at below), one
        // unread above it; the canonical row's watermark sits above its own
        // incoming row (read there).
        seed_memo_message(
            &store,
            &account.id,
            &shell.id,
            "m-shell-read",
            "incoming",
            "peer",
            1_000,
        );
        seed_memo_message(
            &store,
            &account.id,
            &shell.id,
            "m-shell-unread",
            "incoming",
            "peer",
            5_000,
        );
        seed_memo_message(
            &store,
            &account.id,
            &canonical.id,
            "m-canonical-read",
            "incoming",
            "peer",
            2_000,
        );
        store
            .conn()
            .execute(
                "UPDATE conversations SET read_watermark_ms=1000, unread_count=1,
                        unread_mentions=1 WHERE id=?1",
                params![shell.id],
            )
            .unwrap();
        store
            .conn()
            .execute(
                "UPDATE conversations SET read_watermark_ms=2000 WHERE id=?1",
                params![canonical.id],
            )
            .unwrap();
        store
            .conn()
            .execute(
                "UPDATE messages SET mentions_self=1 WHERE id='m-shell-unread'",
                [],
            )
            .unwrap();
        store
            .upsert_peer_identity(&account.id, &aci, "+15555550101")
            .unwrap();

        let outcome = store
            .merge_peer_identity(&account.id, &aci, "+15555550101")
            .unwrap()
            .expect("the fold answers");
        let folded = outcome.canonical_summary;
        // Conserved by the watermark union: the shell's read row stays read
        // (its watermark carried the read), the unread row and the already-
        // unread canonical window count — never the raw column sum 1+0, and
        // never the MAX 1.
        assert_eq!(folded.unread_count, 1);
        assert_eq!(folded.unread_mentions, 1, "the mention badge recomputes");
    }

    /// Contract 1.259 (§4.243): the guard arms — one-sided rows, the self
    /// number, the degenerate binding, and a masked shell title (the fold
    /// runs, the notice stays silent — the official titleIsUseful gate); and
    /// the replay after a fold is a no-op that answers None.
    #[test]
    fn peer_identity_merge_guard_arms_stay_silent_or_noop() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let aci = canonical_aci("18E2E00B2AC755ECA25DD5646A80C042").unwrap();

        // Number-only peer: no canonical row, nothing folds.
        store
            .ensure_conversation(&account.id, "direct", "+15555550103", "Lone")
            .unwrap();
        assert!(
            store
                .merge_peer_identity(&account.id, &aci, "+15555550103")
                .unwrap()
                .is_none(),
        );
        assert!(
            store
                .conversation_by_peer(&account.id, "direct", "+15555550103")
                .unwrap()
                .is_some(),
            "the one-sided row survives a no-op probe"
        );

        // ACI-only peer: no shell, nothing folds.
        store
            .ensure_conversation(&account.id, "direct", &aci, "Aci Only")
            .unwrap();
        assert!(
            store
                .merge_peer_identity(&account.id, &aci, "+15555550104")
                .unwrap()
                .is_none(),
        );

        // Degenerate binding: the redirect face answers None.
        assert!(
            store
                .merge_peer_identity(&account.id, &aci, &aci)
                .unwrap()
                .is_none(),
        );

        // The account's own number belongs to the memo family — the peer
        // fold never touches it (§4.170 owns the shell). The ensure door
        // itself redirects the own number onto the ACI key while the ACI is
        // set (the §4.170 redirect), so the honest assertions here are: the
        // peer probe answers None on the own number, and the canonical row
        // is untouched.
        store.set_account_aci(&account.id, Some(&aci)).unwrap();
        store
            .ensure_conversation(&account.id, "direct", "+15555550100", "Self")
            .unwrap();
        assert!(
            store
                .merge_peer_identity(&account.id, &aci, "+15555550100")
                .unwrap()
                .is_none(),
        );
        assert!(
            store
                .conversation_by_peer(&account.id, "direct", &aci)
                .unwrap()
                .is_some(),
            "the canonical row survives the own-number no-op probe"
        );
        store.set_account_aci(&account.id, None).unwrap();

        // Masked shell title: the fold runs, the notice stays silent.
        let masked = store
            .ensure_conversation(&account.id, "direct", "+15555550105", "+86***05")
            .unwrap();
        let peer_aci = canonical_aci("29D3E11C3BD866FDB36EE8271B90D153").unwrap();
        store
            .ensure_conversation(&account.id, "direct", &peer_aci, "Masked Peer")
            .unwrap();
        seed_memo_message(
            &store,
            &account.id,
            &masked.id,
            "m-masked",
            "incoming",
            "peer",
            1_000,
        );
        store
            .upsert_peer_identity(&account.id, &peer_aci, "+15555550105")
            .unwrap();
        let outcome = store
            .merge_peer_identity(&account.id, &peer_aci, "+15555550105")
            .unwrap()
            .expect("the fold answers");
        assert!(
            outcome.merge_notice.is_none(),
            "a masked shell title never mints the notice (titleIsUseful gate)"
        );
        assert!(
            store
                .conversation_by_peer(&account.id, "direct", "+15555550105")
                .unwrap()
                .is_none(),
            "the fold itself still ran"
        );

        // Replay: the shell is gone, the probe answers None.
        assert!(
            store
                .merge_peer_identity(&account.id, &peer_aci, "+15555550105")
                .unwrap()
                .is_none(),
        );
    }

    /// Contract 1.259 (§4.243): the expire timer keeps the more restrictive
    /// arm (official :1349-1356 — the smaller non-null timer wins; a
    /// timer-less canonical row adopts the shell's; the shell's absence
    /// keeps the canonical's).
    #[test]
    fn peer_identity_merge_carries_the_more_restrictive_expire_timer() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();

        let build_pair = |store: &Store,
                          number: &str,
                          aci_word: &str,
                          shell_timer: Option<i64>,
                          canonical_timer: Option<i64>,
                          seed_word: &str| {
            let aci = canonical_aci(aci_word).unwrap();
            let shell = store
                .ensure_conversation(&account.id, "direct", number, "Peer")
                .unwrap();
            let canonical = store
                .ensure_conversation(&account.id, "direct", &aci, "Peer")
                .unwrap();
            for (id, timer) in [(&shell.id, shell_timer), (&canonical.id, canonical_timer)] {
                store
                    .conn()
                    .execute(
                        "UPDATE conversations SET expire_timer_seconds=?2 WHERE id=?1",
                        params![id, timer],
                    )
                    .unwrap();
            }
            seed_memo_message(
                store,
                &account.id,
                &shell.id,
                &format!("m-{seed_word}"),
                "outgoing",
                "self",
                1_000,
            );
            seed_memo_message(
                store,
                &account.id,
                &canonical.id,
                &format!("m2-{seed_word}"),
                "outgoing",
                "self",
                2_000,
            );
            store
                .upsert_peer_identity(&account.id, &aci, number)
                .unwrap();
            let outcome = store
                .merge_peer_identity(&account.id, &aci, number)
                .unwrap()
                .expect("the fold answers");
            outcome.canonical_summary.expire_timer_seconds
        };

        // Shell 300s vs canonical 86400s: the more restrictive 300 wins.
        let merged = build_pair(
            &store,
            "+15555550111",
            "39E0E22D4CE9770EC1A2B3D4E5F60718",
            Some(300),
            Some(86_400),
            "t1",
        );
        assert_eq!(merged, Some(300));
        // Canonical without a timer adopts the shell's.
        let merged = build_pair(
            &store,
            "+15555550112",
            "4A1F33E5DF088A1F4C2B901E6C31E264",
            Some(600),
            None,
            "t2",
        );
        assert_eq!(merged, Some(600));
        // Shell without a timer keeps the canonical's.
        let merged = build_pair(
            &store,
            "+15555550113",
            "5B2044F6E0199B2A5D3CA12F7D42F375",
            None,
            Some(1_200),
            "t3",
        );
        assert_eq!(merged, Some(1_200));
    }

    /// Contract 1.259 (§4.243): both number spellings (§4.144 — `+`-prefixed
    /// against bare digits) are probed for the shell, exact form first; a
    /// bare-keyed shell folds under a `+`-prefixed binding, and the wire
    /// number in the notice normalizes to the `+` word form.
    #[test]
    fn peer_identity_merge_probes_both_number_spellings() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let aci = canonical_aci("6C3157A813ABAD3B6E4DB23F8E53F486").unwrap();
        // The shell keyed in bare digits (the history-import/sync spelling).
        let shell = store
            .ensure_conversation(&account.id, "direct", "15555550116", "Bare Peer")
            .unwrap();
        let canonical = store
            .ensure_conversation(&account.id, "direct", &aci, "Canonical Peer")
            .unwrap();
        seed_memo_message(
            &store,
            &account.id,
            &shell.id,
            "m-bare",
            "incoming",
            "peer",
            1_000,
        );
        seed_memo_message(
            &store,
            &account.id,
            &canonical.id,
            "m-canon",
            "outgoing",
            "self",
            1_000,
        );
        store
            .upsert_peer_identity(&account.id, &aci, "+15555550116")
            .unwrap();

        let outcome = store
            .merge_peer_identity(&account.id, &aci, "+15555550116")
            .unwrap()
            .expect("the alternate-spelling shell folds");
        assert_eq!(outcome.canonical_summary.id, canonical.id);
        let notice = outcome
            .merge_notice
            .expect("both sides had messages and a useful title");
        let merge = notice.rich.unwrap().conversation_merge.unwrap();
        assert_eq!(
            merge.obsolete_conversation_number.as_deref(),
            Some("+15555550116"),
            "the wire number normalizes to the + word form"
        );
        assert!(
            store
                .conversation_by_peer(&account.id, "direct", "15555550116")
                .unwrap()
                .is_none(),
        );
    }

    /// Contract 1.170 (§4.170): once the account carries an ACI, the
    /// own-number direct key redirects to the canonical ACI key at
    /// `ensure_conversation` — the shell is never created through the
    /// redirected door — the answer is stable across both spellings, the
    /// degenerate `aci == number` answer redirects nothing, and the
    /// canonical row reads `isSelf` on both the single-row and the list
    /// face.
    #[test]
    fn canonical_aci_key_redirects_the_own_number_and_marks_is_self() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let aci = canonical_aci("18E2E00B2AC755ECA25DD5646A80C042").unwrap();

        // Before the ACI lands, the own-number key materializes (the §4.42
        // shape) and marks self by the number.
        let shell = store
            .ensure_conversation(&account.id, "direct", "+15555550100", "Note to Self")
            .unwrap();
        assert_eq!(shell.peer_key, "+15555550100");
        assert!(
            store
                .conversation_summary(&account.id, &shell.id)
                .unwrap()
                .unwrap()
                .is_self
        );

        store.set_account_aci(&account.id, Some(&aci)).unwrap();

        // The own-number call now answers the canonical ACI-keyed row; a
        // second shell is never created behind the redirect.
        let canonical = store
            .ensure_conversation(&account.id, "direct", "+15555550100", "Note to Self")
            .unwrap();
        assert_eq!(canonical.peer_key, aci, "the number key redirects");
        assert_ne!(canonical.id, shell.id);
        let canonical_by_key = store
            .ensure_conversation(&account.id, "direct", &aci, "Note to Self")
            .unwrap();
        assert_eq!(canonical_by_key.id, canonical.id, "stable across spellings");

        // The canonical row reads `isSelf` on both faces. The pre-existing
        // number-keyed shell still marks too — the fold, not the redirect,
        // is what retires it.
        assert!(
            store
                .conversation_summary(&account.id, &canonical.id)
                .unwrap()
                .unwrap()
                .is_self
        );
        let listed = store.list_conversations(&account.id, 10, None).unwrap();
        let marked: Vec<_> = listed.items.iter().filter(|row| row.is_self).collect();
        assert_eq!(
            marked.len(),
            2,
            "shell and canonical both mark until the fold"
        );
        assert!(marked.iter().any(|row| row.id == canonical.id));

        // The degenerate answer — an ACI equal to the number — redirects
        // nothing: the number key keeps answering the number-keyed row.
        store
            .set_account_aci(&account.id, Some("+15555550100"))
            .unwrap();
        let degenerate = store
            .ensure_conversation(&account.id, "direct", "+15555550100", "Note to Self")
            .unwrap();
        assert_eq!(degenerate.peer_key, "+15555550100");
        assert_eq!(degenerate.id, shell.id, "the shell answers as itself");
    }

    /// Contract 1.44 (§4.43): `contacts.list` marks exactly the linked
    /// account's own entry — the `kind='contact'` row whose peer key is the
    /// account's number — and never a sibling contact, a UUID-keyed row (the
    /// §4.24 boundary), a group, or another account's entry. The marker is a
    /// read-time projection: the cache row stores nothing, a resync that
    /// rewrites the row in place neither computes nor erases it, and the
    /// cursor path marks its page rows like the first page does.
    #[test]
    fn contact_list_is_self_marks_only_the_own_contact_entry() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        store
            .upsert_contact(
                &account.id,
                "contact",
                "+15555550100",
                "Test User",
                None,
                10,
            )
            .unwrap();
        store
            .upsert_contact(&account.id, "contact", "+15555550101", "Alice", None, 10)
            .unwrap();
        store
            .upsert_contact(
                &account.id,
                "contact",
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "Aci Peer",
                None,
                10,
            )
            .unwrap();
        store
            .upsert_contact(&account.id, "group", "Z3JvdXAtaWQ=", "Group", None, 10)
            .unwrap();

        let listed = store.list_contacts(&account.id, None, 10, None).unwrap();
        let marked: Vec<_> = listed.items.iter().filter(|row| row.is_self).collect();
        assert_eq!(marked.len(), 1);
        assert_eq!(marked[0].kind, "contact");
        assert_eq!(marked[0].peer_key, "+15555550100");
        // Title material is the account's own profile name (§4.42); the
        // desktop localizes the Note-to-Self presentation from the marker.
        assert_eq!(marked[0].title, "Test User");

        // A resync rewrites the row in place (upsert, same title) and the
        // marker is unchanged — nothing about it is stored.
        store
            .upsert_contact(&account.id, "contact", "+15555550101", "Alice A.", None, 11)
            .unwrap();
        let relisted = store.list_contacts(&account.id, None, 10, None).unwrap();
        let still_marked: Vec<_> = relisted.items.iter().filter(|row| row.is_self).collect();
        assert_eq!(still_marked.len(), 1);
        assert_eq!(still_marked[0].peer_key, "+15555550100");
        assert_eq!(relisted.items.len(), listed.items.len());

        // Cursor pagination derives the same marker on the second page: the
        // account lookup rides whichever page the guard is held for.
        let first = store.list_contacts(&account.id, None, 2, None).unwrap();
        assert_eq!(first.items.len(), 2);
        let cursor = first.next_cursor.clone().unwrap();
        let second = store
            .list_contacts(&account.id, None, 10, Some(&cursor))
            .unwrap();
        for row in second.items.iter().chain(first.items.iter()) {
            assert_eq!(row.is_self, row.peer_key == "+15555550100");
        }

        // The same peer key means different things per owning account: under
        // the second account, +15555550199 is its own entry, while under the
        // first account it is just another contact.
        let other = store
            .upsert_account_from_signal("+15555550199", Some(2), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        store
            .upsert_contact(&other.id, "contact", "+15555550199", "Other Self", None, 10)
            .unwrap();
        let other_listed = store.list_contacts(&other.id, None, 10, None).unwrap();
        let other_marked: Vec<_> = other_listed
            .items
            .iter()
            .filter(|row| row.is_self)
            .collect();
        assert_eq!(other_marked.len(), 1);
        assert_eq!(other_marked[0].peer_key, "+15555550199");

        store
            .upsert_contact(&account.id, "contact", "+15555550199", "Bob", None, 10)
            .unwrap();
        let account_view = store.list_contacts(&account.id, None, 10, None).unwrap();
        assert_eq!(
            account_view
                .items
                .iter()
                .filter(|row| row.is_self)
                .map(|row| row.peer_key.as_str())
                .collect::<Vec<_>>(),
            vec!["+15555550100"]
        );
    }

    /// Contract 1.138 (§4.130): the draft stamp round-trips through both
    /// summary projections — save replaces, clear is idempotent, an unknown
    /// conversation is addressed by nobody — and the absence collapses to
    /// the absent wire key everywhere.
    #[test]
    fn conversation_draft_stamps_roundtrip_through_summaries() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();

        // No draft: absent on the single-row and the list face alike.
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.draft_timestamp, None);
        let page = store.list_conversations(&account.id, 10, None).unwrap();
        assert!(page.items.iter().all(|item| item.draft_timestamp.is_none()));

        // Save: the stamp shows on both summaries; re-save replaces.
        assert!(
            store
                .save_conversation_draft(&account.id, &direct.id, 1_700_000_000_000)
                .unwrap()
        );
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.draft_timestamp, Some(1_700_000_000_000));
        let page = store.list_conversations(&account.id, 10, None).unwrap();
        let listed = page.items.iter().find(|item| item.id == direct.id).unwrap();
        assert_eq!(listed.draft_timestamp, Some(1_700_000_000_000));
        assert!(
            store
                .save_conversation_draft(&account.id, &direct.id, 1_700_000_000_500)
                .unwrap()
        );
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.draft_timestamp, Some(1_700_000_000_500));

        // Clear: absent again, and the clear is idempotent.
        assert!(
            store
                .clear_conversation_draft(&account.id, &direct.id)
                .unwrap()
        );
        assert!(
            store
                .clear_conversation_draft(&account.id, &direct.id)
                .unwrap()
        );
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.draft_timestamp, None);

        // An unknown conversation is addressed by nobody (the caller answers
        // CONVERSATION_NOT_FOUND from the false).
        assert!(
            !store
                .save_conversation_draft(&account.id, "no-such-conversation", 1)
                .unwrap()
        );
        assert!(
            !store
                .clear_conversation_draft(&account.id, "no-such-conversation")
                .unwrap()
        );
    }

    /// Contract 1.138 (§4.129, widened by 1.146 §4.144): the summary
    /// identifiers derive from the peer key's shape — a group row keys
    /// groupId off the raw master key, a +prefixed direct row answers e164
    /// (and, since 1.146, serviceId when the ingest-written peer_identities
    /// row resolves — in either spelling), a UUID-shaped direct row answers
    /// serviceId, a number-shaped direct row maps through the most recent
    /// peer_identities row (either spelling), and a key nothing resolves
    /// answers all-absent. pni is never present.
    #[test]
    fn conversation_summary_projects_identifiers_from_the_peer_key() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let group = store
            .ensure_conversation(&account.id, "group", "AbCdEf0123456789=", "group")
            .unwrap();
        let plus = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let plus_mapped = store
            .ensure_conversation(&account.id, "direct", "+15555550104", "contact")
            .unwrap();
        let plus_exact_map = store
            .ensure_conversation(&account.id, "direct", "+15555550105", "contact")
            .unwrap();
        let uuid = store
            .ensure_conversation(
                &account.id,
                "direct",
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "contact",
            )
            .unwrap();
        let number = store
            .ensure_conversation(&account.id, "direct", "15555550102", "contact")
            .unwrap();
        let number_plus_map = store
            .ensure_conversation(&account.id, "direct", "15555550106", "contact")
            .unwrap();
        let number_orphan = store
            .ensure_conversation(&account.id, "direct", "15555550103", "contact")
            .unwrap();
        // The ingest-written mappings a real receive chain leaves behind —
        // the bare-digit spelling a history/sync key spells (1.146: the
        // same mapping the +prefixed contact rows resolve through) beside
        // the +prefixed spelling the receive chain's contacts hit resolves
        // to, both probe orders pinned.
        store
            .upsert_peer_identity(
                &account.id,
                "11111111-2222-4333-8444-555555555555",
                "15555550102",
            )
            .unwrap();
        store
            .upsert_peer_identity(
                &account.id,
                "22222222-2222-4333-8444-555555555556",
                "15555550104",
            )
            .unwrap();
        store
            .upsert_peer_identity(
                &account.id,
                "33333333-2222-4333-8444-555555555557",
                "+15555550105",
            )
            .unwrap();
        store
            .upsert_peer_identity(
                &account.id,
                "44444444-2222-4333-8444-555555555558",
                "+15555550106",
            )
            .unwrap();

        let ids = |conversation_id: &str| {
            let summary = store
                .conversation_summary(&account.id, conversation_id)
                .unwrap()
                .unwrap();
            (
                summary.service_id,
                summary.e164,
                summary.group_id,
                summary.pni,
            )
        };
        assert_eq!(
            ids(&group.id),
            (None, None, Some("AbCdEf0123456789=".into()), None)
        );
        // The 1.146 miss arm: a +keyed row no identity resolves keeps the
        // 1.138 answer verbatim — e164 present, serviceId absent.
        assert_eq!(
            ids(&plus.id),
            (None, Some("+15555550101".into()), None, None)
        );
        // The 1.146 hit arms: a +keyed row the ingest mapped carries both —
        // e164 verbatim beside the mapped ACI, in the bare-spelled mapping…
        assert_eq!(
            ids(&plus_mapped.id),
            (
                Some("22222222-2222-4333-8444-555555555556".into()),
                Some("+15555550104".into()),
                None,
                None
            )
        );
        // …and in the +spelled mapping (the exact probe).
        assert_eq!(
            ids(&plus_exact_map.id),
            (
                Some("33333333-2222-4333-8444-555555555557".into()),
                Some("+15555550105".into()),
                None,
                None
            )
        );
        assert_eq!(
            ids(&uuid.id),
            (
                Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                None,
                None,
                None
            )
        );
        assert_eq!(
            ids(&number.id),
            (
                Some("11111111-2222-4333-8444-555555555555".into()),
                None,
                None,
                None
            )
        );
        // The number arm's dual form: a bare-keyed row resolves through a
        // +spelled mapping too.
        assert_eq!(
            ids(&number_plus_map.id),
            (
                Some("44444444-2222-4333-8444-555555555558".into()),
                None,
                None,
                None
            )
        );
        assert_eq!(ids(&number_orphan.id), (None, None, None, None));
    }

    /// Contract 1.146 (§4.144): `contacts.list` direct rows additively
    /// carry the derived serviceId through the same §4.129 family — a
    /// UUID-shaped peer key verbatim, a phone-keyed row (either spelling)
    /// through the most recent ingest-written mapping, an unresolved key
    /// and every group row absent. Absent-key wire: pre-1.146 hosts read
    /// byte-identical rows.
    #[test]
    fn contact_list_rows_carry_the_derived_service_id() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        store
            .upsert_contact(&account.id, "contact", "15555550101", "Bare Key", None, 10)
            .unwrap();
        store
            .upsert_contact(&account.id, "contact", "+15555550102", "Plus Key", None, 10)
            .unwrap();
        store
            .upsert_contact(
                &account.id,
                "contact",
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "Aci Key",
                None,
                10,
            )
            .unwrap();
        store
            .upsert_contact(&account.id, "group", "Z3JvdXAtaWQ=", "Group", None, 10)
            .unwrap();
        // The ingest-written mapping, +spelled against a bare-keyed row —
        // the dual-form probe the derivation runs.
        store
            .upsert_peer_identity(
                &account.id,
                "11111111-2222-4333-8444-555555555555",
                "+15555550101",
            )
            .unwrap();

        let listed = store.list_contacts(&account.id, None, 10, None).unwrap();
        let service_id_of = |peer_key: &str| {
            listed
                .items
                .iter()
                .find(|row| row.peer_key == peer_key)
                .unwrap()
                .service_id
                .clone()
        };
        assert_eq!(
            service_id_of("15555550101").as_deref(),
            Some("11111111-2222-4333-8444-555555555555")
        );
        assert_eq!(service_id_of("+15555550102"), None);
        assert_eq!(
            service_id_of("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10").as_deref(),
            Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10")
        );
        assert_eq!(service_id_of("Z3JvdXAtaWQ="), None);
    }

    /// Contract 1.138 (§4.131): the blocked stamp merges read-modify-write —
    /// a §4.47 write-back or BLOCK verb stamps survive the throttled enrich's
    /// trio re-stamp when the incoming trio does not name `blocked`, an
    /// engine answer that does name it wins, and a group row is nobody's
    /// trio stamp (the §4.45 pull stays the group authority).
    /// 契约 1.268（§4.252 · 批 Z12 · S16）：戳内 hidden 位读取三态——
    /// true/false 显式、戳缺席/无 hidden 键 = None（未知不折 false）。
    #[test]
    fn conversation_hidden_bit_reads_the_stamp_tri_state() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        // 无戳 = None（未知）。
        assert_eq!(
            store
                .conversation_hidden_bit(&account.id, "+15555550101")
                .unwrap(),
            None
        );
        // 显式 hidden 位逐字读出。
        store
            .set_conversation_mrr_factors_for_peer(
                &account.id,
                "+15555550101",
                r#"{"hidden":true,"profileSharing":false}"#,
            )
            .unwrap();
        assert_eq!(
            store
                .conversation_hidden_bit(&account.id, "+15555550101")
                .unwrap(),
            Some(true)
        );
        store
            .set_conversation_mrr_factors_for_peer(
                &account.id,
                "+15555550101",
                r#"{"hidden":false}"#,
            )
            .unwrap();
        assert_eq!(
            store
                .conversation_hidden_bit(&account.id, "+15555550101")
                .unwrap(),
            Some(false)
        );
        // 未知群行/号码不存在的行 = None（绝不冒充 false）。
        assert_eq!(
            store
                .conversation_hidden_bit(&account.id, "+15555559999")
                .unwrap(),
            None
        );
    }

    #[test]
    fn blocked_stamp_survives_the_enrich_and_yields_to_engine_truth() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let group = store
            .ensure_conversation(&account.id, "group", "AbCdEf0123456789=", "group")
            .unwrap();

        // No stamp: the summary's blocked bit reads false.
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(!summary.blocked);

        // The stamp lands, and the enrich's probed-absent {} re-stamp keeps
        // it (alongside the accept pair in the same merge).
        assert!(
            store
                .set_conversation_blocked_factor(&account.id, &direct.id, true)
                .unwrap()
        );
        assert!(
            store
                .set_conversation_accept_response_factor(&account.id, &direct.id, true, 1)
                .unwrap()
        );
        assert!(
            store
                .set_conversation_mrr_factors_for_peer(&account.id, "+15555550101", "{}")
                .unwrap()
        );
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(summary.blocked);
        assert!(summary.message_request_accepted);

        // Engine truth wins: an enrich answer naming isBlocked replaces the
        // stamp.
        assert!(
            store
                .set_conversation_mrr_factors_for_peer(
                    &account.id,
                    "+15555550101",
                    r#"{"blocked":false}"#
                )
                .unwrap()
        );
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(!summary.blocked);

        // A group row is nobody's trio stamp.
        assert!(
            !store
                .set_conversation_blocked_factor(&account.id, &group.id, true)
                .unwrap()
        );
    }

    /// Contract 1.60 (§4.54): the terminated flag rides the summary and the
    /// contacts-row projections from the §4.50 appendix capture — a group
    /// whose cache row stores the flag answers true on the list, the
    /// single-summary (conversation.changed) face, and the contacts row;
    /// a non-terminated group, a direct conversation, and a group with no
    /// cache row (pre-1.53 sync) all answer false, and false collapses to the
    /// absent wire key (pre-1.60 hosts read byte-identical rows).
    #[test]
    fn terminated_projection_marks_only_sync_captured_groups() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        // Conversation skeletons through the normal ensure path (the same
        // stable_hash_id([account, kind, peer]) key the sync materializes).
        let ended = store
            .ensure_conversation(&account.id, "group", "ZW5kZWQ=", "Ended Group")
            .unwrap();
        let alive = store
            .ensure_conversation(&account.id, "group", "YWxpdmU=", "Alive Group")
            .unwrap();
        let direct = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Alice")
            .unwrap();

        // The §4.50 appendix capture discipline verbatim: terminated stored
        // only when true, the marker JSON mirrors group_extra_json's shape.
        store
            .upsert_contact(
                &account.id,
                "group",
                "ZW5kZWQ=",
                "Ended Group",
                Some(r#"{"memberCount":3,"isTerminated":true}"#),
                20,
            )
            .unwrap();
        store
            .upsert_contact(
                &account.id,
                "group",
                "YWxpdmU=",
                "Alive Group",
                Some(r#"{"memberCount":4}"#),
                20,
            )
            .unwrap();
        store
            .upsert_contact(&account.id, "contact", "+15555550101", "Alice", None, 20)
            .unwrap();

        // List face: exactly the flagged group marked, direct never.
        let listed = store.list_conversations(&account.id, 10, None).unwrap();
        let ended_row = listed.items.iter().find(|row| row.id == ended.id).unwrap();
        let alive_row = listed.items.iter().find(|row| row.id == alive.id).unwrap();
        let direct_row = listed.items.iter().find(|row| row.id == direct.id).unwrap();
        assert!(ended_row.is_terminated);
        assert!(!alive_row.is_terminated);
        assert!(!direct_row.is_terminated);

        // Single-summary face (the conversation.changed payload).
        assert!(
            store
                .conversation_summary(&account.id, &ended.id)
                .unwrap()
                .unwrap()
                .is_terminated
        );
        assert!(
            !store
                .conversation_summary(&account.id, &alive.id)
                .unwrap()
                .unwrap()
                .is_terminated
        );
        assert!(
            !store
                .conversation_summary(&account.id, &direct.id)
                .unwrap()
                .unwrap()
                .is_terminated
        );

        // Contacts-row face: the group carries its own marker, the direct
        // row never marks.
        let contacts = store.list_contacts(&account.id, None, 10, None).unwrap();
        let ended_contact = contacts
            .items
            .iter()
            .find(|row| row.kind == "group" && row.peer_key == "ZW5kZWQ=")
            .unwrap();
        let alive_contact = contacts
            .items
            .iter()
            .find(|row| row.kind == "group" && row.peer_key == "YWxpdmU=")
            .unwrap();
        assert!(ended_contact.is_terminated);
        assert!(!alive_contact.is_terminated);
        assert!(
            contacts
                .items
                .iter()
                .filter(|row| row.kind == "contact")
                .all(|row| !row.is_terminated)
        );

        // Wire shape: true serializes, false collapses to the absent key —
        // pre-1.60 hosts read byte-identical rows.
        use serde_json::json;
        let wire = serde_json::to_value(&*listed.items).unwrap();
        let rows = wire.as_array().unwrap();
        for row in rows {
            let flag = row.get("isTerminated");
            let expected = row["id"] == json!(ended.id);
            assert_eq!(flag.is_some(), expected, "row {}", row["id"]);
            if expected {
                assert_eq!(flag, Some(&json!(true)));
            }
        }
        let contact_wire = serde_json::to_value(&*contacts.items).unwrap();
        for row in contact_wire.as_array().unwrap() {
            let expected = row["peerKey"] == json!("ZW5kZWQ=");
            assert_eq!(row.get("isTerminated").is_some(), expected);
        }

        // A group with no contacts-cache row at all (never synced) stays
        // false on both faces.
        let orphan = store
            .ensure_conversation(&account.id, "group", "b3JwaGFu", "Orphan")
            .unwrap();
        assert!(
            !store
                .conversation_summary(&account.id, &orphan.id)
                .unwrap()
                .unwrap()
                .is_terminated
        );
        let orphan_listed = store.list_conversations(&account.id, 10, None).unwrap();
        assert!(
            !orphan_listed
                .items
                .iter()
                .find(|row| row.id == orphan.id)
                .unwrap()
                .is_terminated
        );
    }

    /// Contract 1.255 (§4.240): the group row's removalStage rides the same
    /// §4.50 appendix marker the terminated flag reads — the captured
    /// `isMember: false` residual projects the official
    /// `"justNotification"` word on the list face, the single-summary
    /// (conversation.changed) face, and the wire; a healthy member row, a
    /// pre-batch row, and every direct row answer the absent key
    /// (pre-1.255 hosts read byte-identical rows). The terminated flag stays
    /// its own independent face on the Gone stamp's two-word marker.
    #[test]
    fn removal_stage_projects_the_captured_member_word() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let left = store
            .ensure_conversation(&account.id, "group", "bGVmdA==", "Left Group")
            .unwrap();
        let alive = store
            .ensure_conversation(&account.id, "group", "YWxpdmU=", "Alive Group")
            .unwrap();
        let gone = store
            .ensure_conversation(&account.id, "group", "Z29uZQ==", "Gone Group")
            .unwrap();
        let direct = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Alice")
            .unwrap();

        store
            .upsert_contact(
                &account.id,
                "group",
                "bGVmdA==",
                "Left Group",
                Some(r#"{"memberCount":3,"isMember":false}"#),
                20,
            )
            .unwrap();
        store
            .upsert_contact(
                &account.id,
                "group",
                "YWxpdmU=",
                "Alive Group",
                Some(r#"{"memberCount":4,"isMember":true}"#),
                20,
            )
            .unwrap();
        // The §4.167 Gone stamp's exact two-word shape: the legacy
        // terminated face rides beside the member word.
        store
            .upsert_contact(
                &account.id,
                "group",
                "Z29uZQ==",
                "Gone Group",
                Some(r#"{"isTerminated":true,"isMember":false}"#),
                20,
            )
            .unwrap();
        store
            .upsert_contact(&account.id, "contact", "+15555550101", "Alice", None, 20)
            .unwrap();

        // List face: the member word maps to the official notification
        // stage; the terminated flag stays independent on the same row.
        let listed = store.list_conversations(&account.id, 10, None).unwrap();
        let left_row = listed.items.iter().find(|row| row.id == left.id).unwrap();
        let alive_row = listed.items.iter().find(|row| row.id == alive.id).unwrap();
        let gone_row = listed.items.iter().find(|row| row.id == gone.id).unwrap();
        let direct_row = listed.items.iter().find(|row| row.id == direct.id).unwrap();
        assert_eq!(left_row.removal_stage.as_deref(), Some("justNotification"));
        assert!(!left_row.is_terminated);
        assert_eq!(alive_row.removal_stage, None);
        assert_eq!(gone_row.removal_stage.as_deref(), Some("justNotification"));
        assert!(gone_row.is_terminated);
        assert_eq!(direct_row.removal_stage, None);

        // Single-summary face (the conversation.changed payload): the same
        // projection, so an event-driven window and a reload cannot disagree.
        assert_eq!(
            store
                .conversation_summary(&account.id, &left.id)
                .unwrap()
                .unwrap()
                .removal_stage
                .as_deref(),
            Some("justNotification")
        );
        assert_eq!(
            store
                .conversation_summary(&account.id, &gone.id)
                .unwrap()
                .unwrap()
                .removal_stage
                .as_deref(),
            Some("justNotification")
        );
        assert_eq!(
            store
                .conversation_summary(&account.id, &alive.id)
                .unwrap()
                .unwrap()
                .removal_stage,
            None
        );

        // Wire shape: the stage serializes only when present — pre-1.255
        // hosts read byte-identical rows.
        let wire = serde_json::to_value(&*listed.items).unwrap();
        for row in wire.as_array().unwrap() {
            let stage = row.get("removalStage");
            let expected = matches!(row["id"], ref id if *id == left.id || *id == gone.id);
            assert_eq!(stage.is_some(), expected, "row {}", row["id"]);
            if expected {
                assert_eq!(stage, Some(&serde_json::json!("justNotification")));
            }
        }
    }

    /// Contract 1.256 (§4.241): the shared-group titles answer the official
    /// reverse lookup from the captured rosters — a UUID-keyed direct row
    /// matches through its service id, a phone-keyed row through its e164
    /// (both §4.229 spellings), titles order by the group rows' sync
    /// recency, the array caps at 32, group/self rows and contact group
    /// rows answer absent, and an unmatched direct row answers the computed
    /// empty array (the official EMPTY_ARRAY shape, never absence).
    #[test]
    fn received_at_ms_rides_the_newest_row_face_additively() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550102", "Peer")
            .unwrap();
        let row = |id: &str,
                   direction: &'static str,
                   sent_at: u64,
                   received_at: Option<u64>|
         -> MessageRecord {
            MessageRecord {
                is_erased: false,
                delete_failed: false,
                required_protocol_version: None,
                author_aci: None,
                id: id.into(),
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                direction,
                sender_id: "peer".into(),
                sender_name: None,
                mentions_self: false,
                sent_at,
                received_at,
                text: None,
                text_bytes: None,
                text_truncated: false,
                text_retrievable: false,
                status: "delivered",
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments: Vec::new(),
                rich: None,
                edited_at: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                admin_deleted: false,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            }
        };

        // Official activity face: the newest row stamps both moments — the
        // activity moment (last_message_at, official `timestamp`) and the
        // device-arrival moment (contract 1.265, official
        // `lastMessageReceivedAtMs`). Incoming rows carry both.
        store
            .insert_message(
                &row("m-in", "incoming", 4_000, Some(5_000)),
                None,
                None,
                false,
            )
            .unwrap();
        let listed = store.list_conversations(&account.id, 20, None).unwrap();
        let ending = listed
            .items
            .iter()
            .find(|row| row.id == conversation.id)
            .unwrap();
        assert_eq!(ending.last_message_received_at_ms, Some(5_000));
        // The single-row summary — the conversation.changed event face —
        // answers from the same newest-row meta read: a reloaded page and
        // the event-driven window cannot disagree.
        let single = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .unwrap();
        assert_eq!(single.last_message_received_at_ms, Some(5_000));
        // Wire shape: the key rides only when the store holds the stamp.
        let wire = serde_json::to_value(&single).unwrap();
        assert_eq!(wire["lastMessageReceivedAtMs"], serde_json::json!(5_000));

        // Outgoing activity stamps the same face (the official
        // getLastMessageData consumes the activity row regardless of
        // direction; our send lane stamps received_at on the outgoing row).
        store
            .insert_message(
                &row("m-out", "outgoing", 6_500, Some(7_000)),
                None,
                None,
                false,
            )
            .unwrap();
        let single = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .unwrap();
        assert_eq!(single.last_message_received_at_ms, Some(7_000));

        // A newer ending without a receive stamp (legacy/import face) moves
        // the ending: the key goes absent — absence is honest, never zero,
        // and the official comparator falls back to the activity moment
        // (conversations.dom.ts:349 `|| timestamp`).
        store
            .insert_message(&row("m-new", "incoming", 9_000, None), None, None, false)
            .unwrap();
        let listed = store.list_conversations(&account.id, 20, None).unwrap();
        let ending = listed
            .items
            .iter()
            .find(|row| row.id == conversation.id)
            .unwrap();
        assert_eq!(ending.last_message_received_at_ms, None);
        let single = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .unwrap();
        assert_eq!(single.last_message_received_at_ms, None);
        let wire = serde_json::to_value(&single).unwrap();
        assert!(wire.get("lastMessageReceivedAtMs").is_none());

        // A conversation whose ending is a rowless row never projects the
        // key either — the empty-conversation arm of the same face.
        store
            .ensure_conversation(&account.id, "direct", "+15555550103", "Empty")
            .unwrap();
        let listed = store.list_conversations(&account.id, 20, None).unwrap();
        let empty_row = listed
            .items
            .iter()
            .find(|row| row.title == "Empty")
            .unwrap();
        assert_eq!(empty_row.last_message_received_at_ms, None);
        let wire = serde_json::to_value(empty_row).unwrap();
        assert!(wire.get("lastMessageReceivedAtMs").is_none());
    }

    #[test]
    fn shared_group_names_reverse_lookup_answers_the_engine_group_table() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let aci = "11111111-1111-4111-8111-111111111111";
        let number = "+15555550102";

        // Conversations: A uuid-keyed (in two groups), B phone-keyed (in
        // one), the account's own row (self — never projects).
        let conv_a = store
            .ensure_conversation(&account.id, "direct", aci, "A")
            .unwrap();
        let conv_b = store
            .ensure_conversation(&account.id, "direct", number, "B")
            .unwrap();
        store
            .ensure_conversation(&account.id, "direct", "+15555550100", "Self")
            .unwrap();

        // Group cache rows: recency-controlled sync stamps — the newer
        // group must answer first.
        let entries = [
            SyncedContact {
                kind: "group",
                peer_key: "oldLQ==",
                title: "Old Group",
                extra: Some(
                    r#"{"memberCount":2,"members":[{"id":"22222222-2222-4222-8222-222222222222"},{"id":"11111111-1111-4111-8111-111111111111"}]}"#,
                ),
            },
            SyncedContact {
                kind: "group",
                peer_key: "bmV3",
                title: "New Group",
                extra: Some(
                    r#"{"memberCount":2,"members":[{"id":"11111111-1111-4111-8111-111111111111"},{"id":"+15555550102"}]}"#,
                ),
            },
            SyncedContact {
                kind: "contact",
                peer_key: aci,
                title: "A",
                extra: None,
            },
            SyncedContact {
                kind: "contact",
                peer_key: number,
                title: "B",
                extra: None,
            },
        ];
        store
            .upsert_passive_contacts(&account.id, &entries, 200)
            .unwrap();
        // Re-stamp the old group with an earlier synced_at: the passive
        // upsert is latest-wins, so stamp it first at 100 and the 200 batch
        // above keeps it stale — order comes out new-first.
        let stale = [SyncedContact {
            kind: "group",
            peer_key: "oldLQ==",
            title: "Old Group",
            extra: Some(
                r#"{"memberCount":2,"members":[{"id":"22222222-2222-4222-8222-222222222222"},{"id":"11111111-1111-4111-8111-111111111111"}]}"#,
            ),
        }];
        store
            .upsert_passive_contacts(&account.id, &stale, 100)
            .unwrap();

        // List face: A answers [New Group, Old Group] (recency order), B
        // answers [New Group] through the e164 spelling, the self row never
        // projects, group rows never project.
        let listed = store.list_conversations(&account.id, 20, None).unwrap();
        let row_a = listed.items.iter().find(|row| row.id == conv_a.id).unwrap();
        let row_b = listed.items.iter().find(|row| row.id == conv_b.id).unwrap();
        assert_eq!(
            row_a.shared_group_names,
            Some(vec!["New Group".to_string(), "Old Group".to_string()])
        );
        assert_eq!(
            row_b.shared_group_names,
            Some(vec!["New Group".to_string()])
        );
        assert!(
            listed
                .items
                .iter()
                .filter(|row| row.kind == "group")
                .all(|row| row.shared_group_names.is_none())
        );
        assert!(
            listed
                .items
                .iter()
                .filter(|row| row.is_self)
                .all(|row| row.shared_group_names.is_none())
        );

        // Single-summary face: the same answer the list carries.
        assert_eq!(
            store
                .conversation_summary(&account.id, &conv_a.id)
                .unwrap()
                .unwrap()
                .shared_group_names,
            Some(vec!["New Group".to_string(), "Old Group".to_string()])
        );

        // Contacts face: the contact rows carry the same titles, the group
        // rows stay absent.
        let contacts = store.list_contacts(&account.id, None, 20, None).unwrap();
        let contact_a = contacts
            .items
            .iter()
            .find(|row| row.kind == "contact" && row.peer_key == aci)
            .unwrap();
        assert_eq!(
            contact_a.shared_group_names,
            Some(vec!["New Group".to_string(), "Old Group".to_string()])
        );
        assert!(
            contacts
                .items
                .iter()
                .filter(|row| row.kind == "group")
                .all(|row| row.shared_group_names.is_none())
        );

        // An unmatched direct row answers the computed empty array.
        let stranger = store
            .ensure_conversation(&account.id, "direct", "+15555550109", "Stranger")
            .unwrap();
        let row = store
            .conversation_summary(&account.id, &stranger.id)
            .unwrap()
            .unwrap();
        assert_eq!(row.shared_group_names, Some(Vec::new()));

        // Wire shape: group rows and the self row carry no key.
        let wire = serde_json::to_value(&*listed.items).unwrap();
        for row in wire.as_array().unwrap() {
            if row["type"] == "group" {
                assert!(row.get("sharedGroupNames").is_none(), "row {}", row["id"]);
            }
        }

        // The cap: 33 groups containing A project exactly 32 titles.
        for index in 0..33 {
            let peer = format!("Y2Fw{}=", index);
            let extra = format!(r#"{{"memberCount":1,"members":[{{"id":"{aci}"}}]}}"#);
            store
                .upsert_contact(&account.id, "group", &peer, "Cap", Some(&extra), 20)
                .unwrap();
        }
        let capped = store
            .conversation_summary(&account.id, &conv_a.id)
            .unwrap()
            .unwrap()
            .shared_group_names
            .unwrap();
        assert_eq!(capped.len(), 32);
    }

    /// Contract 1.257 (§4.242): the hidden bit rides the factor stamp
    /// verbatim — present exactly when the stamp carries it, never derived
    /// through the inSystemContacts inversion (which stays verbatim beside
    /// it for the pre-1.257 consumers); group rows and unstamped rows stay
    /// absent.
    #[test]
    fn hidden_bit_rides_verbatim_beside_the_inversion() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = store
            .ensure_conversation(&account.id, "direct", "+15555550103", "C")
            .unwrap();
        let group = store
            .ensure_conversation(&account.id, "group", "Z3Jw", "Group")
            .unwrap();

        // No stamp yet: both faces absent (unknown, never invented).
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.hidden, None);
        assert_eq!(summary.in_system_contacts, None);

        // hidden=true: the bit rides verbatim; the inversion stays on its
        // own face (inSystemContacts=false).
        store
            .set_conversation_mrr_factors_for_peer(
                &account.id,
                "+15555550103",
                r#"{"hidden":true,"profileSharing":false,"blocked":false}"#,
            )
            .unwrap();
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.hidden, Some(true));
        assert_eq!(summary.in_system_contacts, Some(false));

        // hidden=false: verbatim false; the inversion answers true.
        store
            .set_conversation_mrr_factors_for_peer(
                &account.id,
                "+15555550103",
                r#"{"hidden":false,"profileSharing":false,"blocked":false}"#,
            )
            .unwrap();
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.hidden, Some(false));
        assert_eq!(summary.in_system_contacts, Some(true));

        // Group rows: no factor stamp face, always absent.
        let summary = store
            .conversation_summary(&account.id, &group.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.hidden, None);
        assert_eq!(summary.in_system_contacts, None);

        // Wire shape: hidden serializes only when the stamp carries it.
        let listed = store.list_conversations(&account.id, 10, None).unwrap();
        let wire = serde_json::to_value(&*listed.items).unwrap();
        for row in wire.as_array().unwrap() {
            let expected = row["id"] == direct.id;
            assert_eq!(row.get("hidden").is_some(), expected, "row {}", row["id"]);
        }
    }

    /// Contract 1.260 (§4.244): the verified storage-projection bit reads the
    /// identity trust stamp — TRUSTED_VERIFIED is the true arm, the other
    /// two pinned words and the probed-absent `{}` are the false arm (the
    /// official DEFAULT face), a never-probed row answers absent (never
    /// invented); group and self rows stay absent on every arm; both stamp
    /// shapes land (peer key and conversation id); the wire carries the key
    /// only when the bit exists.
    #[test]
    fn verified_bit_reads_the_identity_trust_stamp() {
        // Pure projection arms first (the §4.50 hostile-stamp discipline).
        assert_eq!(identity_verified_bit_of_stamp(None), None);
        assert_eq!(identity_verified_bit_of_stamp(Some("not json")), None);
        assert_eq!(identity_verified_bit_of_stamp(Some("[]")), None);
        assert_eq!(identity_verified_bit_of_stamp(Some("{}")), Some(false));
        assert_eq!(
            identity_verified_bit_of_stamp(Some(r#"{"trustLevel":"TRUSTED_VERIFIED"}"#)),
            Some(true)
        );
        assert_eq!(
            identity_verified_bit_of_stamp(Some(r#"{"trustLevel":"TRUSTED_UNVERIFIED"}"#)),
            Some(false)
        );
        assert_eq!(
            identity_verified_bit_of_stamp(Some(r#"{"trustLevel":"UNTRUSTED"}"#)),
            Some(false)
        );

        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = store
            .ensure_conversation(&account.id, "direct", "+15555550103", "C")
            .unwrap();
        let direct_uuid = store
            .ensure_conversation(
                &account.id,
                "direct",
                "11111111-1111-4111-8111-111111111111",
                "U",
            )
            .unwrap();
        let fresh = store
            .ensure_conversation(&account.id, "direct", "+15555550104", "F")
            .unwrap();
        let group = store
            .ensure_conversation(&account.id, "group", "Z3Jw", "Group")
            .unwrap();
        let self_row = store
            .ensure_conversation(&account.id, "direct", "+15555550100", "Note to self")
            .unwrap();

        // Never probed: absent on both faces (unknown, never a false).
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.verified, None);
        let listed = store.list_conversations(&account.id, 20, None).unwrap();
        let row = listed.items.iter().find(|row| row.id == direct.id).unwrap();
        assert_eq!(row.verified, None);

        // TRUSTED_VERIFIED via the peer-key stamp shape: the true arm.
        store
            .set_conversation_identity_verified_for_peer(
                &account.id,
                "+15555550103",
                "TRUSTED_VERIFIED",
            )
            .unwrap();
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.verified, Some(true));

        // The other two words via the conversation-id stamp shape: the
        // false arm both times (official unverified presentation).
        store
            .set_conversation_identity_verified_for_conversation(
                &account.id,
                &direct_uuid.id,
                "TRUSTED_UNVERIFIED",
            )
            .unwrap();
        let summary = store
            .conversation_summary(&account.id, &direct_uuid.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.verified, Some(false));
        // 契约 §4.223/§4.244：信任重置臂的写穿戳是**只有 trustLevel 的新
        // 对象**——引擎 sidecar 的 `pending` 挂起位随写穿一起消失（本地
        // 投影不残留挂起态；权威位仍在引擎，下一次 identities.get 收敛）。
        let raw_stamp: String = store
            .lock_conn()
            .unwrap()
            .query_row(
                "SELECT identity_verified_json FROM conversations WHERE id=?1",
                rusqlite::params![direct_uuid.id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(raw_stamp, r#"{"trustLevel":"TRUSTED_UNVERIFIED"}"#);
        store
            .set_conversation_identity_verified_for_conversation(
                &account.id,
                &direct_uuid.id,
                "UNTRUSTED",
            )
            .unwrap();
        let summary = store
            .conversation_summary(&account.id, &direct_uuid.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.verified, Some(false));

        // Group and self rows: absent on every arm (no stamp face, no read).
        store
            .set_conversation_identity_verified_for_conversation(
                &account.id,
                &group.id,
                "TRUSTED_VERIFIED",
            )
            .unwrap();
        store
            .set_conversation_identity_verified_for_conversation(
                &account.id,
                &self_row.id,
                "TRUSTED_VERIFIED",
            )
            .unwrap();
        assert_eq!(
            store
                .conversation_summary(&account.id, &group.id)
                .unwrap()
                .unwrap()
                .verified,
            None
        );
        assert_eq!(
            store
                .conversation_summary(&account.id, &self_row.id)
                .unwrap()
                .unwrap()
                .verified,
            None
        );

        // The sweep: the never-probed row takes the probed-absent `{}`
        // marker (the official DEFAULT face, false), self rows stay NULL,
        // and the trigger count self-extinguishes.
        assert_eq!(
            store
                .count_direct_conversations_without_identity_verified(&account.id)
                .unwrap(),
            1
        );
        let swept = store
            .stamp_identity_verified_absent_rows(&account.id)
            .unwrap();
        assert_eq!(swept, 1);
        assert_eq!(
            store
                .count_direct_conversations_without_identity_verified(&account.id)
                .unwrap(),
            0
        );
        let summary = store
            .conversation_summary(&account.id, &fresh.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.verified, Some(false));
        assert_eq!(
            store
                .conversation_summary(&account.id, &self_row.id)
                .unwrap()
                .unwrap()
                .verified,
            None
        );

        // Wire shape: verified serializes only when the bit exists.
        let listed = store.list_conversations(&account.id, 20, None).unwrap();
        let wire = serde_json::to_value(&*listed.items).unwrap();
        for row in wire.as_array().unwrap() {
            let expected = matches!(
                row["id"].as_str(),
                Some(id) if id == direct.id || id == direct_uuid.id || id == fresh.id
            );
            assert_eq!(row.get("verified").is_some(), expected, "row {}", row["id"]);
            if expected {
                assert!(row["verified"].is_boolean(), "row {}", row["id"]);
            }
        }
    }

    /// Z25 root-cause batch (§4.244 erratum): the owed-peer list and the
    /// per-row absent stamp — the single-reference probe's store face. The
    /// list answers the never-probed direct non-self rows in rowid order,
    /// respects the caller cap, and excludes the self spellings (empty key,
    /// the signal account, the account ACI); the per-row `{}` stamp is
    /// NULL-guarded (never clobbers a word stamp, idempotent) and
    /// extinguishes the trigger count row by row.
    #[test]
    fn verified_probe_owed_peer_list_and_absent_stamp() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let absent = store
            .ensure_conversation(&account.id, "direct", "+15555550103", "A")
            .unwrap();
        let worded = store
            .ensure_conversation(
                &account.id,
                "direct",
                "11111111-1111-4111-8111-111111111111",
                "B",
            )
            .unwrap();
        let fresh = store
            .ensure_conversation(&account.id, "direct", "+15555550104", "C")
            .unwrap();
        // Self spellings and a group row: never owed.
        store
            .ensure_conversation(&account.id, "direct", "+15555550100", "self")
            .unwrap();
        store
            .ensure_conversation(&account.id, "group", "Z3Jw", "Group")
            .unwrap();

        // Owed list: rowid order, all three non-self direct rows.
        let owed = store
            .direct_peers_without_identity_verified(&account.id, 16)
            .unwrap();
        assert_eq!(
            owed,
            vec![
                "+15555550103".to_string(),
                "11111111-1111-4111-8111-111111111111".to_string(),
                "+15555550104".to_string(),
            ]
        );

        // The cap bounds the window (deterministic head of the queue).
        let owed = store
            .direct_peers_without_identity_verified(&account.id, 2)
            .unwrap();
        assert_eq!(
            owed,
            vec![
                "+15555550103".to_string(),
                "11111111-1111-4111-8111-111111111111".to_string(),
            ]
        );

        // Per-row absent stamp: lands `{}` (the read face folds to the
        // official DEFAULT false), extinguishes exactly that row, is
        // idempotent under the NULL guard, and never clobbers a word stamp.
        assert!(
            store
                .stamp_identity_verified_absent_peer(&account.id, "+15555550103")
                .unwrap()
        );
        assert!(
            !store
                .stamp_identity_verified_absent_peer(&account.id, "+15555550103")
                .unwrap()
        );
        let summary = store
            .conversation_summary(&account.id, &absent.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.verified, Some(false));
        store
            .set_conversation_identity_verified_for_peer(
                &account.id,
                "11111111-1111-4111-8111-111111111111",
                "TRUSTED_VERIFIED",
            )
            .unwrap();
        assert!(
            !store
                .stamp_identity_verified_absent_peer(
                    &account.id,
                    "11111111-1111-4111-8111-111111111111"
                )
                .unwrap()
        );
        let summary = store
            .conversation_summary(&account.id, &worded.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.verified, Some(true));

        // Only the untouched row stays owed; the window extinguishes.
        let owed = store
            .direct_peers_without_identity_verified(&account.id, 16)
            .unwrap();
        assert_eq!(owed, vec!["+15555550104".to_string()]);
        assert_eq!(
            store
                .count_direct_conversations_without_identity_verified(&account.id)
                .unwrap(),
            1
        );
        let _ = fresh;
    }

