    /// Sticker persistence (contract revision 1.35, §4.31): the pack identity
    /// round-trips through `sticker_json` beside the metadata-only descriptor,
    /// and `MessageRecord` keeps absent sticker keys off the wire so pre-1.35
    /// rows stay byte-identical.
    #[test]
    fn sticker_row_round_trips_and_plain_rows_stay_key_absent() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let base = |id: &str, sent_at: u64| MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: id.into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "outgoing",
            sender_id: account.id.clone(),
            sender_name: None,
            mentions_self: false,
            sent_at,
            received_at: None,
            text: None,
            text_bytes: None,
            text_truncated: false,
            text_retrievable: false,
            status: "sent",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            admin_deleted: false,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };

        let mut sticker_row = base("sticker-row", 60);
        sticker_row.attachments = vec![crate::engine::NormalizedAttachment {
            id: "att-sticker".into(),
            content_type: Some("image/webp".into()),
            filename: None,
            size: Some(8192),
            width: Some(512),
            height: Some(512),
            is_voice_note: false,
            caption: None,
            blur_hash: None,
            incremental_mac: None,
            chunk_size: None,
            is_borderless: false,
            is_gif: false,
            locator: None,
            waveform: None,
            duration: None,
        }];
        sticker_row.sticker = Some(crate::engine::NormalizedSticker {
            pack_id: "abcdef01".into(),
            pack_key: "AAAAAAAAAAAAAAAAAAAAAA==".into(),
            sticker_id: 7,
            emoji: Some("🎉".into()),
        });
        store
            .insert_message(&sticker_row, Some("req-sticker-store"), None, false)
            .unwrap();
        let row = store
            .message_by_client_request(&account.id, "req-sticker-store")
            .unwrap()
            .expect("the sticker row exists");
        let sticker = row
            .sticker
            .clone()
            .expect("the pack identity survives the store");
        assert_eq!(sticker.pack_id, "abcdef01");
        assert_eq!(sticker.pack_key, "AAAAAAAAAAAAAAAAAAAAAA==");
        assert_eq!(sticker.sticker_id, 7);
        assert_eq!(sticker.emoji.as_deref(), Some("🎉"));
        assert_eq!(row.attachments.len(), 1);
        assert_eq!(row.attachments[0].id, "att-sticker");
        assert_eq!(row.attachments[0].width, Some(512));
        let wire = serde_json::to_value(&row).unwrap();
        assert_eq!(wire["sticker"]["packId"], "abcdef01");
        assert_eq!(wire["sticker"]["stickerId"], 7);
        assert_eq!(wire["attachments"][0]["contentType"], "image/webp");
        assert!(wire["attachments"][0].get("filename").is_none());

        // A plain row keeps the key absent — pre-1.35 rows stay byte-identical
        // on the wire.
        store
            .insert_message(&base("plain-row", 61), None, None, false)
            .unwrap();
        let rows = store
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap()
            .items;
        let plain_row = rows
            .iter()
            .find(|row| row.id == "plain-row")
            .expect("the plain row exists");
        let wire = serde_json::to_value(plain_row).unwrap();
        assert!(wire.get("sticker").is_none(), "{wire}");
    }

    /// Conversation pin state (contract 1.33; multi-pin queue, diff-C #54):
    /// distinct targets coexist as queue members ordered `pinned_at` ASC, the
    /// legacy single face projects the newest, a targeted clear removes only
    /// the named member, and the summary projects the camelCase
    /// `pinnedMessages` array + `pinnedMessage` (newest) with `expiresAt`
    /// only on a live timed pin — an expired timed pin (`duration 0` =
    /// already past) and a pin whose target row is gone stop rendering.
    #[test]
    fn conversation_pin_queue_coexists_clears_targeted_and_projects_both_faces() {
        use serde_json::json;
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let base = |id: &str, sent_at: u64| MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: id.into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "incoming",
            sender_id: "peer".into(),
            sender_name: None,
            mentions_self: false,
            sent_at,
            received_at: None,
            text: Some("body".into()),
            text_bytes: Some(4),
            text_truncated: false,
            text_retrievable: true,
            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        assert!(
            store
                .insert_message(&base("m1", 10), None, Some("body"), true)
                .unwrap()
        );
        assert!(
            store
                .insert_message(&base("m2", 20), None, Some("body"), true)
                .unwrap()
        );

        // Forever pin on the first row: projected with the resolved message
        // id and no expiresAt (the wire key stays absent).
        store
            .append_conversation_pin(
                &account.id,
                &conversation.id,
                "+15555550101",
                10,
                1_700_000_000_000,
                None,
            )
            .unwrap();
        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .unwrap();
        let pinned = summary.pinned_message.as_ref().unwrap();
        assert_eq!(pinned.message_id, "m1");
        assert_eq!(pinned.target_author, "+15555550101");
        assert_eq!(pinned.target_sent_timestamp, 10);
        assert_eq!(pinned.pinned_at, 1_700_000_000_000);
        assert_eq!(pinned.expires_at, None);
        let wire = serde_json::to_value(&summary).unwrap();
        assert_eq!(wire["pinnedMessage"]["messageId"], json!("m1"));
        assert_eq!(wire["pinnedMessage"]["targetSentTimestamp"], json!(10));
        assert!(wire["pinnedMessage"].get("expiresAt").is_none());

        // A second pin on another row joins the queue (official
        // getPinnedMessagesLimit = 3): both render, `pinned_at` ASC, and the
        // legacy single face keeps projecting the newest so single-pin hosts
        // read the same row they always did.
        store
            .append_conversation_pin(
                &account.id,
                &conversation.id,
                "+15555550101",
                20,
                1_700_000_000_001,
                Some(4_000_000_000_000),
            )
            .unwrap();
        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .unwrap();
        let pinned = summary.pinned_message.as_ref().unwrap();
        assert_eq!(pinned.message_id, "m2");
        assert!(pinned.expires_at.is_some(), "a timed pin carries expiry");
        let wire = serde_json::to_value(&summary).unwrap();
        assert!(wire["pinnedMessage"]["expiresAt"].is_u64());
        assert_eq!(
            summary
                .pinned_messages
                .iter()
                .map(|pin| pin.message_id.as_str())
                .collect::<Vec<_>>(),
            vec!["m1", "m2"],
            "the queue renders oldest-first"
        );
        assert_eq!(wire["pinnedMessages"][0]["messageId"], json!("m1"));
        assert_eq!(wire["pinnedMessages"][1]["messageId"], json!("m2"));

        // A targeted clear removes only the named member.
        assert!(
            store
                .clear_conversation_pin(&account.id, &conversation.id, 10)
                .unwrap()
        );
        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .unwrap();
        assert_eq!(
            summary
                .pinned_messages
                .iter()
                .map(|pin| pin.message_id.as_str())
                .collect::<Vec<_>>(),
            vec!["m2"]
        );

        // The matching clear removes the last member and empties both faces.
        assert!(
            store
                .clear_conversation_pin(&account.id, &conversation.id, 20)
                .unwrap()
        );
        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .unwrap();
        assert!(summary.pinned_message.is_none());
        assert!(summary.pinned_messages.is_empty());
        let wire = serde_json::to_value(&summary).unwrap();
        assert!(wire.get("pinnedMessages").is_none(), "{wire}");

        // An already-expired timed pin (a deadline in the past) and a pin
        // whose target row is no longer in the history stop rendering.
        store
            .append_conversation_pin(
                &account.id,
                &conversation.id,
                "+15555550101",
                10,
                1_700_000_000_002,
                Some(1),
            )
            .unwrap();
        assert!(
            store
                .conversation_summary(&account.id, &conversation.id)
                .unwrap()
                .unwrap()
                .pinned_message
                .is_none(),
            "an expired pin must not render"
        );
        store
            .append_conversation_pin(
                &account.id,
                &conversation.id,
                "+15555550101",
                999,
                1_700_000_000_003,
                None,
            )
            .unwrap();
        assert!(
            store
                .conversation_summary(&account.id, &conversation.id)
                .unwrap()
                .unwrap()
                .pinned_message
                .is_none(),
            "a pin without a local row must not render"
        );
    }

    /// Multi-pin queue cap (diff-C #54): the queue holds at most
    /// `CONVERSATION_PIN_LIMIT` (official `getPinnedMessagesLimit` = 3)
    /// members; a pin past the cap replaces the row with the oldest
    /// `pinned_at`, and re-pinning an existing member refreshes its stamp
    /// without growing the queue.
    #[test]
    fn conversation_pin_queue_caps_at_three_replacing_the_oldest() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let base = |id: &str, sent_at: u64| MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: id.into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "incoming",
            sender_id: "peer".into(),
            sender_name: None,
            mentions_self: false,
            sent_at,
            received_at: None,
            text: Some("body".into()),
            text_bytes: Some(4),
            text_truncated: false,
            text_retrievable: true,
            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        for (id, sent_at) in [("m1", 10), ("m2", 20), ("m3", 30), ("m4", 40)] {
            assert!(
                store
                    .insert_message(&base(id, sent_at), None, Some("body"), true)
                    .unwrap()
            );
        }

        for (index, sent_at) in [10, 20, 30].into_iter().enumerate() {
            store
                .append_conversation_pin(
                    &account.id,
                    &conversation.id,
                    "+15555550101",
                    sent_at,
                    1_700_000_000_000 + index as u64,
                    None,
                )
                .unwrap();
        }
        let queue = |store: &Store| {
            store
                .conversation_summary(&account.id, &conversation.id)
                .unwrap()
                .unwrap()
                .pinned_messages
                .iter()
                .map(|pin| pin.message_id.clone())
                .collect::<Vec<_>>()
        };
        assert_eq!(queue(&store), vec!["m1", "m2", "m3"]);

        // The fourth pin replaces the oldest (m1) — receiver-side enforcement
        // of the official replace-earliest discipline keeps the queue bounded.
        store
            .append_conversation_pin(
                &account.id,
                &conversation.id,
                "+15555550101",
                40,
                1_700_000_000_003,
                None,
            )
            .unwrap();
        assert_eq!(queue(&store), vec!["m2", "m3", "m4"]);

        // Re-pinning an existing member refreshes its stamp in place; the
        // queue neither grows nor evicts (m2 moves to the newest slot).
        store
            .append_conversation_pin(
                &account.id,
                &conversation.id,
                "+15555550101",
                20,
                1_700_000_000_004,
                None,
            )
            .unwrap();
        assert_eq!(queue(&store), vec!["m3", "m4", "m2"]);
        assert_eq!(queue(&store).len(), CONVERSATION_PIN_LIMIT);
    }

    /// Official `appendPinnedMessage` (pinnedMessages.std.ts:157-201): the
    /// same target replaces only when the incoming `pinned_at` is strictly
    /// newer, so an older backup replay never clobbers the newer live row.
    /// The local key is the target stamp — not the author spelling — so the
    /// import face (ACI) and the live face (E.164) converge on one row.
    #[test]
    fn conversation_pin_same_target_keeps_newer_pin_across_author_spellings() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        assert!(
            store
                .insert_message(
                    &pin_test_message(&account.id, &conversation.id, "m1", 10),
                    None,
                    Some("body"),
                    true,
                )
                .unwrap()
        );

        // Backup import first (older `pinnedAtTimestamp`), then the live pin
        // from another device (newer receive clock), then the import replayed
        // — the replay must leave the newer live row alone.
        store
            .append_conversation_pin(
                &account.id,
                &conversation.id,
                "8fc00000-0000-4000-8000-000000000001",
                10,
                500,
                None,
            )
            .unwrap();
        store
            .append_conversation_pin(
                &account.id,
                &conversation.id,
                "+15555550101",
                10,
                600,
                Some(9_999_999_999_999),
            )
            .unwrap();
        store
            .append_conversation_pin(
                &account.id,
                &conversation.id,
                "8fc00000-0000-4000-8000-000000000001",
                10,
                500,
                None,
            )
            .unwrap();

        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.pinned_messages.len(), 1, "one target, one row");
        let pinned = summary.pinned_message.as_ref().unwrap();
        assert_eq!(pinned.message_id, "m1");
        assert_eq!(pinned.pinned_at, 600, "the newer pin survives the replay");
        assert_eq!(
            pinned.target_author, "+15555550101",
            "the newer live spelling is the stored display face"
        );
        assert_eq!(pinned.expires_at, Some(9_999_999_999_999));
        let rows: i64 = store
            .conn()
            .query_row("SELECT COUNT(*) FROM conversation_pins", [], |row| {
                row.get(0)
            })
            .unwrap();
        assert_eq!(rows, 1);
    }

    /// 契约 1.280（§4.264）schema v49: the payload table's primary key widens
    /// from clientRequestId alone to (clientRequestId, attachmentIndex). A v48
    /// row migrates to index 0 with every field preserved, the rebuilt table
    /// accepts a second index for the same request (the composite key is real),
    /// and the account index comes back with the rename.
    #[test]
    fn schema_v49_upgrades_attachment_payloads_to_composite_key() {
        const DATA_URI: &str = "data:text/plain;filename=notes.txt;base64,YXR0YWNobWVudCBieXRlcw==";
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("connector.sqlite3");
        let now = crate::link::now_ms();
        let created_at = now.saturating_sub(1_000);
        let conn = Connection::open(&path).unwrap();
        conn.execute_batch(&format!(
            "CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
             INSERT INTO meta(key, value) VALUES('schema_version', '48');
             CREATE TABLE accounts (
               id TEXT PRIMARY KEY,
               signal_account TEXT NOT NULL UNIQUE,
               masked_address TEXT NOT NULL,
               state TEXT NOT NULL
             );
             INSERT INTO accounts VALUES('a1', '+15555550100', '+1555***00', 'ready');
             CREATE TABLE outgoing_attachment_payloads (
               client_request_id TEXT PRIMARY KEY,
               account_id TEXT NOT NULL,
               conversation_id TEXT NOT NULL,
               data_uri TEXT NOT NULL,
               created_at INTEGER NOT NULL,
               updated_at INTEGER NOT NULL
             );
             CREATE INDEX outgoing_attachment_payloads_account
               ON outgoing_attachment_payloads(account_id, conversation_id);
             INSERT INTO outgoing_attachment_payloads VALUES
               ('req-v48', 'a1', 'c1', '{DATA_URI}', {created_at}, {now});"
        ))
        .unwrap();
        drop(conn);

        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let version: i64 = store
            .conn()
            .query_row(
                "SELECT CAST(value AS INTEGER) FROM meta WHERE key='schema_version'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(version, SCHEMA_VERSION);
        assert_eq!(
            store
                .outgoing_attachment_payload("a1", "req-v48", 0)
                .unwrap()
                .as_deref(),
            Some(DATA_URI),
            "the v48 single-key row lands at index 0"
        );
        assert_eq!(
            store.outgoing_attachment_payloads("a1", "req-v48").unwrap(),
            vec![(0, DATA_URI.to_string())]
        );
        let migrated: (String, String, String, i64, i64) = store
            .conn()
            .query_row(
                "SELECT account_id, conversation_id, data_uri, created_at, updated_at
                   FROM outgoing_attachment_payloads
                  WHERE client_request_id='req-v48' AND attachment_index=0",
                [],
                |row| {
                    Ok((
                        row.get(0)?,
                        row.get(1)?,
                        row.get(2)?,
                        row.get(3)?,
                        row.get(4)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(
            migrated,
            (
                "a1".to_string(),
                "c1".to_string(),
                DATA_URI.to_string(),
                created_at as i64,
                now as i64,
            ),
            "every column the v48 row carried survives the rebuild"
        );
        // The composite key is real: a second index for the same request fits.
        store
            .remember_outgoing_attachment_payload("a1", "c1", "req-v48", 1, DATA_URI, now)
            .unwrap();
        assert_eq!(
            store.outgoing_attachment_payloads("a1", "req-v48").unwrap(),
            vec![(0, DATA_URI.to_string()), (1, DATA_URI.to_string())]
        );
        let account_index: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master
                  WHERE type='index' AND name='outgoing_attachment_payloads_account'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(account_index, 1, "the account/conversation index is back");
    }

    /// 契约 1.280（§4.264）schema v49（形状驱动）：版本号已经写成 49、主键还是
    /// 中间形状 (client_request_id, attachment_index) 的库，在下一次开库时按当前
    /// 形状重建——主键补上 account_id、两行原样保留；重建后同一个
    /// clientRequestId 在两个账号下各是一行，互不覆盖。
    #[test]
    fn schema_v49_rebuilds_the_intermediate_payload_key_and_keeps_rows() {
        const DATA_URI: &str = "data:text/plain;filename=notes.txt;base64,YXR0YWNobWVudCBieXRlcw==";
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("connector.sqlite3");
        let now = crate::link::now_ms();
        let conn = Connection::open(&path).unwrap();
        conn.execute_batch(&format!(
            "CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
             INSERT INTO meta(key, value) VALUES('schema_version', '49');
             CREATE TABLE accounts (
               id TEXT PRIMARY KEY,
               signal_account TEXT NOT NULL UNIQUE,
               masked_address TEXT NOT NULL,
               state TEXT NOT NULL
             );
             INSERT INTO accounts VALUES('a1', '+15555550100', '+1555***00', 'ready');
             INSERT INTO accounts VALUES('a2', '+15555550101', '+1555***01', 'ready');
             CREATE TABLE outgoing_attachment_payloads (
               client_request_id TEXT NOT NULL,
               attachment_index INTEGER NOT NULL,
               account_id TEXT NOT NULL,
               conversation_id TEXT NOT NULL,
               data_uri TEXT NOT NULL,
               created_at INTEGER NOT NULL,
               updated_at INTEGER NOT NULL,
               PRIMARY KEY(client_request_id, attachment_index)
             );
             INSERT INTO outgoing_attachment_payloads VALUES
               ('req-intermediate', 0, 'a1', 'c1', '{DATA_URI}', {now}, {now}),
               ('req-intermediate', 1, 'a1', 'c1', '{DATA_URI}', {now}, {now});"
        ))
        .unwrap();
        drop(conn);

        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        assert_eq!(
            table_primary_key_columns(&store.conn(), "outgoing_attachment_payloads").unwrap(),
            vec![
                "account_id".to_string(),
                "client_request_id".to_string(),
                "attachment_index".to_string(),
            ],
            "the rebuild widens the primary key to the account-scoped shape"
        );
        assert_eq!(
            store
                .outgoing_attachment_payloads("a1", "req-intermediate")
                .unwrap(),
            vec![(0, DATA_URI.to_string()), (1, DATA_URI.to_string())],
            "both intermediate rows survive the rebuild"
        );
        // The widened key is account-scoped: the same clientRequestId lands as
        // the second account's own row instead of colliding with a1's group.
        store
            .remember_outgoing_attachment_payload("a2", "c2", "req-intermediate", 0, DATA_URI, now)
            .unwrap();
        assert_eq!(
            store
                .outgoing_attachment_payloads("a2", "req-intermediate")
                .unwrap(),
            vec![(0, DATA_URI.to_string())],
            "the second account reads back its own bytes"
        );
        assert_eq!(
            store
                .outgoing_attachment_payloads("a1", "req-intermediate")
                .unwrap()
                .len(),
            2,
            "a2's write never touches a1's group"
        );
    }

    /// 契约 1.280（§4.264）schema v49（中断恢复）：旧实现逐条 DDL、没有事务，
    /// 崩在 COPY 与 DROP 之间会留下残表 outgoing_attachment_payloads_v49。开库
    /// 时必须**继续搬运**：已经搬进残表的行不重复、还留在现表的行补上，残表随后
    /// 消失，主键是当前形状。
    #[test]
    fn schema_v49_recovers_an_interrupted_payload_rebuild() {
        const MOVED_URI: &str =
            "data:text/plain;filename=moved.txt;base64,YXR0YWNobWVudCBieXRlcw==";
        const LEFT_URI: &str = "data:text/plain;filename=left.txt;base64,bGVmdCBieXRlcw==";
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("connector.sqlite3");
        let now = crate::link::now_ms();
        let moved_created_at = now.saturating_sub(5_000);
        let conn = Connection::open(&path).unwrap();
        conn.execute_batch(&format!(
            "CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
             INSERT INTO meta(key, value) VALUES('schema_version', '48');
             CREATE TABLE accounts (
               id TEXT PRIMARY KEY,
               signal_account TEXT NOT NULL UNIQUE,
               masked_address TEXT NOT NULL,
               state TEXT NOT NULL
             );
             INSERT INTO accounts VALUES('a1', '+15555550100', '+1555***00', 'ready');
             CREATE TABLE outgoing_attachment_payloads (
               client_request_id TEXT PRIMARY KEY,
               account_id TEXT NOT NULL,
               conversation_id TEXT NOT NULL,
               data_uri TEXT NOT NULL,
               created_at INTEGER NOT NULL,
               updated_at INTEGER NOT NULL
             );
             INSERT INTO outgoing_attachment_payloads VALUES
               ('req-moved', 'a1', 'c1', '{MOVED_URI}', {moved_created_at}, {now}),
               ('req-left', 'a1', 'c1', '{LEFT_URI}', {now}, {now});
             CREATE TABLE outgoing_attachment_payloads_v49 (
               client_request_id TEXT NOT NULL,
               attachment_index INTEGER NOT NULL,
               account_id TEXT NOT NULL,
               conversation_id TEXT NOT NULL,
               data_uri TEXT NOT NULL,
               created_at INTEGER NOT NULL,
               updated_at INTEGER NOT NULL,
               PRIMARY KEY(client_request_id, attachment_index),
               FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE CASCADE
             );
             INSERT INTO outgoing_attachment_payloads_v49 VALUES
               ('req-moved', 0, 'a1', 'c1', '{MOVED_URI}', {moved_created_at}, {now});"
        ))
        .unwrap();
        drop(conn);

        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        assert_eq!(
            store
                .outgoing_attachment_payload("a1", "req-moved", 0)
                .unwrap()
                .as_deref(),
            Some(MOVED_URI),
            "the row the interrupted copy already moved is still there"
        );
        assert_eq!(
            store
                .outgoing_attachment_payload("a1", "req-left", 0)
                .unwrap()
                .as_deref(),
            Some(LEFT_URI),
            "the row the interrupted copy never reached is picked up now"
        );
        let total: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM outgoing_attachment_payloads",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(total, 2, "no row is duplicated by resuming the copy");
        let created_at: i64 = store
            .conn()
            .query_row(
                "SELECT created_at FROM outgoing_attachment_payloads
                  WHERE account_id='a1' AND client_request_id='req-moved'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(
            created_at, moved_created_at as i64,
            "the moved row keeps its original creation stamp"
        );
        assert!(
            !table_exists(&store.conn(), "outgoing_attachment_payloads_v49").unwrap(),
            "the residual staging table is consumed, not left behind"
        );
        assert_eq!(
            table_primary_key_columns(&store.conn(), "outgoing_attachment_payloads").unwrap(),
            vec![
                "account_id".to_string(),
                "client_request_id".to_string(),
                "attachment_index".to_string(),
            ],
            "the resumed rebuild lands on the account-scoped key"
        );
    }

    /// 契约 1.280（§4.264）schema v49（中断恢复，DROP 之后）：崩在 DROP 与
    /// RENAME 之间的库开库时现表由 SCHEMA_DDL 重新建成空表，残表里的行是唯一
