    #[test]
    fn concurrent_status_updates_never_mismatch_record_and_transition() {
        // Regression (optimization-plan A6): update_message_status used to run
        // its UPDATE and its read-back SELECT in two separate lock rounds, so
        // a concurrent writer could flip the status in between and the call
        // would return the other writer's row together with changed=true — a
        // status event this call never set. The single transaction keeps the
        // pair atomic: the read-back must always report the status this call
        // wrote (a replayed write reports the same status with changed=false).
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let message = MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: "contended".into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "outgoing",
            sender_id: account.id.clone(),
            sender_name: None,
            mentions_self: false,
            sent_at: 10,
            received_at: None,
            text: Some("body".into()),
            text_bytes: Some(4),
            text_truncated: false,
            text_retrievable: true,
            status: "pending",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        store
            .insert_message(&message, None, Some("body"), false)
            .unwrap();

        let store = std::sync::Arc::new(store);
        std::thread::scope(|scope| {
            for thread_index in 0..4_u32 {
                let store = std::sync::Arc::clone(&store);
                scope.spawn(move || {
                    for round in 0..750_u32 {
                        let status = if (thread_index + round) % 2 == 0 {
                            "sent"
                        } else {
                            "failed"
                        };
                        let (record, _changed) = store
                            .update_message_status("contended", status, None)
                            .unwrap()
                            .expect("contended row exists");
                        assert_eq!(
                            record.status, status,
                            "read-back must report the status this call wrote"
                        );
                    }
                });
            }
        });
    }

    /// Contract 1.109 (§4.90): the remote delete is author-scoped at the
    /// store level — per-sender clocks let two members' rows share one
    /// (conversation, sent_at), and only the delete author's own row ever
    /// transitions; an author with no row answers None, and a replay
    /// answers the already-deleted row with changed=false.
    #[test]
    fn remote_delete_scopes_to_the_delete_author() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "group", "Z3JvdXAtc2NvcGU", "Scoped")
            .unwrap();
        let row = |store: &Store, id: &str, sender: &str| {
            let message = MessageRecord {
                is_erased: false,
                delete_failed: false,
                required_protocol_version: None,
                author_aci: None,
                id: id.into(),
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                direction: "incoming",
                sender_id: sender.into(),
                sender_name: None,
                mentions_self: false,
                sent_at: 700,
                received_at: None,
                text: Some(id.into()),
                text_bytes: None,
                text_truncated: false,
                text_retrievable: true,
                status: "delivered",
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments: Vec::new(),
                edited_at: None,
                rich: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                admin_deleted: false,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            };
            store.insert_message(&message, None, None, false).unwrap();
        };
        row(&store, "author-a", "hash-a");
        row(&store, "author-b", "hash-b");

        // Author B's delete converges only B's own row, never A's.
        let applied = store
            .mark_remote_deleted(&account.id, &conversation.id, 700, "hash-b")
            .unwrap()
            .expect("the author's own row exists");
        assert_eq!(applied.0.id, "author-b");
        assert!(applied.1, "the first transition reports changed");
        let untouched = store
            .message_by_id(&account.id, &conversation.id, "author-a")
            .unwrap()
            .unwrap();
        assert_eq!(untouched.status, "delivered");

        // An author with no row at the timestamp answers None.
        assert!(
            store
                .mark_remote_deleted(&account.id, &conversation.id, 700, "hash-c")
                .unwrap()
                .is_none(),
            "a foreign author's delete matches no row of its own"
        );

        // Author A's own delete converges only its row; the replay reports
        // the same row with changed=false.
        let own = store
            .mark_remote_deleted(&account.id, &conversation.id, 700, "hash-a")
            .unwrap()
            .expect("the author's own row exists");
        assert_eq!(own.0.id, "author-a");
        assert!(own.1);
        let replay = store
            .mark_remote_deleted(&account.id, &conversation.id, 700, "hash-a")
            .unwrap()
            .expect("the replay still finds the row");
        assert!(
            !replay.1,
            "the replayed delete never re-reports a transition"
        );
    }

    /// Contract 1.111 (§4.92): the startup sweep — a 'pending' outgoing row
    /// is a send whose completion never landed (the process died between the
    /// insert and the engine answer), so the next open migrates it to
    /// 'failed' where the desktop's retry affordance applies; rows in any
    /// other status are untouched, and a reopen of an already-swept store
    /// sweeps nothing.
    #[test]
    fn startup_sweep_migrates_stale_pending_sends_to_failed() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let row = |store: &Store, id: &str, status: &'static str| {
            let message = MessageRecord {
                is_erased: false,
                delete_failed: false,
                required_protocol_version: None,
                author_aci: None,
                id: id.into(),
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                direction: "outgoing",
                sender_id: account.id.clone(),
                sender_name: None,
                mentions_self: false,
                sent_at: 100,
                received_at: None,
                text: Some("body".into()),
                text_bytes: Some(4),
                text_truncated: false,
                text_retrievable: true,
                status,
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments: Vec::new(),
                edited_at: None,
                rich: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                admin_deleted: false,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            };
            store.insert_message(&message, None, None, false).unwrap();
        };
        row(&store, "stale-pending", "pending");
        row(&store, "sent-ok", "sent");
        row(&store, "failed-already", "failed");
        drop(store);

        // The reopen sweeps exactly the stale pending row.
        let reopened = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let status_of = |id: &str| {
            reopened
                .message_by_id(&account.id, &conversation.id, id)
                .unwrap()
                .unwrap()
                .status
        };
        assert_eq!(status_of("stale-pending"), "failed");
        assert_eq!(status_of("sent-ok"), "sent");
        assert_eq!(status_of("failed-already"), "failed");

        // The swept row carries the desktop's retry affordance: the guarded
        // failed→pending rearm works on it like any failure.
        let (record, changed) = reopened
            .rearm_failed_message("stale-pending")
            .unwrap()
            .expect("the swept row rearms");
        assert!(changed);
        assert_eq!(record.status, "pending");

        // A reopen of the already-swept store applies the same honesty to the
        // re-armed row: a 'pending' row observed at open is by definition
        // orphaned (its dispatch lives inside the process that just died), so
        // the sweep takes it back to 'failed' — the retry affordance simply
        // re-arms again, and no spinner can outlive its process twice.
        drop(reopened);
        let third = Store::open(temp.path(), Some(test_store_key())).unwrap();
        assert_eq!(
            third
                .message_by_id(&account.id, &conversation.id, "stale-pending")
                .unwrap()
                .unwrap()
                .status,
            "failed"
        );
    }

    /// Contract 1.112 (§4.93): Signal timestamps are per-sender clocks, so
    /// rows can land out of order — a delayed delivery (a peer back from
    /// offline) or a slow send completion carrying an older upstream
    /// timestamp must never drag the conversation/account endings backwards.
    /// The unread counters stay unconditional: an old message still deserves
    /// its badge.
    #[test]
    fn message_insert_and_send_completion_never_regress_the_ending() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let row = |store: &Store,
                   id: &str,
                   direction: &'static str,
                   sender: &str,
                   sent_at: u64,
                   status: &'static str| {
            let message = MessageRecord {
                is_erased: false,
                delete_failed: false,
                required_protocol_version: None,
                author_aci: None,
                id: id.into(),
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                direction,
                sender_id: sender.into(),
                sender_name: None,
                mentions_self: false,
                sent_at,
                received_at: None,
                text: Some(id.into()),
                text_bytes: None,
                text_truncated: false,
                text_retrievable: true,
                status,
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments: Vec::new(),
                edited_at: None,
                rich: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                admin_deleted: false,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            };
            let increment_unread = direction == "incoming";
            store
                .insert_message(&message, None, None, increment_unread)
                .unwrap();
        };
        let ending = |store: &Store| {
            let conversation = store
                .conversation_summary(&account.id, &conversation.id)
                .unwrap()
                .unwrap();
            let account = store.account_summary(&account.id).unwrap().unwrap();
            (
                conversation.last_message_at,
                conversation.unread_count,
                account.last_message_at,
            )
        };

        // A pending send composes (its local clock reads 450), then the peer
        // answers with newer rows while the dispatch is still in flight.
        row(&store, "slow-send", "outgoing", &account.id, 450, "pending");
        assert_eq!(ending(&store), (Some(450), 0, Some(450)));
        row(&store, "newer", "incoming", "peer-hash", 500, "delivered");
        assert_eq!(ending(&store), (Some(500), 1, Some(500)));

        // A delayed older row lands: the ending stays, the badge still moves.
        row(&store, "older", "incoming", "peer-hash", 300, "delivered");
        assert_eq!(ending(&store), (Some(500), 2, Some(500)));

        // The slow send completes with its upstream timestamp (450): the
        // pre-guard code dragged the ending back to 450; now it stays.
        store
            .complete_outgoing_send("slow-send", &account.id, &conversation.id, 450, None)
            .unwrap()
            .expect("the pending row exists");
        assert_eq!(ending(&store), (Some(500), 2, Some(500)));

        // A pending send inserted with an absurdly stale local clock value
        // does not regress the ending either (the insert guard covers
        // outgoing rows the same way), and its completion inside the ladder
        // still advances the ending.
        row(&store, "fast-send", "outgoing", &account.id, 1, "pending");
        assert_eq!(ending(&store), (Some(500), 2, Some(500)));
        store
            .complete_outgoing_send("fast-send", &account.id, &conversation.id, 600, None)
            .unwrap()
            .expect("the pending row exists");
        assert_eq!(ending(&store), (Some(600), 2, Some(600)));
    }

    #[test]
    fn conversation_cursor_follows_full_sort_key_without_skips() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let older = store
            .ensure_conversation(&account.id, "direct", "older", "Older")
            .unwrap();
        let newer = store
            .ensure_conversation(&account.id, "direct", "newer", "Newer")
            .unwrap();
        let empty = store
            .ensure_conversation(&account.id, "direct", "empty", "Empty")
            .unwrap();
        let same_time = store
            .ensure_conversation(&account.id, "direct", "same-time", "Same time")
            .unwrap();
        for (conversation, id, sent_at) in [
            (&older, "older-message", 10),
            (&newer, "newer-message", 20),
            (&same_time, "same-time-message", 20),
        ] {
            let message = MessageRecord {
                is_erased: false,
                delete_failed: false,
                required_protocol_version: None,
                author_aci: None,
                id: id.into(),
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                direction: "incoming",
                sender_id: "peer".into(),
                sender_name: None,
                mentions_self: false,
                sent_at,
                received_at: Some(sent_at),
                text: Some(id.into()),
                text_bytes: Some(id.len() as u32),
                text_truncated: false,
                text_retrievable: true,
                status: "delivered",
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments: Vec::new(),
                edited_at: None,
                rich: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                admin_deleted: false,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            };
            store
                .insert_message(&message, None, Some(id), false)
                .unwrap();
        }

        let mut cursor = None;
        let mut ids = Vec::new();
        loop {
            let page = store
                .list_conversations(&account.id, 1, cursor.as_deref())
                .unwrap();
            ids.extend(page.items.into_iter().map(|item| item.id));
            cursor = page.next_cursor;
            if cursor.is_none() {
                break;
            }
        }

        let mut same_timestamp_ids = [newer.id.clone(), same_time.id.clone()];
        same_timestamp_ids.sort();
        same_timestamp_ids.reverse();
        assert_eq!(
            ids,
            [
                same_timestamp_ids[0].clone(),
                same_timestamp_ids[1].clone(),
                older.id.clone(),
                empty.id.clone(),
            ],
        );
        assert!(matches!(
            store.list_conversations(&account.id, 1, Some("bad-cursor")),
            Err(StoreError::InvalidCursor),
        ));
        let other_account = store
            .upsert_account_from_signal("+15555550101", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let (cursor_conversation, remaining_same_time) = if newer.id > same_time.id {
            (&newer, &same_time)
        } else {
            (&same_time, &newer)
        };
        let account_cursor = format!("v2:{}:0:20:{}", account.id, cursor_conversation.id);
        assert!(matches!(
            store.list_conversations(&other_account.id, 1, Some(&account_cursor)),
            Err(StoreError::InvalidCursor),
        ));

        let changed = MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: "newer-message-2".into(),
            account_id: account.id.clone(),
            conversation_id: cursor_conversation.id.clone(),
            direction: "incoming",
            sender_id: "peer".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: 30,
            received_at: Some(30),
            text: Some("changed after cursor".into()),
            text_bytes: Some(20),
            text_truncated: false,
            text_retrievable: true,

            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        store
            .insert_message(&changed, None, Some("newer-message-2"), false)
            .unwrap();
        let after_change = store
            .list_conversations(&account.id, 1, Some(&account_cursor))
            .unwrap();
        assert_eq!(after_change.items[0].id, remaining_same_time.id);
    }

    #[test]
    fn message_cursor_must_exist_in_the_same_conversation() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "peer", "Peer")
            .unwrap();
        let other_conversation = store
            .ensure_conversation(&account.id, "direct", "other-peer", "Other peer")
            .unwrap();
        let other_message = MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: "other-message".into(),
            account_id: account.id.clone(),
            conversation_id: other_conversation.id.clone(),
            direction: "incoming",
            sender_id: "other-peer".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: 10,
            received_at: Some(10),
            text: Some("other".into()),
            text_bytes: Some(5),
            text_truncated: false,
            text_retrievable: true,

            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        store
            .insert_message(&other_message, None, Some("other-message"), false)
            .unwrap();
        let other_account = store
            .upsert_account_from_signal("+15555550101", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();

        assert!(matches!(
            store.list_messages(&account.id, &conversation.id, 10, Some("unknown-message")),
            Err(StoreError::InvalidCursor),
        ));
        assert!(matches!(
            store.list_messages(&account.id, &conversation.id, 10, Some("other-message")),
            Err(StoreError::InvalidCursor),
        ));
        // Same rule for a self-describing cursor: it is bound to the thread and
        // account that issued it, whatever sort key it claims.
        let other_cursor = encode_message_cursor(&account.id, &other_conversation.id, &{
            let mut record = other_message.clone();
            record.direction = "incoming";
            record
        });
        assert!(matches!(
            store.list_messages(&account.id, &conversation.id, 10, Some(&other_cursor)),
            Err(StoreError::InvalidCursor),
        ));
        assert!(matches!(
            store.list_messages(
                &other_account.id,
                &other_conversation.id,
                10,
                Some(&other_cursor)
            ),
            Err(StoreError::InvalidCursor),
        ));
        assert!(matches!(
            store.list_messages(&account.id, &conversation.id, 10, Some("m1:broken")),
            Err(StoreError::InvalidCursor),
        ));
        assert!(matches!(
            store.list_messages(
                &other_account.id,
                &other_conversation.id,
                10,
                Some("other-message"),
            ),
            Err(StoreError::InvalidCursor),
        ));
    }

    #[test]
    fn search_matches_bodies_across_conversations_newest_first() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let one = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "One")
            .unwrap();
        let two = store
            .ensure_conversation(&account.id, "group", "group-id-1", "Two")
            .unwrap();
        let hit = |id: &str, conversation_id: &str, sent_at: u64, text: &str| {
            let mut message = MessageRecord {
                is_erased: false,
                delete_failed: false,
                required_protocol_version: None,
                author_aci: None,
                id: id.into(),
                account_id: account.id.clone(),
                conversation_id: conversation_id.into(),
                direction: "incoming",
                sender_id: "peer".into(),
                sender_name: None,
                mentions_self: false,
                sent_at,
                received_at: Some(sent_at),
                text: Some(text.into()),
                text_bytes: Some(text.len() as u32),
                text_truncated: false,
                text_retrievable: true,
                status: "delivered",
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments: Vec::new(),
                rich: None,
                edited_at: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                admin_deleted: false,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            };
            if id == "attachment-only" {
                message.text = None;
                message.text_bytes = None;
            }
            store.insert_message(&message, None, None, false).unwrap();
        };
        hit("old", &one.id, 10, "needle in the old thread");
        hit("new", &two.id, 20, "Needle in the new group");
        hit("miss", &one.id, 30, "nothing to see here");
        hit("attachment-only", &one.id, 40, "");
        let ids = store
            .search_messages(&account.id, "needle", 10, None, None)
            .unwrap()
            .items
            .into_iter()
            .map(|row| row.id)
            .collect::<Vec<_>>();
        assert_eq!(ids, ["new", "old"]);
        // Case folding covers ASCII; the empty query matches nothing rather
        // than every row.
        assert_eq!(
            store
                .search_messages(&account.id, "NEEDLE", 10, None, None)
                .unwrap()
                .items
                .len(),
            2
        );
        assert!(
            store
                .search_messages(&account.id, "", 10, None, None)
                .unwrap()
                .items
                .is_empty()
        );
        // Another account's store never leaks rows into the results.
        let other = store
            .upsert_account_from_signal("+15555550101", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert!(
            store
                .search_messages(&other.id, "needle", 10, None, None)
                .unwrap()
                .items
                .is_empty()
        );
    }

    #[test]
    fn search_like_metacharacters_are_literal_and_cursor_pages_are_stable() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        for (index, body) in [
            "100% done",
            "snake_case body",
            "plain body one",
            "plain body two",
        ]
        .into_iter()
        .enumerate()
        {
            let message = MessageRecord {
                is_erased: false,
                delete_failed: false,
                required_protocol_version: None,
                author_aci: None,
                id: format!("row-{index}"),
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                direction: "incoming",
                sender_id: "peer".into(),
                sender_name: None,
                mentions_self: false,
                sent_at: 10 + index as u64,
                received_at: Some(10 + index as u64),
                text: Some(body.into()),
                text_bytes: Some(body.len() as u32),
                text_truncated: false,
                text_retrievable: true,
                status: "delivered",
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments: Vec::new(),
                rich: None,
                edited_at: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                admin_deleted: false,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            };
            store.insert_message(&message, None, None, false).unwrap();
        }
        // % and _ in the query match literally, not as wildcards.
        let ids = |query: &str| -> Vec<String> {
            store
                .search_messages(&account.id, query, 10, None, None)
                .unwrap()
                .items
                .into_iter()
                .map(|row| row.id)
                .collect()
        };
        assert_eq!(ids("0% d"), ["row-0"]);
        assert_eq!(ids("e_case"), ["row-1"]);
        // The query "%" matches the one row containing a percent sign —
        // literally, not as a wildcard over every row.
        assert_eq!(ids("%"), ["row-0"]);
        assert_eq!(ids("_"), ["row-1"]);

        // A cursor pages below its own sort key, so it stays resolvable no
        // matter what later happens to the row it was cut from; a cursor
        // from another account is refused.
        let first_page = store
            .search_messages(&account.id, "plain body", 1, None, None)
            .unwrap();
        assert_eq!(first_page.items.len(), 1);
        let cursor = first_page.next_cursor.unwrap();
        let second_page = store
            .search_messages(&account.id, "plain body", 10, Some(&cursor), None)
            .unwrap();
        assert_eq!(
            second_page
                .items
                .iter()
                .map(|row| row.id.as_str())
                .collect::<Vec<_>>(),
            ["row-2"]
        );
        assert!(second_page.next_cursor.is_none());
        // The cursor carries its own sort key, so re-paging from it is
        // deterministic regardless of what happens to the anchor row.
        let repaged = store
            .search_messages(&account.id, "plain body", 10, Some(&cursor), None)
            .unwrap();
        assert_eq!(repaged.items[0].id, "row-2");
        let other = store
            .upsert_account_from_signal("+15555550101", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert!(matches!(
            store.search_messages(&other.id, "plain body", 10, Some(&cursor), None),
            Err(StoreError::InvalidCursor),
        ));
        assert!(matches!(
            store.search_messages(&account.id, "plain body", 10, Some("m1:bogus"), None),
            Err(StoreError::InvalidCursor),
        ));
    }

    #[test]
    fn search_conversation_scope_filters_and_keeps_the_unscoped_face() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let one = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "One")
            .unwrap();
        let two = store
            .ensure_conversation(&account.id, "group", "group-id-1", "Two")
            .unwrap();
        let hit = |id: &str, conversation_id: &str, sent_at: u64, text: &str| {
            let message = MessageRecord {
                is_erased: false,
                delete_failed: false,
                required_protocol_version: None,
                author_aci: None,
                id: id.into(),
                account_id: account.id.clone(),
                conversation_id: conversation_id.into(),
                direction: "incoming",
                sender_id: "peer".into(),
                sender_name: None,
                mentions_self: false,
                sent_at,
                received_at: Some(sent_at),
                text: Some(text.into()),
                text_bytes: Some(text.len() as u32),
                text_truncated: false,
                text_retrievable: true,
                status: "delivered",
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments: Vec::new(),
                rich: None,
                edited_at: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                admin_deleted: false,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            };
            store.insert_message(&message, None, None, false).unwrap();
        };
        hit("old", &one.id, 10, "needle in the old thread");
        hit("new", &two.id, 20, "Needle in the new group");
        hit("newest", &one.id, 30, "needle again at the top");
        // The scope is a pure filter over the same newest-first ordering:
        // only the named conversation's rows come back, newest first.
        let ids = |conversation_id: Option<&str>| -> Vec<String> {
            store
                .search_messages(&account.id, "needle", 10, None, conversation_id)
                .unwrap()
                .items
                .into_iter()
                .map(|row| row.id)
                .collect()
        };
        assert_eq!(ids(Some(&one.id)), ["newest", "old"]);
        assert_eq!(ids(Some(&two.id)), ["new"]);
        // The key absent keeps the account-wide face: the same call without
        // the scope still spans conversations (the pre-1.162 contract).
        assert_eq!(ids(None), ["newest", "new", "old"]);
        // A scoped page's cursor stays the account-bound sort-key format, so
        // it keeps resolving inside the scope it was minted for — and the
        // same sort key replayed unscoped (or the other way) stays a valid
        // resume point over the same global ordering, never an error.
        let first_page = store
            .search_messages(&account.id, "needle", 1, None, Some(&one.id))
            .unwrap();
        assert_eq!(first_page.items[0].id, "newest");
        let cursor = first_page.next_cursor.unwrap();
        let scoped_second = store
            .search_messages(&account.id, "needle", 10, Some(&cursor), Some(&one.id))
            .unwrap();
        assert_eq!(
            scoped_second
                .items
                .iter()
                .map(|row| row.id.as_str())
                .collect::<Vec<_>>(),
            ["old"]
        );
        let unscoped_resume = store
            .search_messages(&account.id, "needle", 10, Some(&cursor), None)
            .unwrap();
        assert_eq!(
            unscoped_resume
                .items
                .iter()
                .map(|row| row.id.as_str())
                .collect::<Vec<_>>(),
            ["new", "old"]
        );
    }

    /// §4.263: the startup sweep prunes payloads past the 30-day retention and
    /// older-than-grace orphans with no message row, while a fresh row and a
    /// row still backed by its message survive a reopen.
    #[test]
    fn outgoing_attachment_payloads_prune_expired_and_orphaned_rows_on_open() {
        const DATA_URI: &str = "data:text/plain;base64,YXR0YWNobWVudCBieXRlcw==";
        let temp = TempDir::new().unwrap();
        let now = crate::link::now_ms();
        let account_id = {
            let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
            let account = store
                .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
                .unwrap();
            let conversation = store
                .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
                .unwrap();
            let message = pin_test_message(&account.id, &conversation.id, "m-payload", 10);
            store
                .insert_message(&message, Some("req-kept"), Some("body"), false)
                .unwrap();
            for client_request_id in ["req-fresh", "req-expired", "req-orphan", "req-kept"] {
                store
                    .remember_outgoing_attachment_payload(
                        &account.id,
                        &conversation.id,
                        client_request_id,
                        0,
                        DATA_URI,
                        now,
                    )
                    .unwrap();
            }
            let expired = now.saturating_sub(31 * 24 * 60 * 60 * 1_000);
            let orphan = now.saturating_sub(2 * 60 * 60 * 1_000);
            store
                .conn()
                .execute(
                    "UPDATE outgoing_attachment_payloads SET updated_at=?1
                      WHERE client_request_id IN ('req-expired', 'req-orphan')",
                    params![expired as i64],
                )
                .unwrap();
            store
                .conn()
                .execute(
                    "UPDATE outgoing_attachment_payloads SET updated_at=?1
                      WHERE client_request_id='req-kept'",
                    params![orphan as i64],
                )
                .unwrap();
            account.id
        };
        // A new store instance runs the startup sweep before serving.
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        assert_eq!(
            store
                .outgoing_attachment_payload(&account_id, "req-fresh", 0)
                .unwrap()
                .as_deref(),
            Some(DATA_URI),
            "a fresh payload survives the startup sweep"
        );
        assert_eq!(
            store
                .outgoing_attachment_payload(&account_id, "req-expired", 0)
                .unwrap(),
            None,
            "a payload past the retention window is pruned"
        );
        assert_eq!(
            store
                .outgoing_attachment_payload(&account_id, "req-orphan", 0)
                .unwrap(),
            None,
            "an orphan past the grace window is pruned"
        );
        assert_eq!(
            store
                .outgoing_attachment_payload(&account_id, "req-kept", 0)
                .unwrap()
                .as_deref(),
            Some(DATA_URI),
            "a payload still backed by its message row survives"
        );
    }

    /// 契约 1.280（§4.264）：payload 的主键以账号开头。两个账号可以用同一个
    /// clientRequestId，各自首发都必须写进去、各自都能读回自己的字节；覆盖、
    /// 删除也只动自己那一组。
    #[test]
    fn outgoing_attachment_payloads_are_scoped_to_their_own_account() {
        const SHARED_ID: &str = "req-shared-client-request";
        const FIRST_URI_0: &str = "data:text/plain;filename=first-0.txt;base64,YQ==";
        const FIRST_URI_1: &str = "data:text/plain;filename=first-1.txt;base64,YTE=";
        const SECOND_URI_0: &str = "data:text/plain;filename=second-0.txt;base64,Yg==";
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let first = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let second = store
            .upsert_account_from_signal("+15555550101", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let first_conversation = store
            .ensure_conversation(&first.id, "direct", "+15555550111", "First peer")
            .unwrap();
        let second_conversation = store
            .ensure_conversation(&second.id, "direct", "+15555550112", "Second peer")
            .unwrap();
        let now = crate::link::now_ms();
        // Two desktops picking the same idempotency key is legal: the payload
        // rows belong to their account, not to the id alone.
        store
            .remember_outgoing_attachment_payloads(
                &first.id,
                &first_conversation.id,
                SHARED_ID,
                &[(0, FIRST_URI_0), (1, FIRST_URI_1)],
                now,
            )
            .unwrap();
        store
            .remember_outgoing_attachment_payload(
                &second.id,
                &second_conversation.id,
                SHARED_ID,
                0,
                SECOND_URI_0,
                now,
            )
            .unwrap();
        assert_eq!(
            store
                .outgoing_attachment_payloads(&first.id, SHARED_ID)
                .unwrap(),
            vec![(0, FIRST_URI_0.to_string()), (1, FIRST_URI_1.to_string())],
            "the first account keeps its whole group"
        );
        assert_eq!(
            store
                .outgoing_attachment_payloads(&second.id, SHARED_ID)
                .unwrap(),
            vec![(0, SECOND_URI_0.to_string())],
            "the second account's first send is not swallowed by the first account's key"
        );
        assert_eq!(
            store
                .outgoing_attachment_payload(&first.id, SHARED_ID, 0)
                .unwrap()
                .as_deref(),
            Some(FIRST_URI_0),
            "single-index reads are account-scoped too"
        );
        // The idempotent-replay discipline is per account: an index the first
        // account already holds is still writable for the second.
        store
            .remember_outgoing_attachment_payload(
                &second.id,
                &second_conversation.id,
                SHARED_ID,
                1,
                SECOND_URI_0,
                now,
            )
            .unwrap();
        assert_eq!(
            store
                .outgoing_attachment_payloads(&second.id, SHARED_ID)
                .unwrap()
                .len(),
            2
        );
        // A rewrite through one account never rewrites the other's row.
        store
            .update_outgoing_attachment_payload(
                &second.id,
                &second_conversation.id,
                SHARED_ID,
                0,
                SECOND_URI_0,
                now + 1,
            )
            .unwrap();
        assert_eq!(
            store
                .outgoing_attachment_payload(&first.id, SHARED_ID, 0)
                .unwrap()
                .as_deref(),
            Some(FIRST_URI_0),
            "the other account's bytes are untouched"
        );
        // A group delete scoped to one account leaves the other intact.
        assert_eq!(
            store
                .delete_outgoing_attachment_payloads(&second.id, SHARED_ID)
                .unwrap(),
            2
        );
        assert!(
            store
                .outgoing_attachment_payloads(&second.id, SHARED_ID)
                .unwrap()
                .is_empty()
        );
        assert_eq!(
            store
                .outgoing_attachment_payloads(&first.id, SHARED_ID)
                .unwrap()
                .len(),
            2,
            "the surviving account keeps its group"
        );
    }

