    /// Contract 1.181 (§4.181): the groups-in-common scan resolves the
    /// contact through the whole identity ladder — the peer key's two phone
    /// spellings, the ACI the identity table holds for either, and the
    /// reverse peer keys when the key itself is ACI-shaped — matches roster
    /// id and uuid entries, skips malformed rosters, title-sorts like the
    /// official panel, and answers an honest empty set for a stranger.
    #[test]
    fn groups_in_common_matches_the_identity_ladder_and_sorts_by_title() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        // The contact's ACI, observed under the bare-digit phone spelling.
        store
            .upsert_peer_identity(
                &account.id,
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "15555550101",
            )
            .unwrap();
        store
            .upsert_contact(
                &account.id,
                "group",
                "Z3JvdXAtYmV0YQ",
                "Beta Group",
                Some(r#"{"memberCount":2,"members":[{"id":"0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10"}]}"#),
                1725300000,
            )
            .unwrap();
        store
            .upsert_contact(
                &account.id,
                "group",
                "Z3JvdXAtYWxwaGE",
                "Alpha Group",
                Some(r#"{"memberCount":2,"members":[{"id":"+15555550999","uuid":"0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10"}]}"#),
                1725300000,
            )
            .unwrap();
        store
            .upsert_contact(
                &account.id,
                "group",
                "Z3JvdXAtb3RoZXI",
                "Other Group",
                Some(r#"{"memberCount":1,"members":[{"id":"+15555550777"}]}"#),
                1725300000,
            )
            .unwrap();
        // A malformed extra never fails the scan (the hostile-roster
        // discipline); a group without a roster cannot match.
        store
            .upsert_contact(
                &account.id,
                "group",
                "Z3JvdXAtYmFk",
                "Bad JSON",
                Some("not-json"),
                1725300000,
            )
            .unwrap();
        store
            .upsert_contact(
                &account.id,
                "group",
                "Z3JvdXAtcGxhaW4",
                "No Roster",
                None,
                1725300000,
            )
            .unwrap();
        // Contact-kind rows never join the scan.
        store
            .upsert_contact(
                &account.id,
                "contact",
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "The Contact",
                None,
                1725300000,
            )
            .unwrap();

        let expected = vec![
            CommonGroupRow {
                peer_key: "Z3JvdXAtYWxwaGE".into(),
                title: "Alpha Group".into(),
            },
            CommonGroupRow {
                peer_key: "Z3JvdXAtYmV0YQ".into(),
                title: "Beta Group".into(),
            },
        ];
        // The plus-spelled conversation key reaches the ACI-keyed roster id
        // and the uuid-keyed entry through the identity table.
        assert_eq!(
            store.groups_in_common(&account.id, "+15555550101").unwrap(),
            expected
        );
        // The bare spelling answers the same set.
        assert_eq!(
            store.groups_in_common(&account.id, "15555550101").unwrap(),
            expected
        );
        // The ACI-shaped key resolves through the reverse ladder to the same
        // two groups.
        assert_eq!(
            store
                .groups_in_common(&account.id, "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10")
                .unwrap(),
            expected
        );
        // A stranger answers the honest empty set.
        assert!(
            store
                .groups_in_common(&account.id, "+15555550333")
                .unwrap()
                .is_empty()
        );
        // Another account's cache is disjoint.
        assert!(
            store
                .groups_in_common("no-such-account", "+15555550101")
                .unwrap()
                .is_empty()
        );
    }

    /// Contract 1.38 (§4.37): the candidate ladder ranks incoming rows whose
    /// conversation matches a candidate peer key ahead of outgoing rows at
    /// the same timestamp, skips rows without a rich record, and ignores
    /// conversations outside the candidate set. An empty candidate set is
    /// answered without touching the database.
    #[test]
    fn view_once_open_candidates_rank_incoming_first() {
        use crate::engine::NormalizedRich;
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let peer = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let stranger = store
            .ensure_conversation(&account.id, "direct", "+15555550999", "contact")
            .unwrap();
        let base =
            |id: &str, conversation_id: &str, direction: &'static str, rich: bool| MessageRecord {
                is_erased: false,
                delete_failed: false,
                required_protocol_version: None,
                author_aci: None,
                id: id.into(),
                account_id: account.id.clone(),
                conversation_id: conversation_id.into(),
                direction,
                sender_id: if direction == "outgoing" {
                    "self".into()
                } else {
                    "peer".into()
                },
                sender_name: None,
                mentions_self: false,
                sent_at: 99,
                received_at: None,
                text: Some("burn me".into()),
                text_bytes: Some(7),
                text_truncated: false,
                text_retrievable: true,
                status: "delivered",
                client_request_id: None,
                quote_message_id: None,
                quote_snapshot: None,
                quote: None,
                attachments: Vec::new(),
                rich: rich.then_some(NormalizedRich {
                    view_once: true,
                    ..NormalizedRich::default()
                }),
                edited_at: None,
                reactions: Vec::new(),
                edits: Vec::new(),
                delivered_at: None,
                read_at: None,
                viewed_at: None,
                send_outcomes: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                admin_deleted: false,
                server_guid: None,
                server_timestamp: None,
                is_story: false,
                story_message: None,
            };
        for record in [
            base("m-incoming", &peer.id, "incoming", true),
            // Gets a non-marker rich_json from the UPDATE below: the caller's
            // marker filter must skip it even though the query surfaces it.
            base("m-plain-rich", &peer.id, "incoming", true),
            base("m-no-rich", &peer.id, "incoming", false),
            base("m-outgoing", &peer.id, "outgoing", true),
            base("m-stranger", &stranger.id, "incoming", true),
        ] {
            store
                .insert_message(&record, None, Some("burn me"), true)
                .unwrap();
        }
        // The non-view-once rich row: same shape, no marker — the caller's
        // filter (first candidate carrying the marker) must not select it.
        store
            .lock_conn()
            .unwrap()
            .execute(
                "UPDATE messages SET rich_json='{\"previews\":[]}' WHERE id='m-plain-rich'",
                [],
            )
            .unwrap();

        let candidates = store
            .view_once_open_candidates(
                &account.id,
                99,
                &["+15555550101".to_string(), "aci-peer".to_string()],
            )
            .unwrap();
        // Incoming rows first (id order), then the outgoing row. The
        // non-marker rich row and the rich-less row both surface here —
        // the marker filter is the caller's job (`apply_view_once_open_sync`
        // takes the first candidate carrying `viewOnce`/`viewOnceInvalid`),
        // and the stranger conversation's row never enters the scan.
        let ids: Vec<&str> = candidates.iter().map(|record| record.id.as_str()).collect();
        assert_eq!(ids, vec!["m-incoming", "m-plain-rich", "m-outgoing"]);

        // A candidate set that matches nothing (wrong timestamp, wrong keys)
        // and the empty set both answer empty.
        assert!(
            store
                .view_once_open_candidates(&account.id, 98, &["+15555550101".to_string()])
                .unwrap()
                .is_empty()
        );
        assert!(
            store
                .view_once_open_candidates(&account.id, 99, &[])
                .unwrap()
                .is_empty()
        );
    }

    /// Contract 1.38 (§4.37): the first burn clears the body bytes, stamps
    /// `openedAt` onto the rich record, and keeps the renderable metadata;
    /// a replay rewrites nothing and reports `changed=false` — exactly-one
    /// event and fan-out are the caller's contract, this is its foundation.
    #[test]
    fn burn_view_once_message_transitions_once_and_keeps_metadata() {
        use crate::engine::{NormalizedAttachment, NormalizedRich};
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let peer = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let record = MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: "m-view".into(),
            account_id: account.id.clone(),
            conversation_id: peer.id.clone(),
            direction: "incoming",
            sender_id: "peer".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: 99,
            received_at: None,
            text: Some("self-destructing".into()),
            text_bytes: Some(16),
            text_truncated: false,
            text_retrievable: true,
            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: vec![NormalizedAttachment {
                id: "att-view-1".into(),
                content_type: Some("image/jpeg".into()),
                filename: Some("snap.jpg".into()),
                size: Some(2048),
                width: Some(64),
                height: Some(32),
                is_voice_note: false,
                caption: None,
                blur_hash: None,
                incremental_mac: None,
                chunk_size: None,
                is_borderless: false,
                is_gif: false,
                locator: None,
                waveform: None,
                duration: None,
            }],
            rich: Some(NormalizedRich {
                view_once: true,
                ..NormalizedRich::default()
            }),
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        store
            .insert_message(&record, None, Some("self-destructing"), true)
            .unwrap();

        let (burned, changed) = store
            .burn_view_once_message(&account.id, &peer.id, "m-view", 12345)
            .unwrap()
            .expect("the row exists");
        assert!(changed);
        assert!(burned.text.is_none());
        assert_eq!(burned.text_bytes, None);
        assert_eq!(burned.attachments.len(), 1);
        assert_eq!(burned.attachments[0].id, "att-view-1");
        let rich = burned.rich.expect("rich survives the burn");
        assert_eq!(rich.view_once_opened_at, Some(12345));
        assert!(rich.view_once);

        let (replayed, changed) = store
            .burn_view_once_message(&account.id, &peer.id, "m-view", 99999)
            .unwrap()
            .expect("the row still exists");
        assert!(!changed);
        let rich = replayed.rich.expect("rich survives the replay");
        assert_eq!(rich.view_once_opened_at, Some(12345));
        assert_eq!(replayed.text, None);

        // A missing row answers None both for the burn and for its replay.
        assert!(
            store
                .burn_view_once_message(&account.id, &peer.id, "m-absent", 1)
                .unwrap()
                .is_none()
        );
    }

