    /// The live locator column round-trips (contract revision 1.61, §4.54):
    /// a receive envelope's transit faces land index-aligned beside the
    /// descriptors, a metadata-only envelope lands the all-None faces, and
    /// both read back through `live_attachment_locators` — the wire
    /// descriptor stays byte-identical either way.
    #[test]
    fn live_locator_column_round_trips_index_aligned() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550105", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550106", "Peer")
            .unwrap();
        let descriptor = |id: &str, locator: Option<crate::store::HistoryAttachmentLocator>| {
            crate::engine::NormalizedAttachment {
                id: id.into(),
                content_type: Some("image/jpeg".into()),
                filename: None,
                size: Some(2048),
                width: None,
                height: None,
                is_voice_note: false,
                caption: None,
                blur_hash: None,
                incremental_mac: None,
                chunk_size: None,
                is_borderless: false,
                is_gif: false,
                locator,
                waveform: None,
                duration: None,
            }
        };
        let full_face = crate::store::HistoryAttachmentLocator {
            key: Some("a2F0LWtleQ==".into()),
            cdn_key: Some("live-key".into()),
            cdn_number: Some(3),
            upload_timestamp: Some(1700000000000),
            digest: Some("ZGl-nonsense".into()),
            plaintext_hash: Some("aabb".into()),
        };
        let mut with_face = expire_record("m-loc", &account.id, &conversation.id);
        with_face.attachments = vec![
            descriptor("att-a", Some(full_face.clone())),
            // The hole stays index-aligned: a metadata-only sibling keeps its
            // own all-None face instead of shifting the row.
            descriptor("att-b", None),
        ];
        store
            .insert_message(&with_face, None, Some("face"), true)
            .unwrap();
        let faces = store
            .live_attachment_locators(&account.id, "m-loc")
            .unwrap();
        assert_eq!(faces.len(), 2);
        assert_eq!(faces[0], full_face);
        assert_eq!(faces[1], crate::store::HistoryAttachmentLocator::default());

        let plain = expire_record("m-plain", &account.id, &conversation.id);
        store
            .insert_message(&plain, None, Some("plain"), true)
            .unwrap();
        assert!(
            store
                .live_attachment_locators(&account.id, "m-plain")
                .unwrap()
                .is_empty()
        );
    }

    /// merge_live_attachment_locators (contract revision 1.175, §4.175): the
    /// merge fills only empty slots — the optimistic outgoing row / the
    /// backfill response both land their pointer faces through this
    /// primitive. First face wins (an existing non-default slot is never
    /// overwritten); a longer new face extends the column index-aligned; an
    /// all-default new face and an absent row both answer `Ok(false)`.
    #[test]
    fn merge_live_attachment_locators_fills_only_empty_slots() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550105", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550106", "Peer")
            .unwrap();
        let descriptor = |id: &str, locator: Option<crate::store::HistoryAttachmentLocator>| {
            crate::engine::NormalizedAttachment {
                id: id.into(),
                content_type: Some("image/jpeg".into()),
                filename: None,
                size: Some(2048),
                width: None,
                height: None,
                is_voice_note: false,
                caption: None,
                blur_hash: None,
                incremental_mac: None,
                chunk_size: None,
                is_borderless: false,
                is_gif: false,
                locator,
                waveform: None,
                duration: None,
            }
        };
        let face = |cdn: &str| crate::store::HistoryAttachmentLocator {
            key: Some("a2F0LWtleQ==".into()),
            cdn_key: Some(cdn.into()),
            cdn_number: Some(3),
            upload_timestamp: Some(1700000000000),
            digest: Some("ZGl-nonsense".into()),
            plaintext_hash: None,
        };
        // The pre-echo outgoing row: descriptors without locators.
        let mut row = expire_record("m-merge", &account.id, &conversation.id);
        row.direction = "outgoing";
        row.attachments = vec![descriptor("att-a", None), descriptor("att-b", None)];
        store
            .insert_message(&row, None, Some("merge"), false)
            .unwrap();
        // The insert stored the all-default faces index-aligned (the 1.61
        // write discipline) — every slot is an empty hole waiting to fill.
        let initial = store
            .live_attachment_locators(&account.id, "m-merge")
            .unwrap();
        assert_eq!(initial.len(), 2);
        assert!(
            initial
                .iter()
                .all(|face| face == &crate::store::HistoryAttachmentLocator::default())
        );

        // The echo/backfill merge: index 0 lands, index 1 stays a hole for
        // now; a longer face extends the column.
        let changed = store
            .merge_live_attachment_locators(
                &account.id,
                "m-merge",
                &[Some(face("cdn-a")), None, Some(face("cdn-c"))],
            )
            .unwrap();
        assert!(changed);
        let faces = store
            .live_attachment_locators(&account.id, "m-merge")
            .unwrap();
        assert_eq!(faces.len(), 3);
        assert_eq!(faces[0], face("cdn-a"));
        assert_eq!(faces[1], crate::store::HistoryAttachmentLocator::default());
        assert_eq!(faces[2], face("cdn-c"));

        // First face wins: a second merge with a different face for index 0
        // changes nothing.
        let changed = store
            .merge_live_attachment_locators(
                &account.id,
                "m-merge",
                &[Some(face("cdn-OTHER")), Some(face("cdn-b"))],
            )
            .unwrap();
        assert!(changed, "index 1's empty slot still fills");
        let faces = store
            .live_attachment_locators(&account.id, "m-merge")
            .unwrap();
        assert_eq!(faces[0], face("cdn-a"), "existing slot never moves");
        assert_eq!(faces[1], face("cdn-b"));

        // All-default new face: quiet no-op.
        let changed = store
            .merge_live_attachment_locators(&account.id, "m-merge", &[None, None])
            .unwrap();
        assert!(!changed);

        // Absent row: quiet no-op.
        let changed = store
            .merge_live_attachment_locators(&account.id, "m-absent", &[Some(face("cdn-x"))])
            .unwrap();
        assert!(!changed);
    }

    /// Post-relink descriptor repair: a row restored from the text-only
    /// backup artifact carries no `attachments_json`; a later live echo /
    /// re-run with the same Signal identity must fill the descriptor and its
    /// locator instead of being swallowed by the identity dedupe. Both the
    /// public merge and the duplicate `insert_message` arm converge on the
    /// same empty-position-only write.
    #[test]
    fn duplicate_insert_and_merge_repair_missing_attachment_descriptors() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550107", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550108", "Peer")
            .unwrap();
        let face = crate::store::HistoryAttachmentLocator {
            key: Some("a2F0LWtleQ==".into()),
            cdn_key: Some("cdn-repair".into()),
            cdn_number: Some(3),
            upload_timestamp: Some(1_700_000_000_000),
            digest: Some("ZGl-nonsense".into()),
            plaintext_hash: None,
        };
        let descriptor = |id: &str| crate::engine::NormalizedAttachment {
            id: id.into(),
            content_type: Some("image/jpeg".into()),
            filename: Some("restored.jpg".into()),
            size: Some(2048),
            width: None,
            height: None,
            is_voice_note: false,
            caption: None,
            blur_hash: None,
            incremental_mac: None,
            chunk_size: None,
            is_borderless: false,
            is_gif: false,
            locator: Some(face.clone()),
            waveform: None,
            duration: None,
        };

        // The public merge fills an empty row.
        let mut restored = expire_record("m-repair", &account.id, &conversation.id);
        restored.attachments = Vec::new();
        store
            .insert_message(&restored, None, Some("restored"), true)
            .unwrap();
        assert!(
            store
                .merge_live_attachment_faces(&account.id, "m-repair", &[descriptor("att-live")])
                .unwrap()
        );
        let stored = store
            .message_by_id(&account.id, &conversation.id, "m-repair")
            .unwrap()
            .unwrap();
        assert_eq!(stored.attachments.len(), 1);
        assert_eq!(stored.attachments[0].id, "att-live");
        let faces = store
            .live_attachment_locators(&account.id, "m-repair")
            .unwrap();
        assert_eq!(faces.len(), 1);
        assert_eq!(faces[0], face);
        // First face wins: a second repair never moves the stored descriptor.
        assert!(
            !store
                .merge_live_attachment_faces(&account.id, "m-repair", &[descriptor("att-other")])
                .unwrap()
        );
        let stored = store
            .message_by_id(&account.id, &conversation.id, "m-repair")
            .unwrap()
            .unwrap();
        assert_eq!(stored.attachments[0].id, "att-live");

        // The duplicate `insert_message` arm performs the same repair.
        let mut duplicate = expire_record("m-repair-insert", &account.id, &conversation.id);
        duplicate.attachments = Vec::new();
        store
            .insert_message(&duplicate, None, Some("plain"), true)
            .unwrap();
        duplicate.attachments = vec![descriptor("att-echo")];
        assert!(!store.insert_message(&duplicate, None, None, true).unwrap());
        let stored = store
            .message_by_id(&account.id, &conversation.id, "m-repair-insert")
            .unwrap()
            .unwrap();
        assert_eq!(stored.attachments.len(), 1);
        assert_eq!(stored.attachments[0].id, "att-echo");
        let faces = store
            .live_attachment_locators(&account.id, "m-repair-insert")
            .unwrap();
        assert_eq!(faces.len(), 1);
        assert_eq!(faces[0], face);
    }

    /// `remove_message_attachment_at` (contract 1.196, §4.196): the
    /// official single-attachment delete mirror — the descriptor leaves and
    /// the same index leaves both locator columns, so surviving slots never
    /// shift onto a neighbour. An absent row, an index past the end, and a
    /// row with no descriptors answer `None` without writing.
    #[test]
    fn remove_message_attachment_at_strips_descriptor_and_aligned_locators() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550105", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550106", "Peer")
            .unwrap();
        let descriptor = |id: &str, locator: Option<HistoryAttachmentLocator>| {
            crate::engine::NormalizedAttachment {
                id: id.into(),
                content_type: Some("image/jpeg".into()),
                filename: None,
                size: Some(2048),
                width: None,
                height: None,
                is_voice_note: false,
                caption: None,
                blur_hash: None,
                incremental_mac: None,
                chunk_size: None,
                is_borderless: false,
                is_gif: false,
                locator,
                waveform: None,
                duration: None,
            }
        };
        let face = |digest: &str, hash: &str| HistoryAttachmentLocator {
            key: Some("a2F0LWtleQ==".into()),
            cdn_key: Some(format!("cdn-{digest}")),
            cdn_number: Some(3),
            upload_timestamp: Some(1700000000000),
            digest: Some(digest.into()),
            plaintext_hash: Some(hash.into()),
        };
        let mut row = expire_record("m-strip", &account.id, &conversation.id);
        row.attachments = vec![
            descriptor("att-a", Some(face("digest-a", "aa"))),
            descriptor("att-b", Some(face("digest-b", "bb"))),
            descriptor("att-c", Some(face("digest-c", "cc"))),
        ];
        store
            .insert_message(&row, None, Some("strip"), true)
            .unwrap();
        // Seed the history-import column too: the removal must keep both
        // index-aligned columns in step (they are separate columns because
        // the history import and the live receive write different faces).
        let history_faces = vec![
            face("digest-a", "aa"),
            face("digest-b", "bb"),
            face("digest-c", "cc"),
        ];
        store
            .conn()
            .execute(
                "UPDATE messages SET attachment_locators=?3 WHERE account_id=?1 AND id=?2",
                params![
                    account.id,
                    "m-strip",
                    serde_json::to_string(&history_faces).unwrap()
                ],
            )
            .unwrap();

        assert_eq!(
            store
                .remove_message_attachment_at(&account.id, "m-strip", 1)
                .unwrap()
                .as_deref(),
            Some("att-b")
        );
        let record = store
            .message_by_id(&account.id, &conversation.id, "m-strip")
            .unwrap()
            .expect("the message row survives an attachment delete");
        assert_eq!(
            record
                .attachments
                .iter()
                .map(|attachment| attachment.id.as_str())
                .collect::<Vec<_>>(),
            vec!["att-a", "att-c"]
        );
        let live = store
            .live_attachment_locators(&account.id, "m-strip")
            .unwrap();
        assert_eq!(live.len(), 2);
        assert_eq!(live[0].digest.as_deref(), Some("digest-a"));
        assert_eq!(live[1].digest.as_deref(), Some("digest-c"));
        let history = store
            .history_attachment_locators(&account.id, "m-strip")
            .unwrap();
        assert_eq!(history.len(), 2);
        assert_eq!(history[0].digest.as_deref(), Some("digest-a"));
        assert_eq!(history[1].digest.as_deref(), Some("digest-c"));

        // Out-of-range, absent row, and a descriptor-less row are quiet
        // misses: nothing is written.
        assert!(
            store
                .remove_message_attachment_at(&account.id, "m-strip", 9)
                .unwrap()
                .is_none()
        );
        assert!(
            store
                .remove_message_attachment_at(&account.id, "m-absent", 0)
                .unwrap()
                .is_none()
        );
        let mut plain = expire_record("m-plain-strip", &account.id, &conversation.id);
        plain.attachments = Vec::new();
        store
            .insert_message(&plain, None, Some("plain"), true)
            .unwrap();
        assert!(
            store
                .remove_message_attachment_at(&account.id, "m-plain-strip", 0)
                .unwrap()
                .is_none()
        );
    }

    /// serverGuid round-trip (contract revision 1.49, §4.48): a live receive
    /// row persists the envelope's serverGuid, and `server_guids_by_ids`
    /// answers a 1:1 list — the recorded guid for the row, None for missing
    /// rows and None for guid-less rows.
    #[test]
    fn server_guid_round_trip_and_lookup() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550101", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550102", "Peer")
            .unwrap();
        let mut with_guid = expire_record("m1", &account.id, &conversation.id);
        with_guid.server_guid = Some("guid-one".to_string());
        store.insert_message(&with_guid, None, None, true).unwrap();
        let without_guid = expire_record("m2", &account.id, &conversation.id);
        store
            .insert_message(&without_guid, None, None, true)
            .unwrap();

        let fetched = store
            .message_by_id(&account.id, &conversation.id, "m1")
            .unwrap()
            .unwrap();
        assert_eq!(fetched.server_guid.as_deref(), Some("guid-one"));
        let plain = store
            .message_by_id(&account.id, &conversation.id, "m2")
            .unwrap()
            .unwrap();
        assert_eq!(plain.server_guid, None);

        let guids = store
            .server_guids_by_ids(
                &account.id,
                &conversation.id,
                &["m1".into(), "missing".into(), "m2".into()],
            )
            .unwrap();
        assert_eq!(guids, vec![Some("guid-one".to_string()), None, None]);
    }

    /// Schema v22 (contract revision 1.128, §4.109): the
    /// `server_timestamp` column upgrades in place from a pre-1.128 store,
    /// pre-existing rows stay NULL (never backfilled), and a stamped row
    /// round-trips through insert + read with the value verbatim.
    #[test]
    fn schema_v22_upgrade_adds_server_timestamp_column() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("connector.sqlite3");
        let conn = Connection::open(&path).unwrap();
        conn.execute_batch(
            "CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
             INSERT INTO meta(key, value) VALUES('schema_version', '21');
             CREATE TABLE accounts (
               id TEXT PRIMARY KEY,
               signal_account TEXT NOT NULL UNIQUE,
               masked_address TEXT NOT NULL,
               display_name TEXT,
               state TEXT NOT NULL,
               linked_at INTEGER,
               last_message_at INTEGER,
               unread_count INTEGER NOT NULL DEFAULT 0,
               proxy_group TEXT NOT NULL DEFAULT 'default'
             );
             CREATE TABLE conversations (
               id TEXT PRIMARY KEY,
               account_id TEXT NOT NULL,
               kind TEXT NOT NULL,
               peer_key TEXT NOT NULL,
               title TEXT NOT NULL,
               last_message_preview TEXT,
               last_message_at INTEGER,
               unread_count INTEGER NOT NULL DEFAULT 0,
               unread_mentions INTEGER NOT NULL DEFAULT 0,
               muted INTEGER NOT NULL DEFAULT 0,
               pinned INTEGER NOT NULL DEFAULT 0,
               expire_timer_seconds INTEGER,
               UNIQUE(account_id, kind, peer_key),
               FOREIGN KEY(account_id) REFERENCES accounts(id)
             );
             CREATE TABLE history_import_stage_chats (
               account_id TEXT NOT NULL,
               id INTEGER NOT NULL,
               recipient_id INTEGER NOT NULL,
               expire_timer_ms INTEGER,
               PRIMARY KEY(account_id, id),
               FOREIGN KEY(account_id) REFERENCES accounts(id) ON DELETE CASCADE
             );
             CREATE TABLE messages (
               id TEXT PRIMARY KEY,
               account_id TEXT NOT NULL,
               conversation_id TEXT NOT NULL,
               direction TEXT NOT NULL,
               sender_id TEXT NOT NULL,
               sent_at INTEGER NOT NULL,
               received_at INTEGER,
               stored_at INTEGER,
               body TEXT,
               body_bytes INTEGER,
               body_truncated INTEGER NOT NULL DEFAULT 0,
               status TEXT NOT NULL,
               client_request_id TEXT,
               quote_message_id TEXT,
               quote_snapshot TEXT,
               attachments_json TEXT,
               rich_json TEXT,
               sticker_json TEXT,
               edited_at INTEGER,
               sender_name TEXT,
               mentions_self INTEGER NOT NULL DEFAULT 0,
               delivered_at INTEGER,
               read_at INTEGER,
               viewed_at INTEGER,
               admin_deleted INTEGER NOT NULL DEFAULT 0,
               expire_seconds INTEGER,
               expire_start_at INTEGER,
               expire_at INTEGER,
               server_guid TEXT
             );",
        )
        .unwrap();
        drop(conn);

        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        assert!(table_has_column(&store.conn(), "messages", "server_timestamp").unwrap());
        let version: i64 = store
            .conn()
            .query_row(
                "SELECT CAST(value AS INTEGER) FROM meta WHERE key='schema_version'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(version, SCHEMA_VERSION);
    }

    /// The server-time key (contract revision 1.128, §4.109): a receive
    /// envelope's `serverTimestamp` lands on the row verbatim and reads back
    /// through the projection; a row without the key reads NULL — never
    /// backfilled, never invented.
    #[test]
    fn server_timestamp_round_trips() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550101", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550102", "Peer")
            .unwrap();
        let mut stamped = expire_record("m1", &account.id, &conversation.id);
        stamped.server_timestamp = Some(1_700_000_004_321);
        store.insert_message(&stamped, None, None, true).unwrap();
        let plain = expire_record("m2", &account.id, &conversation.id);
        store.insert_message(&plain, None, None, true).unwrap();

        let fetched = store
            .message_by_id(&account.id, &conversation.id, "m1")
            .unwrap()
            .unwrap();
        assert_eq!(fetched.server_timestamp, Some(1_700_000_004_321));
        let unstamped = store
            .message_by_id(&account.id, &conversation.id, "m2")
            .unwrap()
            .unwrap();
        assert_eq!(unstamped.server_timestamp, None);
    }

    /// The sweep deadline picks the honest countdown start — the engine's
    /// start stamp when stated, else the receive time, else the store's own
    /// insert clock — and rows without a live timer never get one.
    #[test]
    fn expire_deadline_forms() {
        let mut record = expire_record("m1", "a", "c");
        let due = |record: &MessageRecord| expire_deadline(record, 1_000);
        assert_eq!(due(&record), None);
        record.expire_seconds = Some(0);
        assert_eq!(due(&record), None);

        record.expire_seconds = Some(60);
        record.expire_start_at = Some(500);
        assert_eq!(due(&record), Some(60_500));

        record.expire_start_at = None;
        record.received_at = Some(2_000);
        assert_eq!(due(&record), Some(62_000));

        record.received_at = None;
        assert_eq!(due(&record), Some(61_000));
    }

    /// Expire fields round-trip through the row: the stored keys read back
    /// verbatim, the sweep deadline is written at insert from the store clock
    /// when the timer is live, and rows without a timer keep every expire
    /// column NULL so the sweeper never sees them.
    #[test]
    fn expire_fields_round_trip_and_stamp_the_deadline() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();

        let mut live = expire_record("m-live", &account.id, &conversation.id);
        live.expire_seconds = Some(60);
        live.expire_start_at = Some(500);
        assert!(
            store
                .insert_message(&live, None, Some("vanishing"), true)
                .unwrap()
        );

        let mut stated_off = expire_record("m-off", &account.id, &conversation.id);
        stated_off.expire_seconds = Some(0);
        assert!(
            store
                .insert_message(&stated_off, None, None, false)
                .unwrap()
        );

        let page = store
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap();
        assert_eq!(page.items.len(), 2);
        let read_live = page
            .items
            .iter()
            .find(|row| row.id == "m-live")
            .expect("live row");
        assert_eq!(read_live.expire_seconds, Some(60));
        assert_eq!(read_live.expire_start_at, Some(500));
        let read_off = page
            .items
            .iter()
            .find(|row| row.id == "m-off")
            .expect("off row");
        assert_eq!(read_off.expire_seconds, Some(0));
        assert_eq!(read_off.expire_start_at, None);

        let observer = keyed_observer(&store);
        // The deadline derives from the engine-stated start (500 + 60s), not
        // from the store clock.
        let live_expire_at: Option<i64> = observer
            .query_row(
                "SELECT expire_at FROM messages WHERE id='m-live'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(live_expire_at, Some(60_500));
        let (off_expire_at, off_stored_expire): (Option<i64>, Option<i64>) = observer
            .query_row(
                "SELECT expire_at, expire_start_at FROM messages WHERE id='m-off'",
                [],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!(off_expire_at, None);
        assert_eq!(off_stored_expire, None);
    }

    /// One sweep pass deletes exactly the due rows (deadline at or before the
    /// clock), groups them per conversation, repairs each touched summary's
    /// newest-row projection and the account aggregates, and leaves not-yet-due
    /// and timerless rows alone. A quiet sweep answers empty.
    #[test]
    fn sweep_expired_messages_deletes_due_and_repairs_summaries() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let other = store
            .ensure_conversation(&account.id, "direct", "+15555550102", "contact")
            .unwrap();

        // Due in conversation A, oldest deadline first.
        let mut due_old = expire_record("m-due-old", &account.id, &conversation.id);
        due_old.sent_at = 100;
        due_old.expire_seconds = Some(60);
        due_old.expire_start_at = Some(1_000);
        let mut due_new = expire_record("m-due-new", &account.id, &conversation.id);
        due_new.sent_at = 200;
        due_new.expire_seconds = Some(60);
        due_new.expire_start_at = Some(20_000);
        // Not due: deadline far in the future.
        let mut waiting = expire_record("m-waiting", &account.id, &conversation.id);
        waiting.sent_at = 300;
        waiting.expire_seconds = Some(3_600);
        waiting.expire_start_at = Some(1_000_000_000_000);
        // Timerless: never swept, stays the summary's newest row.
        let mut keeper = expire_record("m-keeper", &account.id, &conversation.id);
        keeper.sent_at = 400;
        keeper.expire_seconds = None;
        // Due in conversation B: one conversation's event stays its own.
        let mut due_b = expire_record("m-due-b", &account.id, &other.id);
        due_b.expire_seconds = Some(1);
        due_b.expire_start_at = Some(1);

        for record in [&due_old, &due_new, &waiting, &keeper, &due_b] {
            assert!(
                store
                    .insert_message(
                        record,
                        None,
                        Some(record.text.as_deref().unwrap_or("")),
                        true
                    )
                    .unwrap()
            );
        }
        // The due rows arrived unread: after the sweep the unread badge may
        // only count what still exists.
        store
            .set_conversation_expire_timer(&account.id, &conversation.id, 60)
            .unwrap();

        let groups = store
            .sweep_expired_messages(1_000_000, EXPIRE_SWEEP_BATCH)
            .unwrap();
        assert_eq!(groups.len(), 2, "one group per touched conversation");
        let group_a = groups
            .iter()
            .find(|group| group.conversation_id == conversation.id)
            .expect("conversation A group");
        assert_eq!(group_a.account_id, account.id);
        assert_eq!(group_a.message_ids, vec!["m-due-old", "m-due-new"]);
        let group_b = groups
            .iter()
            .find(|group| group.conversation_id == other.id)
            .expect("conversation B group");
        assert_eq!(group_b.message_ids, vec!["m-due-b"]);

        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .expect("summary");
        assert_eq!(summary.last_message_at, Some(400));
        assert_eq!(summary.last_message_preview.as_deref(), Some("vanishing"));
        assert_eq!(
            summary.unread_count, 2,
            "unread clamps to the surviving rows"
        );
        assert_eq!(summary.expire_timer_seconds, Some(60));

        let remaining = store
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap();
        let ids: Vec<&str> = remaining.items.iter().map(|row| row.id.as_str()).collect();
        assert_eq!(ids, vec!["m-keeper", "m-waiting"]);

        // The follow-up pass is quiet: nothing else was due.
        assert!(
            store
                .sweep_expired_messages(1_000_000, EXPIRE_SWEEP_BATCH)
                .unwrap()
                .is_empty()
        );
    }

    /// 到期主动擦除（contract 1.218, §29.3）：到期 view-once 行走官方
    /// eraseMessageContents 语义 —— 内容字段清空（body/quote/attachments/
    /// sticker/rich 内容键）、行保留、is_erased=true、身份/时间戳/收据/
    /// timer 元数据保留；普通到期行仍删行（upstream removeMessagesById）；
    /// `message.expired` 分组只含删除行；已擦行不再被任何一路重选；最新行
    /// 被擦后会话 preview 跟着落地（已擦正文不泄露到摘要）。
    #[test]
    fn sweep_erases_due_view_once_rows_and_deletes_the_rest() {
        use crate::engine::{
            NormalizedAttachment, NormalizedPreview, NormalizedQuote, NormalizedRich,
            NormalizedSticker, NormalizedTextStyle,
        };
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();

        // Due view-once row with every content face loaded — also the
        // conversation's newest row, so the erase must pull the preview.
        let mut view_once = expire_record("m-vo-due", &account.id, &conversation.id);
        view_once.sent_at = 300;
        view_once.received_at = Some(150);
        view_once.expire_seconds = Some(60);
        view_once.expire_start_at = Some(1_000);
        view_once.text = Some("erase me secret".into());
        view_once.quote_snapshot = Some(NormalizedQuote {
            id: 42,
            author: "+15555550199".into(),
            text: "quoted secret".into(),
            attachments: Vec::new(),
        });
        view_once.attachments = vec![NormalizedAttachment {
            id: "att-vo-1".into(),
            content_type: Some("image/jpeg".into()),
            filename: Some("snap.jpg".into()),
            size: Some(2048),
            width: Some(64),
            height: Some(32),
            is_voice_note: false,
            caption: None,
            blur_hash: None,
            incremental_mac: None,
            chunk_size: None,
            is_borderless: false,
            is_gif: false,
            locator: None,
            waveform: None,
            duration: None,
        }];
        view_once.sticker = Some(NormalizedSticker {
            pack_id: "abcd".into(),
            pack_key: "a2V5".into(),
            sticker_id: 7,
            emoji: Some("\u{1f389}".into()),
        });
        view_once.rich = Some(NormalizedRich {
            view_once: true,
            previews: vec![NormalizedPreview {
                url: "https://example.net/secret".into(),
                title: Some("secret title".into()),
                description: None,
                date: None,
                image: None,
            }],
            text_styles: vec![NormalizedTextStyle {
                style: "bold".into(),
                start: 0,
                length: 5,
            }],
            ..Default::default()
        });
        // Due plain row: the delete path keeps its upstream face.
        let mut plain = expire_record("m-plain-due", &account.id, &conversation.id);
        plain.sent_at = 200;
        plain.expire_seconds = Some(60);
        plain.expire_start_at = Some(1_000);
        // Not-due view-once row: untouched on both faces.
        let mut waiting = expire_record("m-vo-waiting", &account.id, &conversation.id);
        waiting.sent_at = 100;
        waiting.expire_seconds = Some(3_600);
        waiting.expire_start_at = Some(1_000_000_000_000);
        waiting.rich = Some(NormalizedRich {
            view_once: true,
            ..Default::default()
        });

        for record in [&view_once, &plain, &waiting] {
            assert!(
                store
                    .insert_message(
                        record,
                        None,
                        Some(record.text.as_deref().unwrap_or("")),
                        true
                    )
                    .unwrap()
            );
        }

        let groups = store
            .sweep_expired_messages(1_000_000, EXPIRE_SWEEP_BATCH)
            .unwrap();
        assert_eq!(groups.len(), 1, "only the delete path feeds the groups");
        assert_eq!(groups[0].conversation_id, conversation.id);
        assert_eq!(groups[0].message_ids, vec!["m-plain-due"]);

        let rows = store
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap();
        let by_id: std::collections::HashMap<&str, &_> = rows
            .items
            .iter()
            .map(|row| (row.id.as_str(), row))
            .collect();
        // 行保留（普通行删除）；HashMap 无序，排序后比较。
        let mut surviving: Vec<&str> = by_id.keys().copied().collect();
        surviving.sort_unstable();
        assert_eq!(surviving, vec!["m-vo-due", "m-vo-waiting"]);

        // 官方 eraseMessageContents 语义：内容清空。
        let erased = by_id["m-vo-due"];
        assert!(erased.is_erased, "is_erased sets");
        assert_eq!(erased.text, None);
        assert_eq!(erased.text_bytes, None);
        assert!(erased.quote_snapshot.is_none(), "quote erases");
        assert!(erased.attachments.is_empty(), "attachments erase");
        assert!(erased.sticker.is_none(), "sticker erases");
        let rich = erased.rich.as_ref().expect("rich keeps the view-once face");
        assert!(rich.view_once, "isViewOnce preserves");
        assert!(rich.previews.is_empty(), "preview erases");
        assert!(rich.text_styles.is_empty(), "bodyRanges erase");
        // 官方 preserve 面：时间戳/收据/timer 元数据原样。
        assert_eq!(erased.sent_at, 300);
        assert_eq!(erased.received_at, Some(150));
        assert_eq!(erased.expire_seconds, Some(60));
        assert_eq!(erased.expire_start_at, Some(1_000));

        // 摘要不泄露已擦正文（最新行被擦 → preview 落地）。
        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .expect("summary");
        assert_eq!(
            summary.last_message_preview, None,
            "an erased newest row leaves no preview behind"
        );
        assert_eq!(summary.last_message_at, Some(300));

        // 未到期 view-once 行原样。
        let waiting_row = by_id["m-vo-waiting"];
        assert!(!waiting_row.is_erased);
        assert!(waiting_row.text.is_some());
        assert!(waiting_row.rich.as_ref().unwrap().view_once);

        // 第二遍：已擦行不再被任何一路选中，quiet sweep。
        assert!(
            store
                .sweep_expired_messages(1_000_000, EXPIRE_SWEEP_BATCH)
                .unwrap()
                .is_empty()
        );
        let rows = store
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap();
        let still = rows.items.iter().find(|row| row.id == "m-vo-due").unwrap();
        assert!(still.is_erased);
        assert_eq!(still.text, None);
    }

    /// 契约 1.280（§4.264）：view-once 擦除删 payload 的定位键必须带账号。两个
    /// 账号可以用同一个 clientRequestId 各存一组字节；只有真正被擦除的消息所属
    /// 账号的那一组离开，另一个账号的那一组原样保留（子查询只认消息 id，不认
    /// 账号的话这里会连带删掉对方那一组）。
    #[test]
    fn sweep_erases_view_once_payload_only_for_its_own_account() {
        use crate::engine::NormalizedRich;
        const SHARED_ID: &str = "req-vo-shared";
        const FIRST_URI: &str = "data:image/jpeg;filename=snap.jpg;base64,c25hcA==";
        const SECOND_URI: &str = "data:text/plain;filename=other.txt;base64,b3RoZXI=";
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let first = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let second = store
            .upsert_account_from_signal("+15555550101", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let first_conversation = store
            .ensure_conversation(&first.id, "direct", "+15555550111", "First peer")
            .unwrap();
        let second_conversation = store
            .ensure_conversation(&second.id, "direct", "+15555550112", "Second peer")
            .unwrap();

        // Account one: due now, so the sweep burns its content.
        let mut due = expire_record("m-vo-shared-first", &first.id, &first_conversation.id);
        due.sent_at = 300;
        due.expire_seconds = Some(60);
        due.expire_start_at = Some(1_000);
        due.rich = Some(NormalizedRich {
            view_once: true,
            ..Default::default()
        });
        // Account two: the same idempotency key, not due — its payload must not
        // be collateral damage of the first account's erase.
        let mut waiting = expire_record("m-vo-shared-second", &second.id, &second_conversation.id);
        waiting.sent_at = 300;
        waiting.expire_seconds = Some(60);
        waiting.expire_start_at = Some(1_000_000_000_000);
        waiting.rich = Some(NormalizedRich {
            view_once: true,
            ..Default::default()
        });
        for record in [&due, &waiting] {
            assert!(
                store
                    .insert_message(
                        record,
                        Some(SHARED_ID),
                        Some(record.text.as_deref().unwrap_or("")),
                        true
                    )
                    .unwrap()
            );
        }
        let now = crate::link::now_ms();
        store
            .remember_outgoing_attachment_payload(
                &first.id,
                &first_conversation.id,
                SHARED_ID,
                0,
                FIRST_URI,
                now,
            )
            .unwrap();
        store
            .remember_outgoing_attachment_payload(
                &second.id,
                &second_conversation.id,
                SHARED_ID,
                0,
                SECOND_URI,
                now,
            )
            .unwrap();

        let groups = store
            .sweep_expired_messages(1_000_000, EXPIRE_SWEEP_BATCH)
            .unwrap();
        assert!(groups.is_empty(), "the erase path never feeds the groups");
        assert_eq!(
            store
                .outgoing_attachment_payload(&first.id, SHARED_ID, 0)
                .unwrap(),
            None,
            "the burned view-once row loses its own payload"
        );
        assert_eq!(
            store
                .outgoing_attachment_payload(&second.id, SHARED_ID, 0)
                .unwrap()
                .as_deref(),
            Some(SECOND_URI),
            "the other account's payload under the same clientRequestId survives"
        );
        let erased = store
            .message_by_id(&first.id, &first_conversation.id, "m-vo-shared-first")
            .unwrap()
            .unwrap();
        assert!(erased.is_erased, "the row itself stays as a tombstone");
    }

    /// The conversation timer mirror writes only on real transitions: the
    /// first write reports a change, rewriting the same value reports none,
    /// and an unknown conversation never invents one.
    #[test]
    fn set_conversation_expire_timer_reports_transitions() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();

        assert!(
            store
                .set_conversation_expire_timer(&account.id, &conversation.id, 86400)
                .unwrap()
        );
        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.expire_timer_seconds, Some(86400));

        assert!(
            !store
                .set_conversation_expire_timer(&account.id, &conversation.id, 86400)
                .unwrap()
        );
        assert!(
            store
                .set_conversation_expire_timer(&account.id, &conversation.id, 0)
                .unwrap()
        );
        let summary = store
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.expire_timer_seconds, Some(0));

        assert!(
            !store
                .set_conversation_expire_timer(&account.id, "conv-absent", 60)
                .unwrap()
        );
    }

    // ---- Contract 1.65 (§4.58): message-request receive projection ----

    fn mrr_record(
        id: &str,
        account_id: &str,
        conversation_id: &str,
        direction: &'static str,
        sent_at: u64,
    ) -> MessageRecord {
        MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: id.into(),
            account_id: account_id.into(),
            conversation_id: conversation_id.into(),
            direction,
            sender_id: if direction == "outgoing" {
                "self".into()
            } else {
                "peer".into()
            },
            sender_name: None,
            mentions_self: false,
            sent_at,
            received_at: None,
            text: Some("body".into()),
            text_bytes: Some(4),
            text_truncated: false,
            text_retrievable: true,
            status: "delivered",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        }
    }

