    /// The VIEWED receipt face (contract 1.94, §4.77): it rides the read
    /// ladder and first-stamps `viewed_at` on every eligible row it hits —
    /// moved rows carry the stamp inside `moved`, an already-read unstamped
    /// row surfaces as `viewed_confirmed`, a pure replay produces neither,
    /// and a failed row never takes the stamp. Delivery and read receipts
    /// never stamp `viewed_at`.
    #[test]
    fn viewed_receipt_stamps_viewed_at_through_the_ladder() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        let record = |id: &str, sent_at: u64, status: &'static str| MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: id.into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "outgoing",
            sender_id: "self".into(),
            sender_name: None,
            mentions_self: false,
            sent_at,
            received_at: None,
            text: Some("voice note".into()),
            text_bytes: Some(10),
            text_truncated: false,
            text_retrievable: true,
            status,
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        for (id, sent_at, status) in [
            ("m-400", 400, "sent"),
            ("m-401", 401, "delivered"),
            ("m-402", 402, "sent"),
            ("m-403", 403, "failed"),
        ] {
            let row = record(id, sent_at, status);
            store
                .insert_message(&row, None, row.text.as_deref(), true)
                .unwrap();
        }
        let upgrade = |sent_at: u64, kind, when: u64| {
            store
                .apply_peer_receipt(&account.id, "+15555550101", &[sent_at], kind, when)
                .unwrap()
        };
        let stored = |id: &str| {
            store
                .message_by_id(&account.id, &conversation.id, id)
                .unwrap()
                .unwrap()
        };

        // A read receipt moves and never stamps viewed_at.
        let upgraded = upgrade(400, crate::engine::ReceiptKind::Read, 1000);
        assert_eq!(upgraded.moved.len(), 1);
        assert!(upgraded.viewed_confirmed.is_empty());
        assert_eq!(upgraded.moved[0].status, "read");
        assert_eq!(upgraded.moved[0].viewed_at, None);
        assert_eq!(stored("m-400").viewed_at, None);

        // A delivery receipt that moves nothing stamps nothing either.
        let upgraded = upgrade(401, crate::engine::ReceiptKind::Delivered, 1001);
        assert!(upgraded.moved.is_empty());
        assert!(upgraded.viewed_confirmed.is_empty());
        assert_eq!(stored("m-401").viewed_at, None);

        // m-402 reaches read through a plain read receipt first.
        let upgraded = upgrade(402, crate::engine::ReceiptKind::Read, 1002);
        assert_eq!(upgraded.moved.len(), 1);
        assert_eq!(stored("m-402").status, "read");
        assert_eq!(stored("m-402").read_at, Some(1002));

        // VIEWED on the already-read unstamped row: no status move, the
        // first viewed stamp surfaces as viewed_confirmed.
        let upgraded = upgrade(402, crate::engine::ReceiptKind::Viewed, 2000);
        assert!(upgraded.moved.is_empty());
        assert_eq!(upgraded.viewed_confirmed.len(), 1);
        let confirmed = &upgraded.viewed_confirmed[0];
        assert_eq!(confirmed.status, "read");
        assert_eq!(confirmed.read_at, Some(1002));
        assert_eq!(confirmed.viewed_at, Some(2000));
        assert_eq!(stored("m-402").viewed_at, Some(2000));

        // A pure replay (already read, already stamped) produces neither
        // face and never re-stamps.
        let upgraded = upgrade(402, crate::engine::ReceiptKind::Viewed, 3000);
        assert!(upgraded.moved.is_empty());
        assert!(upgraded.viewed_confirmed.is_empty());
        assert_eq!(stored("m-402").viewed_at, Some(2000), "first stamp wins");

        // A failed row never takes the stamp.
        let upgraded = upgrade(403, crate::engine::ReceiptKind::Viewed, 2001);
        assert!(upgraded.moved.is_empty());
        assert!(upgraded.viewed_confirmed.is_empty());
        assert_eq!(stored("m-403").viewed_at, None);

        // VIEWED on a delivered row rides the ladder to read and stamps
        // inside the moved face.
        let upgraded = upgrade(401, crate::engine::ReceiptKind::Viewed, 2002);
        assert_eq!(upgraded.moved.len(), 1);
        assert!(upgraded.viewed_confirmed.is_empty());
        let moved = &upgraded.moved[0];
        assert_eq!(moved.status, "read");
        assert_eq!(moved.read_at, Some(2002));
        assert_eq!(moved.viewed_at, Some(2002));
        assert_eq!(stored("m-401").viewed_at, Some(2002));

        // And a late VIEWED on the row the plain read receipt moved earlier
        // confirms its viewed stamp too.
        let upgraded = upgrade(400, crate::engine::ReceiptKind::Viewed, 2003);
        assert!(upgraded.moved.is_empty());
        assert_eq!(upgraded.viewed_confirmed.len(), 1);
        assert_eq!(stored("m-400").viewed_at, Some(2003));
    }

    /// Contract 1.190 (§4.190 ②) — the group dead-letter regression: a group
    /// member's receipt finds the GROUP's outgoing row through the
    /// account-level sentAt find, even when the member's own direct
    /// conversation exists and holds no matching row (the pre-1.190 path
    /// resolved the sender's direct conversation and died there), and even
    /// when no roster was ever captured (the engine-mode degraded accept —
    /// refusing would resurrect the dead-letter for every roster-less
    /// group). A known roster that does NOT carry the sender refuses the
    /// stamp (the official getTargetMessage non-recipient skip), and a
    /// foreign sender never touches another conversation's row sharing the
    /// timestamp.
    #[test]
    fn peer_receipt_finds_the_group_row_and_respects_the_roster() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let group = store
            .ensure_conversation(&account.id, "group", "Z3JvdXAta2V5", "Group")
            .unwrap();
        // The member's own direct conversation exists — with its own outgoing
        // row at a DIFFERENT timestamp (the pre-1.190 misroute target).
        let member_direct = store
            .ensure_conversation(&account.id, "direct", "+15555550201", "contact")
            .unwrap();
        let record = |id: &str, conversation_id: &str, sent_at: u64| MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: id.into(),
            account_id: account.id.clone(),
            conversation_id: conversation_id.to_string(),
            direction: "outgoing",
            sender_id: "self".into(),
            sender_name: None,
            mentions_self: false,
            sent_at,
            received_at: None,
            text: Some("group text".into()),
            text_bytes: Some(10),
            text_truncated: false,
            text_retrievable: true,
            status: "sent",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        let group_row = record("m-grp-400", &group.id, 400);
        store
            .insert_message(&group_row, None, group_row.text.as_deref(), true)
            .unwrap();
        let direct_row = record("m-dir-999", &member_direct.id, 999);
        store
            .insert_message(&direct_row, None, direct_row.text.as_deref(), true)
            .unwrap();

        // No roster captured: the degraded accept still finds the group row.
        let outcome = store
            .apply_peer_receipt(
                &account.id,
                "+15555550201",
                &[400],
                crate::engine::ReceiptKind::Delivered,
                1700,
            )
            .unwrap();
        assert_eq!(outcome.moved.len(), 1, "the group row takes the receipt");
        assert_eq!(outcome.moved[0].conversation_id, group.id);
        assert_eq!(outcome.moved[0].status, "delivered");
        assert_eq!(outcome.matched_timestamps, vec![400]);
        assert_eq!(outcome.receipts_changed.len(), 1);
        assert_eq!(outcome.receipts_changed[0].0, "m-grp-400");
        let ledger = store
            .message_receipts_for(&account.id, "m-grp-400")
            .unwrap();
        assert_eq!(ledger.len(), 1);
        assert_eq!(ledger[0].recipient, "+15555550201");
        assert_eq!(ledger[0].delivered_at, Some(1700));
        assert_eq!(ledger[0].read_at, None);
        // The member's own direct row at 999 stays untouched.
        let untouched = store
            .message_by_id(&account.id, &member_direct.id, "m-dir-999")
            .unwrap()
            .unwrap();
        assert_eq!(untouched.status, "sent");

        // A known roster that carries the member keeps accepting; one that
        // does not carry the sender refuses (the non-recipient skip: the row
        // is neither moved nor ledger-stamped, the timestamp reports
        // blocked — it is a message receipt, never a story candidate).
        store
            .upsert_contact(
                &account.id,
                "group",
                "Z3JvdXAta2V5",
                "Group",
                Some(r#"{"members":[{"id":"+15555550301","name":"Other"}]}"#),
                1,
            )
            .unwrap();
        let outcome = store
            .apply_peer_receipt(
                &account.id,
                "+15555550201",
                &[400],
                crate::engine::ReceiptKind::Read,
                1800,
            )
            .unwrap();
        assert!(
            outcome.moved.is_empty(),
            "a non-member's receipt is skipped"
        );
        assert!(outcome.receipts_changed.is_empty());
        assert_eq!(outcome.blocked_timestamps, vec![400]);
        let ledger = store
            .message_receipts_for(&account.id, "m-grp-400")
            .unwrap();
        assert_eq!(ledger.len(), 1, "no second ledger row for a non-member");
        assert_eq!(ledger[0].read_at, None, "no read stamp for a non-member");
        let row = store
            .message_by_id(&account.id, &group.id, "m-grp-400")
            .unwrap()
            .unwrap();
        assert_eq!(
            row.status, "delivered",
            "the ladder never moved past delivered"
        );

        // The roster member the capture names qualifies (uuid arm too).
        store
            .upsert_contact(
                &account.id,
                "group",
                "Z3JvdXAta2V5",
                "Group",
                Some(r#"{"members":[{"id":"+15555550301","uuid":"11111111-1111-1111-1111-111111111111"}]}"#),
                2,
            )
            .unwrap();
        let outcome = store
            .apply_peer_receipt(
                &account.id,
                "11111111-1111-1111-1111-111111111111",
                &[400],
                crate::engine::ReceiptKind::Read,
                1900,
            )
            .unwrap();
        assert_eq!(outcome.moved.len(), 1, "the uuid-form member qualifies");
        assert_eq!(outcome.moved[0].status, "read");
        assert_eq!(outcome.matched_timestamps, vec![400]);
    }

    /// Contract 1.190 (§4.190 ②): direct rows qualify through the §4.144
    /// identity ladder — the recipient spelled by ACI still stamps the
    /// phone-keyed conversation (peer_identities), the alternate phone
    /// spelling matches, and a receipt from an unrelated peer never touches
    /// the row (the cross-talk guard for two conversations sharing a
    /// timestamp).
    #[test]
    fn peer_receipt_qualifies_direct_rows_through_the_identity_ladder() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "direct", "+15555550101", "contact")
            .unwrap();
        // A second direct conversation whose outgoing row SHARES the
        // timestamp — the cross-talk probe.
        let other = store
            .ensure_conversation(&account.id, "direct", "+15555550303", "contact")
            .unwrap();
        let record = |id: &str, conversation_id: &str| MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: id.into(),
            account_id: account.id.clone(),
            conversation_id: conversation_id.to_string(),
            direction: "outgoing",
            sender_id: "self".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: 500,
            received_at: None,
            text: Some("shared timestamp".into()),
            text_bytes: Some(16),
            text_truncated: false,
            text_retrievable: true,
            status: "sent",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        let mine = record("m-mine-500", &conversation.id);
        store
            .insert_message(&mine, None, mine.text.as_deref(), true)
            .unwrap();
        let theirs = record("m-theirs-500", &other.id);
        store
            .insert_message(&theirs, None, theirs.text.as_deref(), true)
            .unwrap();

        // The peer's ACI, recorded by a past envelope, stamps the
        // phone-keyed conversation.
        store
            .upsert_peer_identity(
                &account.id,
                "22222222-2222-2222-2222-222222222222",
                "+15555550101",
            )
            .unwrap();
        let outcome = store
            .apply_peer_receipt(
                &account.id,
                "22222222-2222-2222-2222-222222222222",
                &[500],
                crate::engine::ReceiptKind::Read,
                2100,
            )
            .unwrap();
        assert_eq!(outcome.moved.len(), 1);
        assert_eq!(outcome.moved[0].id, "m-mine-500");
        assert_eq!(outcome.moved[0].status, "read");

        // The alternate phone spelling matches too.
        let outcome = store
            .apply_peer_receipt(
                &account.id,
                "15555550101",
                &[500],
                crate::engine::ReceiptKind::Viewed,
                2200,
            )
            .unwrap();
        assert_eq!(outcome.viewed_confirmed.len(), 1);
        assert_eq!(outcome.viewed_confirmed[0].id, "m-mine-500");

        // The other conversation's row with the SAME timestamp is never
        // touched by this peer's receipts.
        let foreign = store
            .message_by_id(&account.id, &other.id, "m-theirs-500")
            .unwrap()
            .unwrap();
        assert_eq!(foreign.status, "sent");
        assert!(
            store
                .message_receipts_for(&account.id, "m-theirs-500")
                .unwrap()
                .is_empty()
        );
    }

    /// Contract 1.190 (§4.190 ①): the ledger's first stamps are COALESCE
    /// monotonic per recipient (a replay never re-stamps and never answers a
    /// changed face), the rows cascade with their message (retention deletes
    /// the ledger with the row), and the read face answers account-scoped
    /// and recipient-sorted. The two-recipient ledger rides a GROUP row — a
    /// direct conversation's ladder takes receipts from its own peer only
    /// (the qualification test's own ruling).
    #[test]
    fn message_receipts_first_stamp_replay_and_cascade() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "group", "Z3JvdXAta2V5", "Group")
            .unwrap();
        let record = MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: "m-cascade-600".into(),
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            direction: "outgoing",
            sender_id: "self".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: 600,
            received_at: None,
            text: Some("cascade".into()),
            text_bytes: Some(7),
            text_truncated: false,
            text_retrievable: true,
            status: "sent",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        store
            .insert_message(&record, None, record.text.as_deref(), true)
            .unwrap();

        let apply = |recipient: &str, kind, when: u64| {
            store
                .apply_peer_receipt(&account.id, recipient, &[600], kind, when)
                .unwrap()
        };
        let first = apply("+15555550101", crate::engine::ReceiptKind::Delivered, 2300);
        assert_eq!(first.receipts_changed.len(), 1);
        // A replay answers nothing — not even a changed face.
        let replay = apply("+15555550101", crate::engine::ReceiptKind::Delivered, 9999);
        assert!(replay.receipts_changed.is_empty());
        assert!(replay.moved.is_empty());
        let ledger = store
            .message_receipts_for(&account.id, "m-cascade-600")
            .unwrap();
        assert_eq!(ledger.len(), 1);
        assert_eq!(ledger[0].delivered_at, Some(2300), "first stamp wins");

        // A second recipient lands its own ledger row; the read face is
        // recipient-sorted.
        let _ = apply("+15555550102", crate::engine::ReceiptKind::Delivered, 2301);
        let ledger = store
            .message_receipts_for(&account.id, "m-cascade-600")
            .unwrap();
        assert_eq!(
            ledger
                .iter()
                .map(|row| row.recipient.as_str())
                .collect::<Vec<_>>(),
            vec!["+15555550101", "+15555550102"],
            "recipient-sorted read face"
        );

        // Deleting the message row cascades the ledger with it (the FK the
        // retention sweep's DELETE rides — no orphan ledger rows survive
        // their row).
        store
            .conn()
            .execute("DELETE FROM messages WHERE id='m-cascade-600'", [])
            .unwrap();
        assert!(
            store
                .message_receipts_for(&account.id, "m-cascade-600")
                .unwrap()
                .is_empty()
        );
    }

    /// Contract 1.190 (§4.190 ⑦): the send-settlement seeds expand the
    /// counted outcomes into per-recipient Sent/Failed ledger rows — first
    /// stamp wins against a receipt that raced the settlement, and the
    /// recipient ceiling bounds the ledger (the roster cap).
    #[test]
    fn send_seeds_expand_receipt_rows_with_first_stamp_and_cap() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let group = store
            .ensure_conversation(&account.id, "group", "Z3JvdXAta2V5", "Group")
            .unwrap();
        let record = MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: "m-seed-700".into(),
            account_id: account.id.clone(),
            conversation_id: group.id.clone(),
            direction: "outgoing",
            sender_id: "self".into(),
            sender_name: None,
            mentions_self: false,
            sent_at: 700,
            received_at: None,
            text: Some("group send".into()),
            text_bytes: Some(10),
            text_truncated: false,
            text_retrievable: true,
            status: "sent",
            client_request_id: None,
            quote_message_id: None,
            quote_snapshot: None,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            edited_at: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            admin_deleted: false,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        store
            .insert_message(&record, None, record.text.as_deref(), true)
            .unwrap();

        // A delivery receipt that raced the settlement lands first.
        store
            .apply_peer_receipt(
                &account.id,
                "+15555550201",
                &[700],
                crate::engine::ReceiptKind::Delivered,
                2400,
            )
            .unwrap();
        // The settlement seeds the full roster: the raced recipient keeps
        // its delivered stamp, the seed never clobbers it.
        let seeds = vec![
            crate::store::SendReceiptSeed {
                recipient: "+15555550201".into(),
                succeeded: true,
            },
            crate::store::SendReceiptSeed {
                recipient: "+15555550202".into(),
                succeeded: true,
            },
            crate::store::SendReceiptSeed {
                recipient: "+15555550203".into(),
                succeeded: false,
            },
        ];
        let seeded_account = store
            .seed_send_receipts("m-seed-700", &seeds, 2500)
            .unwrap();
        assert_eq!(seeded_account.as_deref(), Some(account.id.as_str()));
        let ledger = store
            .message_receipts_for(&account.id, "m-seed-700")
            .unwrap();
        assert_eq!(ledger.len(), 3);
        let raced = ledger
            .iter()
            .find(|row| row.recipient == "+15555550201")
            .unwrap();
        assert_eq!(
            raced.delivered_at,
            Some(2400),
            "the raced receipt keeps its stamp"
        );
        assert_eq!(raced.sent_at, Some(2500));
        let failed = ledger
            .iter()
            .find(|row| row.recipient == "+15555550203")
            .unwrap();
        assert_eq!(failed.sent_at, None);
        assert_eq!(failed.failed_at, Some(2500));

        // The recipient ceiling: a ledger at the cap refuses new rows
        // (warn-free, the roster bound) while existing rows still update.
        let current: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM message_receipts WHERE message_id='m-seed-700'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        for index in 0..(MAX_MESSAGE_RECEIPT_RECIPIENTS - current) {
            store
                .conn()
                .execute(
                    "INSERT INTO message_receipts(message_id, recipient, updated_at)
                     VALUES('m-seed-700', ?1, 2600)",
                    params![format!("cap-{index:04}")],
                )
                .unwrap();
        }
        let over = vec![crate::store::SendReceiptSeed {
            recipient: "+15555559999".into(),
            succeeded: true,
        }];
        store.seed_send_receipts("m-seed-700", &over, 2700).unwrap();
        let ledger = store
            .message_receipts_for(&account.id, "m-seed-700")
            .unwrap();
        assert_eq!(
            ledger.len() as i64,
            MAX_MESSAGE_RECEIPT_RECIPIENTS,
            "the cap refuses the new recipient row"
        );
        assert!(ledger.iter().all(|row| row.recipient != "+15555559999"));
        // The existing raced row still takes its update inside the cap.
        store
            .seed_send_receipts(
                "m-seed-700",
                &[crate::store::SendReceiptSeed {
                    recipient: "+15555550202".into(),
                    succeeded: false,
                }],
                2800,
            )
            .unwrap();
        let ledger = store
            .message_receipts_for(&account.id, "m-seed-700")
            .unwrap();
        let second = ledger
            .iter()
            .find(|row| row.recipient == "+15555550202")
            .unwrap();
        assert_eq!(
            second.sent_at,
            Some(2500),
            "existing seed stamps never clobber"
        );
        assert_eq!(second.failed_at, Some(2800), "the missing tier still lands");
    }

    /// Contract 1.190 (§4.190 ⑥): the mirrored readReceipts flag persists
    /// and clears — the gate's local input, three writers' shared landing.
    #[test]
    fn account_read_receipts_flag_persists_and_clears() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550100", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(store.account_read_receipts(&account.id).unwrap(), None);
        store
            .set_account_read_receipts(&account.id, Some(true))
            .unwrap();
        assert_eq!(
            store.account_read_receipts(&account.id).unwrap(),
            Some(true)
        );
        store
            .set_account_read_receipts(&account.id, Some(false))
            .unwrap();
        assert_eq!(
            store.account_read_receipts(&account.id).unwrap(),
            Some(false)
        );
        store.set_account_read_receipts(&account.id, None).unwrap();
        assert_eq!(
            store.account_read_receipts(&account.id).unwrap(),
            None,
            "a sync that states no flag never invents one"
        );
    }

    /// Engine-pool design §5.3: the per-account slot fixes the opaque
    /// account id before the link finishes, so the first commit must insert
    /// the row under that id. A re-sync of the same number keeps the existing
    /// row and never renames it (the binding/identity is immutable).
    #[test]
    fn upsert_honors_a_preallocated_account_id_and_never_renames_a_row() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let reserved = "0123456789abcdef0123456789abcdef";
        let account = store
            .upsert_account_from_signal_with_id(
                "+15555550177",
                Some(7),
                DEFAULT_PROXY_GROUP_ID,
                Some(reserved),
            )
            .unwrap();
        assert_eq!(account.id, reserved);
        assert_eq!(account.proxy_group, DEFAULT_PROXY_GROUP_ID);

        // A later plain sync of the same number updates that row in place.
        let again = store
            .upsert_account_from_signal("+15555550177", None, DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(again.id, reserved);

        // The plain form still mints a fresh opaque id for a new number.
        let other = store
            .upsert_account_from_signal("+15555550178", Some(8), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_ne!(other.id, reserved);
        assert_eq!(other.id.len(), 32);
    }

    #[test]
    fn upsert_is_atomic_when_finish_link_and_receive_race() {
        let temp = TempDir::new().unwrap();
        let store = std::sync::Arc::new(Store::open(temp.path(), Some(test_store_key())).unwrap());
        let mut workers = Vec::new();
        for _ in 0..8 {
            let store = std::sync::Arc::clone(&store);
            workers.push(std::thread::spawn(move || {
                store.upsert_account_from_signal_with_id(
                    "+15555550179",
                    Some(9),
                    DEFAULT_PROXY_GROUP_ID,
                    Some("fedcba9876543210fedcba9876543210"),
                )
            }));
        }
        for worker in workers {
            worker
                .join()
                .expect("upsert worker does not panic")
                .expect("concurrent upsert succeeds");
        }
        let accounts = store.list_accounts().unwrap();
        assert_eq!(
            accounts.len(),
            1,
            "并发 upsert 不得产生唯一键失败或重复账号"
        );
        assert_eq!(accounts[0].id, "fedcba9876543210fedcba9876543210");
    }

    /// `stamp_incoming_viewed` (contract 1.94, §4.77): the local
    /// markViewed half — first stamp wins, only incoming rows qualify, the
    /// selection is exactly the given ids.
    #[test]
    fn backfill_recovers_legacy_group_author_aci_from_sender_hash() {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(test_store_key())).unwrap();
        let account = store
            .upsert_account_from_signal("+15555550182", Some(1), DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = store
            .ensure_conversation(&account.id, "group", "Z3JvdXAtYXV0aA==", "Group")
            .unwrap();
        seed_retry_row(
            &store,
            &account.id,
            &conversation.id,
            "m-author",
            "client-author",
            "sent",
            None,
            0,
            None,
        );
        let aci = "c3b07a1e-55cc-4a44-9e11-8a2b3c4d5e6f";
        let hash = stable_hash_id(&[&account.id, "group", aci]);
        store
            .conn()
            .execute(
                "UPDATE messages SET direction='incoming', sender_id=?1, author_aci=NULL
                 WHERE id='m-author'",
                params![hash],
            )
            .unwrap();
        store
            .conn()
            .execute(
                "INSERT INTO contacts(id, account_id, kind, peer_key, title, extra, synced_at)
                 VALUES('contact-author', ?1, 'contact', ?2, 'Peer', NULL, 1)",
                params![account.id, aci],
            )
            .unwrap();

        let changed = store.backfill_incoming_author_aci().unwrap();
        assert_eq!(changed, 1);
        let row = store
            .message_by_id(&account.id, &conversation.id, "m-author")
            .unwrap()
            .unwrap();
        assert_eq!(row.author_aci.as_deref(), Some(aci));
    }

